/* 平成20年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h20.committeeSessions.push(...[{"id":"h20-20081106-5","meetingId":"h20-cm11","date":"2008年11月6日","dateIso":"2008-11-06","committee":"総務委員会","time":"午後１時０３分～午後４時０８分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を63件抜き出しています。","topics":[{"id":"topic-01","title":"の品川区長期基本計画の策定状況","agenda":"の品川区長期基本計画の策定状況","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"現在、パブリックコメントは何件ぐらい来ているのか、状況を教えていただきたいと思います。それから、パブリックコメントを受けて策定委員会を１２月２日に予定されているようですけれども、最終回の中でパブリックコメントのさまざまな意見が反映されていくのだろうと思っていますけれども、その辺についての考え方というか、予定を教えてください。","respondent":"福島長期計画担当課長","answer":"パブリックコメントを受けた後の策定委員会での審議ですけれども、こちらの内容を整理いたしまして、委員の皆様にお示しし、これをどのように反映していくかご審議をいただくという形で進めてまいります。","id":"exchange-001"},{"speaker":"南委員","kind":"質問","question":"３週間あるので、事務的にはそういうものがあるかなと思ったので、その辺を伺ったんです。もう一つは、パブリックコメントを受けて、やはり区民の方々に直接お示しをしてご意見をいただく場面を、これからやっていくべきではないかと思っているんです。その辺についての考え方はどうでしょうか。","respondent":"福島長期計画担当課長","answer":"説明会等ですけれども、品川区長期基本計画の素案ができた段階、また素案から実際に３月には公表する予定ですけれども、それができた段階で、さまざまな形で区民にお示しし、またどのように実証していくかということについてご意見をいただく予定です。","id":"exchange-002"},{"speaker":"南委員","kind":"確認","question":"今の答弁の最後の部分ですけれども、３月に説明をするということは、区民の皆さんには「このように決めました」ということを提示するということなのかと思うんですけれども、その辺の確認と私が説明会と質問したのは、区民のパブリックコメントをいただき、何回かにわたる策定委員会で策定し、さまざまな形で今まで意見をいただいてきたんですけれども。","respondent":"福島長期計画担当課長","answer":"３月には決まったものを公表するというものです。それを公表し、また決まったものについてご意見をいただくというものです。素案は策定委員会から区のほうに答申としていただきますので、それをもって区民の方に説明会を開くということは予定してございません。","id":"exchange-003"},{"speaker":"南委員","kind":"質問・要望","question":"私が聞きたいのは、いろいろな方々からのご意見を受けとめておつくりになった計画を示す前に、これからの品川区の方向性を示す素案に対して、新たに説明をして意見を求めることが必要ではないかと言っているわけで、以前と以後との関係で全然違うわけです。ですから、改めてもう１回、なぜ区民に方向が決まる前の段階で意見を求めることをしないのか、その理由を教えてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"南委員","kind":"質問・要望","question":"ですから、パブリックコメントのことを言っているわけではないんです。ですから、パブリックコメント以降の新たに策定委員会でご議論をいただいて、答申を受けたそのものについて、品川区として今後１０年、２０年のスパンで区政運営をしていきます、こういう方向でやっていきたいと思いますけれども、いいでしょうか、新たなご意見があったら出してくださいということを聞くべきだと思っているんです。","respondent":"福島長期計画担当課長","answer":"策定委員会でご審議いただくということは、区民の意見を聞くということの一つでもあると考えていますし、そこで決まった素案を区にいただきまして、それをまたさらにパブリックコメント的なことあるいは説明会を開いて意見を聞きますと。","id":"exchange-005"},{"speaker":"南委員","kind":"質問","question":"角度を変えて、３月に決まったものを公開した後に区民からいただいた意見は受けとめていくという答弁がありました。それはどういう扱いに受けとめて、品川区長期基本計画に取り入れることになっていくんですか。品川区長期基本計画にどういう形で反映されていくんでしょうか。公開後に開く場面というのは、どういう性格の会議なんですか。","respondent":"福島長期計画担当課長","answer":"説明会を行うか、あるいはパンフレットにして配るか、どういう形でＰＲしていくか、区民の方にお示しするか、それは今後検討したいと考えています。","id":"exchange-006"},{"speaker":"南委員","kind":"質問・要望","question":"その思いが答弁を聞いていると、似ているようで違うような、似ているのであれば、私が言っている説明会を受けとめて、そういう方向で考えていますと言ってもいいと思うけれども、そういうふうに言わないということは違うところだなと思うので、それでこんなに長くなってしまって恐縮ですけれども、ぜひ私は区民の皆さんが参加しやすいように。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"林委員","kind":"確認","question":"今のお話は、３ページから５ページに書いてあるから読むといいと思うんです。確認をしたいんですけれども、構想ができて、今長期基本計画をつくっている。今年度中に書き上げるという計画をお話しされています。平成２０年度は第三次長期基本計画に基づいて区は動いている。そこを確認したいんですけれども、それでいいですか。","respondent":"福島長期計画担当課長","answer":"第三次長期基本計画に基づいて行っております。","id":"exchange-008"},{"speaker":"林委員","kind":"質問","question":"これが３月に発表されるというと、平成２１年度は何に基づいて区は計画を行うんですか。","respondent":"福島長期計画担当課長","answer":"平成２１年度は新しい基本計画の始まりの年と考えています。","id":"exchange-009"},{"speaker":"林委員","kind":"意見","question":"これにはそこをうたっていないんですね。これから手が入ってくるんだろうけれども、平成２１年度からやるわけですね。これに基づいて総合実施計画がつくられるわけだけれども、そうすると総合実施計画というのは２年に一遍やっていくことになるわけだけれども、ここに書かれている「５年を目途に」ということと、総合実施計画はどういう整合性を持たせるのか。","respondent":"福島長期計画担当課長","answer":"総合実施計画との整合性ですけれども、総合実施計画自体は３年計画でつくりますが、３年ごとに見直しをしていくものでございまして、５年経った時点で、本計画である長期基本計画の改定が必要だということであれば。","id":"exchange-010"},{"speaker":"林委員","kind":"質問","question":"「行います」と明白にうたっていいのかなという気がしてならない。なおかつ、来年の３月にこれが公表されるときに、総合実施計画は一緒に公表するんですか。","respondent":"福島長期計画担当課長","answer":"総合実施計画も一緒に公表する予定です。","id":"exchange-011"},{"speaker":"林委員","kind":"質問","question":"そうすると、総合実施計画はいつくるのですか。そうすると、長期基本計画と総合実施計画を一緒に３月に出して、職員の人たちに３月の時点で新しい総合実施計画はこれだと出して、急に職員の人たちに「さあ、やれ」ということが可能なのかどうか。先ほどの話とは別ですよ。特に、総合実施計画については、財政上、予算上の話も入ってきているはずでしょうから、その辺もひっくるめてやっているんですか。","respondent":"福田企画部長","answer":"今、平成２０年度の上半期が終わったところですが、我々はこの時期になりますと、翌年度に向けてのさまざまな準備的な検討を行います。その一つが、予算の検討ですとか、最終的には区長査定というようなスケジュールが動いております。","id":"exchange-012"},{"speaker":"林委員","kind":"質問","question":"第三次長期計画のときに私も委員会に関わらせていただきましたけれども、いわゆる自治体の中の弊害と言ったら語弊があるかもしれませんが、縦割りはだめですよ、横に串が刺されて、いろいろな課あるいは係が事業について積極的に協力し合う仕組みを、品川区自治体の中では取り上げていますという絵もつくられていたんだけれども、今までの反省、横串がなかなか刺さりづらいというところまで。","respondent":"福田企画部長","answer":"そのことを解決する一つの場所といたしましては、職員の研修もありますけれども、これからご報告をする組織上の問題として十分に検討してまいりましたし、具体的に組織を運営する中でも、さらに具体的に詰めてまいりたいと考えております。","id":"exchange-013"},{"speaker":"林委員","kind":"質問・要望","question":"これがここまで進んでくると、総合実施計画が頭をもたげて、来年度のいろいろな手順を考えなければいけないし、経営者会議でもそれが出てくるはずだと思うので、あくまでも新しい品川区の実際の職員の働き方にもメスを入れておくべきだろうと思っていますので、この後の三、四カ月ぐらいは、そういうところにも気を配りながら体制づくりをしていただきたいと思っていますので、お願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"}]},{"id":"topic-02","title":"の平成２１年度組織改正の検討状況","agenda":"の平成２１年度組織改正の検討状況","exchanges":[{"speaker":"南委員","kind":"質問","question":"そのようになってきていないのが残念だということを指摘しておきたいと思います。それから、保育園のところですけれども、新しい課は三つということで、名称がまた新たに変えたという説明でしたけれども、青少年育成課、子育て支援課、保育課、それぞれどういう所管事務でしょうか、所管事務の中身を伺いたいと思います。","respondent":"福島長期計画担当課長","answer":"今回の組織改正にあたりましては、なるべく組織名称と所管するものが一致するように、またわかりやすいようにということで検討してまいりました。青少年育成課につきましては、主に青少年の健全育成について行っていく課です。","id":"exchange-015"},{"speaker":"南委員","kind":"質問・要望","question":"「さけび」を見ると三つの地域の保育園を３課に分割していくと書いてあるんですけれども、これはどういうことなのか説明していただきたいと思うんです。これを読んだ限りでは、全然わからないので、どういうふうになるのでしょうか。","respondent":"福島長期計画担当課長","answer":"３課の運営方法ですけれども、保育園につきましては三つの課に地域ごとに分かれまして運営するという形で検討しています。","id":"exchange-016"},{"speaker":"南委員","kind":"質問","question":"先ほど聞いた保育課としての所管事務というのは、保育園の運営という説明をされて、地域を三つに分けるということで、例えば青少年育成課の所管事務は青少年の健全育成だという説明しながら、保育園の運営も担当するということになるんですか。","respondent":"福島長期計画担当課長","answer":"そのとおりです。","id":"exchange-017"},{"speaker":"南委員","kind":"質問","question":"したがって、同じサービス水準を提供しなければいけないのに、三つの課に分けていくことになると、そこが担保されていくのでしょうか、そういう心配を感じたんです。ですから、三つに分けるということは、どういうことなのかと思って聞いたんです。そういうことについては、組織改正をするという方針を立てられたトップのところで、どういうふうに思っているのか説明を伺いたいと思います。","respondent":"福島長期計画担当課長","answer":"一つの課で４０近くの保育園を同じにもっていくというのは、かなり厳しい面もあります。そういう意味では、３人の課長が保育園を持つことによりまして、保育水準を上げていきたいと考えているものです。","id":"exchange-018"},{"speaker":"南委員","kind":"質問・要望","question":"この間に数十年にわたって保育行政をしてきました。今まで問題があったんですか。しかし、やっていく中で、問題が出てきたら困ると思うので、今まで出てきていたわけではないと思っているし、だから分ける必要はないのではないかと思うし、出てきているのであれば、どういう事実があったのか、変える必要性がそこにあったということがあれば説明していただきたいと思います。","respondent":"福島長期計画担当課長","answer":"したがいまして、より地域の特性を活かした事業運営ができるのではないか。今後は町会・自治会との連携も必要になってくるかと思われますので、職員も含め地域に入っていくことが大切だと考えておりますので、地域割の必要性を感じたところです。","id":"exchange-019"},{"speaker":"南委員","kind":"質問・要望","question":"やめるべきだと思います。それから、保健所の関係ですけれども、保健所の位置づけが過去の委員会の説明では、サービス業務は三つの既存の施設で行っていくけれども、保健所の中心的な機能部分は本庁に入っていただいて、そこで業務を行っていくという説明でしたけれども、本庁に来る職員あるいは管理職というのは、どういう部分が本庁に来るのでしょうか、まずそれを教えていただきたいと思います。","respondent":"福島長期計画担当課長","answer":"今回、組織改正によりまして、三つの課で３人体制になりますので、量としましては今までと同じですけれども、それをより手厚く３人で行っていくことになりますし、また幅広い青少年の健全育成という視点も加わってまいりますので。","id":"exchange-020"},{"speaker":"南委員","kind":"質問・要望","question":"この点についても、やはり企画財政課のところに専門的な取り組みの状況について説明を求めるのは申し訳ないと思っているんですけれども、だからこそそれぞれの常任委員会に振り分けて意見を聞く体制が取られてしかるべきではないかと思うんですけれども、あえて総務委員会でこの問題が出されて、ほかでは出されていないので聞かなければいけないと思って聞きたいと思います。","respondent":"福島長期計画担当課長","answer":"特に、今後予想されています新型インフルエンザですとか、あるいは昨今の食の安全ですとか、迅速な態勢を取らなければならないときに、地域が二つに分かれているとなかなかそういった態勢が取りにくいということもございましたので、今回本庁に集中化することによりまして。","id":"exchange-021"},{"speaker":"南委員","kind":"質問・要望","question":"現場のところでは、先ほど私が紹介したような心配をする声があると受けとめたんです。したがって、その辺がどういうふうに検討されてきているのかというのは、今の説明では「ああ、そうか」とならないんです。そういう役割を果たしていかないと思うんです。もう一度、私の意見に対してどういうふうに考えておられるのか聞きたいし、ぜひ受けとめていただきたいということを強くお願いしたいと思います。","respondent":"福島長期計画担当課長","answer":"職員の声をですけれども、最初に総務委員会にご報告させていただきました８月２５日から２カ月経ってあります。","id":"exchange-022"},{"speaker":"南委員","kind":"質問・要望","question":"したがって、先ほども言ったように、きちんとした組織、効率的な組織運営ができるようにするには、組織改正について議会と協力がなければできないことですし、それがなければ区民サービスがうまく進んでいかないですから、そこはしっかりと職員の方々の意見を聞いて、どういう組織が一番いいのかということを大事にして対応していただきたいということを強くお願いして終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"須貝委員","kind":"質問・要望","question":"一般の区民にとって、３ページに水とみどりの課がありますけれども、これだけで一般の人がわかるのかなと。今後、どういう方向で決まっていくかわかりませんが、２ページ目に協働・国際担当がありますが、品川区は国際ということを前面に出して予算づけしてありますが、このように表に出していいものかどうかというのは疑問に思うんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"土井委員","kind":"質問・要望","question":"これとこれがあなたの仕事です」ということがきちんと命令がいくようになっていて、そしてきちんと仕事をしてもらえば、名前はどうでもいいと思うんだけれども、それはわかりいいほうがいいし、間違えないほうがいいということなので、数文字で書く名前ですから、記号みたいになってしまっては仕方ないわけで、その意味では一定の整理がされたのだろうと。申し上げておきたいと思います。意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"林委員","kind":"質問・要望","question":"最初に確認をさせていただきたいんだけれども、３ページの一番下にある「８部１室３事務局２所」ですけれども、８部というのは事業部、１室というのは会計管理室、３事務局というのは教育委員会事務局、選挙管理委員会事務局、監査委員事務局の３事務局ですから、区議会事務局という名称がはっきりここに使われているので４事務局になりますが、それはどういう扱いになりますか。","respondent":"福島長期計画担当課長","answer":"８部というのは、教育委員会事務局も一つの部として考えてとらえておりますので、こういう表現をしています。ですから、３事務局というのは区議会事務局、選挙管理委員会事務局、監査委員事務局のことです。２所につきましては、清掃事務所と保健所です。","id":"exchange-026"},{"speaker":"林委員","kind":"質問","question":"教育委員会は部なんですか。教育部というふうにとらえるわけですか。そうすると、教育長というのは部長と同じと我々は考えておくべきですか、その辺、もう１回だけ答えてください。","respondent":"福島長期計画担当課長","answer":"こちらの部という扱いをしていますけれども、本来ですと確かに事務局という名称ですけれども、今まで品川区では一つの事業部という名称で、例えば事業部経営会議におきましても、ほかの事業部長と同列に会議等を進めているですので。","id":"exchange-027"},{"speaker":"林委員","kind":"質問・要望","question":"教育次長が部長にあたるわけですか、そういうとらえ方をしないといけないのか、今の説明で考え方はそれぞれがあるだろうからとらえておきます。もう一つは、最大の不満が住宅課をなぜなくしたのか。問題があるところを切ってしまうという形に見えるので、そこについてご説明をいただきたい。同じように防災まちづくり事業部、防災まちづくりという一つの言葉というのはあるんですか。","respondent":"福島長期計画担当課長","answer":"都市環境事業部につきましても、同じように都市整備を行っていくところですので、二つの部につきましては特に連携しながら進めていくという形で、全体で区のまちづくりを進めていくというように考えております。","id":"exchange-028"},{"speaker":"林委員","kind":"質問","question":"３ページの上の右側二つは連携をするということでわかりました。住宅はわかりました。教育委員会の認識という問題も一つの組織としてあるし、簡単にうちのところでやってしまおうと計画を立ててやれる問題と教育委員会に伺わないとやれない問題とかいろいろなものが出てくると思うんだけれども、その辺の受け皿の体制について聞かせていただけますか。","respondent":"福島長期計画担当課長","answer":"生涯学習課をなくすですが、教育委員会からはなくなりますけれども、区長部局のほうでしっかり行っていきたいと考えております。教育委員会にも意見を伺ったところ、教育委員会の皆様にも十分理解していただき、また賛成というご意見をいただいているところです。","id":"exchange-029"},{"speaker":"林委員","kind":"質問","question":"最後にします。名称を変え、いろいろなくくりというか、担当というか、そういうものが変わっていくんだけれども、庁舎内の場所ももちろん考えていらっしゃるのだろうと思うんですけれども、大幅に変わるんですか。","respondent":"福島長期計画担当課長","answer":"事業部が変わりますので、第４回定例会で条例提案させていただきまして、それを受けた後になりますけれども、事前に来週あたりからレイアウト委員会を開きまして、職員の意見等を聞きながら、どういうレイアウトにするか、特に保健所部門が入ってきますので。","id":"exchange-030"},{"speaker":"伊藤委員","kind":"質問","question":"先の話ですけれども、これを改正して、条例が仮に可決した後の話ですけれども、当然区民にＰＲしなければいけないわけですから、相当の作業が必要と思われるわけですので、まずどういうふうに考えているかということ。例えば、広報紙に載せるとか、ホームページに載せるということを考えているのでしょうけれども、それだけでは不十分なぐらいに変わっていくわけです。","respondent":"福島長期計画担当課長","answer":"当然ながら、広報しながわ、ホームページ、あとはチラシをつくりまして案内をしていきたいと思っています。同時に、４月からは表示板も変えながら、来た方にわかりやすいもの、すぐに目的のところに行けるように、案内板の整備も進めてまいりたいと考えています。","id":"exchange-031"},{"speaker":"伊藤委員","kind":"質問","question":"品川区の組織改正をしたわけですから、それを今度は能動的に伝えるべきだと私は思うわけです。例えば、毎月来るとか、そういうわけだから、そういう方に対して機会があるではないですか。例えば、表現はいろいろ考えなければいけないけれども、こういう予定でありますとか、もっと戦略的な広報をしてはどうですかと思いますので、もう少し答弁をお願いいたします。","respondent":"福島長期計画担当課長","answer":"１２月に議決いただいた後ですけれども、１月、２月、３月と確かに戦略的に進めていかなければならないと考えていますので、さまざまな手法を用いて行っていきたいと考えています。","id":"exchange-032"},{"speaker":"土井委員","kind":"質問・要望","question":"決まりましたらということですけれども、決まる段階でも、今までに例えば町会・自治会等の皆さんからいろいろな形でご意見が出てきたものが、ここにつながっているのだろうと思いますけれども、意見は多種多様でしょうから、ぜひこうなったよというものをしっかり伝えていただきたい。まちの方々がぶつぶつといつまでも続くと、あまり面白くないことが多いものですから、ぜひお願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"金野委員","kind":"質問・要望","question":"要望です。先ほど、これから庁内の配置をレイアウトするということで、今まで相談事がある場合、例えばは２階で受けた問題が、また違う階だったとかという、課を渡り歩くような事例があります。エレベーターもありますけれども、やはり入り口に近いほうがという声を聞いたりしますので、そのようなこともぜひ検討していただいてレイアウトを考えていただければと、これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"}]},{"id":"topic-03","title":"の特別区人事委員会勧告の概要","agenda":"の特別区人事委員会勧告の概要","exchanges":[{"speaker":"林委員","kind":"意見","question":"４ページの一番最後の公務員倫理だけれども、「公務に対する社会の目が厳しくなっている昨今の状況を鑑み」と、こんな言葉を人事委員会が使うのか、私は違うと思う。これは品川区としては言うべきだと思う。だから、襟を正しというのは違うよ。品川区が人事委員会にどういうふうにものを言えるのかわからないけれども、言うとしたら議長会かな、これはひどすぎると思うんだけれども、思いませんか。","respondent":"榎本人事課長","answer":"その下に「公務に対する社会の目が厳しくなっている」ということで説明に入っているんですけれども、概要版ということで、その言葉の部分は若干抜けておりまして、不祥事の部分が若干あるです。","id":"exchange-035"},{"speaker":"南委員","kind":"質問","question":"メンタルヘルスの部分ですが、公務労働に限らず民間でもメンタルヘルスが重要視されて、事前に策を取るべきだという状況が広がってきていることはいいことだと思うんですけれども、ここに出た機会もあって、品川区ではメンタルヘルスにどういう対策を持っているのか、あるいはそういうことで休職している正規職員の方が何人ぐらいいらっしゃるのか、その状況が増える傾向にあるのかどうか。","respondent":"榎本人事課長","answer":"要は、セルフチェックといって、本人にまず気づいてもらう段階、それから周りがある程度気づいてフォローしていく段階、それから、組織として対応しなければいけない段階、あとは病気になってしまったら、どのように専門家につなげていくかという段階で、大きく４段階の中で。","id":"exchange-036"},{"speaker":"土井委員","kind":"質問","question":"勧告ですから、これは勧告のとおりにするということでしょうけれども、給与に関すること、労働時間に関すること等々については、いろいろ手続があるのではないかと思うんですが、それと議会との関係のところをお願いします。","respondent":"榎本人事課長","answer":"今、勧告に基づき職員団体および労働組合との交渉が順次進んできております。その中で、最終的に妥結をした段階で、議会に対して妥結内容に従った条例提案という形にしまして、条例を可決をもって勧告内容の一部もしくはすべてが実施されるというような手順になっております。","id":"exchange-037"},{"speaker":"土井委員","kind":"意見","question":"その手順を終着というか、いつどうなる、議会がいつやったらいいのか。","respondent":"榎本人事課長","answer":"去年の例から申し上げますと、去年は妥結がかなり時間が延びまして、１２月の年末あたりに臨時会を開かせていただいて、条例の審査をしていただいたという経過があります。","id":"exchange-038"},{"speaker":"須貝委員","kind":"質問","question":"平均年間給与についてお聞きしたいんですが、新聞報道とか国税庁から発表されているサラリーマンの平均給与は年間四百数十万円ということが発表されていると思うんですが、それに対して実際に人事委員会が調査した民間の平均給与は年間７２０万円というギャップがあるんですが、その辺についてはどのようにお考えになっていますか。","respondent":"榎本人事課長","answer":"特に、この調査の中では、学歴とか職層とかを大体同程度のものという形で調査をかけて、民間給与の部分という形で出しておりますので、実際の４００万円というものからすると金額的には大きくずれるものがありますけれども。","id":"exchange-039"},{"speaker":"須貝委員","kind":"意見","question":"国と２３区レベルでいろいろ調べて、このように特別区人事委員会勧告を出されていると思いますが、一般の区民、都民、国民を見たときにギャップを思うと思いますので、その辺も今後人事委員会で十分考慮されていくと思いますが、公表の仕方、また参考にしている民間従業員の職種、種別等あると思うんですが、その辺が大分違うので、何かうまい方法で、区民、都民、国民にわかりやすいような公表システム。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-040"}]},{"id":"topic-04","title":"の荏原文化センター屋上防水および外壁改修その他工事請負契約","agenda":"の荏原文化センター屋上防水および外壁改修その他工事請負契約","exchanges":[{"speaker":"林委員","kind":"質問","question":"本件と関係ないかもしれないけれども、先ほど言った組織改正になってきて、生涯学習課がなくなってくると、１ページ目に出ている生涯学習費の項、目が生涯学習施設費、この辺のお金を使うときは変わってくるんですか。これはすぐ仕事にかかると、生涯学習費で修繕したものがどこの管理になっていくようになるんですか。","respondent":"日下部企画財政課長","answer":"予算上の科目の整理の問題と組織改正、その辺の関連がどうかということかと思いますけれども、これからその辺の具体的な整理を進めてまいりますけれども、基本的な考え方としては、こういう形で進めていきたいと考えています。","id":"exchange-041"},{"speaker":"林委員","kind":"意見","question":"こうやってすぐ出るわけです。そういう整理はきちんとしておくべきである。ここでこういうふうに出てきたら、これはあくまでも教育委員会に残るものだから教育委員会の管理ですとか、そういうことをやっておくべきで、今検討中ですというのは非常に区民をばかにしていると思う。もう実際にお金か出すんだから。","respondent":"阿倍経理課長","answer":"そのためには所管替えという形で、きちんと管理はしていきます。ただ、来年度以降の予算につきましては、今、企画財政課長が申しましたとおりになるかと思いますけれども、財産の管理につきましては、当然所管が変われば所管にきちんと移すという形になっています。","id":"exchange-042"},{"speaker":"林委員","kind":"意見","question":"たまたま９,０００万円を超えて議会に報告というので、表になったけれども、これが８,９００万円だったらここに出てこないで、工事に入ってどうするということになるわけだから、やはりそれはきちんと工事がまだあるわけですし、来年度の予算を今つくっていくときには、必ずそういう問題が起きてくるわけですし、それはきちんと把握しておかないといけないと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-043"}]},{"id":"topic-05","title":"の補助３０号線（西小山駅前広場を含む）整備工事請負契約","agenda":"の補助３０号線（西小山駅前広場を含む）整備工事請負契約","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"直接この工事とは関係ありませんけれども、隣接する駐輪場の関係ですけれども、２カ所つくられる予定だと聞いておりますけれども、ここでは１カ所しか表示がないので、あとはどこにつくられるのか、それからこのあたりの概要がわかれば教えていただきたいと思います。","respondent":"阿倍経理課長","answer":"駐輪場をどこに設置するか、所管でございませんので把握してございません。","id":"exchange-044"},{"speaker":"南委員","kind":"意見","question":"建設委員会ではないところで聞いて恐縮ですけれども、駐輪場をつくられる方向で記憶しているんです。今の現状がどうなのかわからないので内容を聞きたかったんですが、できるだけ区民の方々の利便が図れるように整備される当然だと思うので、そのように期待したいと思います。そのことについては改めてこういう意見をお伝えしておきたいということで、表明だけしておきます。","respondent":"須藤委員長","answer":"建設委員会と違うので、所管は契約事項の説明だけですので、その件については所管が違うと思います。","id":"exchange-045"},{"speaker":"須貝委員","kind":"質問","question":"今、平面図を見ていまして、左側に東急有料駐輪場が載っております。工期が平成２１年３月３１日になっていますが、その辺については目処として立っているのでしょうか、それだけお聞かせください。","respondent":"阿倍経理課長","answer":"当然のことながら、契約が済んですので、こちら側としては工期どおり進めていくものと考えております。","id":"exchange-046"},{"speaker":"須貝委員","kind":"質問・要望","question":"深くは言えないのですが、ここに住んでいる方や近隣の商店街の方から、補助３０号線の工事も含めて駅前広場の整備を急いでほしいという要望がかなり出ております。長年交通のことで大分苦労されていると思いますので、そういうお話が出ているようですが、区のほうで頑張っていただいて、速やかな工期どおり工事を進めて終わらせていただきたいと思います。要望だけ言っておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"},{"speaker":"林委員","kind":"質問","question":"１億２,４００万円強は、全部品川区のお金でやるということで理解しておかないといけないですか。","respondent":"日下部企画財政課長","answer":"残りの部分につきましては、都市計画交付金が出ます。残りは基本的に財調で手当てをするということですから、歳出ベースは区の予算として執行いたしますけれども、財源としてはすべ国庫、都市計画交付金、財調という形での目処はついているというものです。","id":"exchange-048"},{"speaker":"林委員","kind":"質問","question":"鉄道が絡むとお金の出所が私たちには理解し難い部分が出てくるんだけれども、これは区がもつ。これの枠の外、今もちらと出ていたけれども、１１ページの左側に1)、2)、があって、その間に線路が書かれています。線路が地下にもぐっているわけです。上が空地になっているわけです。ここについては品川区と東急とはどういう話し合いになっているんですか。","respondent":"日下部企画財政課長","answer":"例えば、ほかの立体化の事業でもそうですが、公租公課分だけを負担して、あとは地元自治体の利用に供する。区のほうとしては、今現在３カ所ありますが、緑道公園として整備するということで、今、工事等も進めているというものです。","id":"exchange-049"},{"speaker":"林委員","kind":"質問","question":"さも決まったように住宅を建てると発表されて、もちろん建設費は向こうがもつのだろうけれども、１億円も２億円も出しておいて、「ああ、そうですか、どうぞ」というのも、しゃくにさわるような気がするけれども、その辺は住環境整備担当がやっていることになっているというから、ここで言うのもおかしな話になってくるけれども、非常に東急としては突発的なものの言い方をしているわけだから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"}]},{"id":"topic-06","title":"の商店街電線類地中化工事（北品川地区）その３請負契約","agenda":"の商店街電線類地中化工事（北品川地区）その３請負契約","exchanges":[{"speaker":"南委員","kind":"意見","question":"この件と少しそれますけれども、ここで聞いていいのかどうかわからないですけれども、電線地中化というのは買い物をする私たちにとっても非常にいいと思うんです。まちの美観の点でもいいと思うんですけれども、どの程度普及しているのか聞きたいなと思ったんですけれども。所管が違うのは承知していますけれども、わかる範囲で。","respondent":"阿倍経理課長","answer":"この近くでは、東京都の第二建設事務所がやりましたけれども、補助２６号線の二葉町のところ、区役所を出まして右側に行きますと、あそこは既にケーブルが下に入っているはずです。はニコンの前のあたり、補助２０５号線も既に地中化していると、区内ではそういう状況です。","id":"exchange-051"},{"speaker":"須貝委員","kind":"質問・要望","question":"それならば、逆に東京都が言わないだろうという議論のほうが、逆に先行して話すべきで、これだけ２３区がきちんとやっている中で、確かに財源的に厳しいところは吸収するということはあると思うんですが、こういう攪乱作戦にぜひ負けないで頑張ってほしいと思います。それに乗って話をしたのではないかと思います。逆に各区が独立するということは、やはり明確に訴えて、今後も言っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-052"},{"speaker":"林委員","kind":"質問","question":"区長はもうみんなはっきりわかっている。このスケジュールを見ても危ないわけでしょう、平成２０年の話が。区長はあと３回ぐらいやるというのなら、そのぐらいの時間は見られるかもしれないけれども、どこへ船を着けて、どういう形を２３区が取っていくのかというのは、２３人で議論していいと思うんです。中の雰囲気を知らないけれども、区長たちの上辺というのはどのぐらいの感覚でよんでいるのですか。","respondent":"濱野区長","answer":"スケジュール等の関係ですが、すべてのメンバーがこれでは間に合わないということで議論を少し延長しましょうということを考えておりますので、来年の４月というのはとても間に合いませんので、もう少し期間を延ばしていくことになると思っています。","id":"exchange-053"},{"speaker":"林委員","kind":"意見","question":"かわいそうだけど、一緒になってやるよというところでも、一緒になったほうが得だという市町村の事情があるけれども、２３区に来ると財調という２３区にとってはなくせない交付金である。東京都にとっても、あれは２３区に対する権力の使い道のような部分がある。区長もおっしゃられたように、２３区にとっては動機づけになる部分かなかなかないわけです。うちはどっちにも入りたくないわけです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-054"},{"speaker":"土井委員","kind":"質問","question":"今の各区長の気持ちがなかなかいかないものの一つは、財調という中身をどうするかということの議論がされていないからだと思うんです。だから、２３区という大きな器の中でこれだけあるんですよという形で分ければですから、それを都にやらせること自体が間違っているということを、やはりみんなで自覚させるということが必要ではないかと思うんです。それがきついということでしょう、違うんですか。","respondent":"濱野区長","answer":"事務の配分について、もう一回本気でやってみようということで、このテーブルができた。我々はそういう認識をして、つまりもう一ランク上の一人前の自治体、地方公共団体を目指すためには、もっといろいろな仕事をやる。引き受けることで財源配分ももっと大きくする。","id":"exchange-055"},{"speaker":"伊藤委員","kind":"確認","question":"おそらく今、４４０項目のうち５０から６０事業ぐらいしか片づいていない。となると、これから本当に進めるんですか。だけれども、それのはるかに前になっているわけですから、そうすると本当にこのことについて区長会がどのように考えているかという疑問さえ感じてしまうので、そのことをまず基本的な確認をお願いしたいのが一つ。それから、それでは進めていくのであれば、何で遅れたんですか。","respondent":"濱野区長","answer":"それからもう一つは、都側の内部でこの問題については非常に冷めているということです。つまり、総務局あるいは知事本局が検討メンバーですけれども、実際の仕事を所管しているのは福祉局あるいは労働経済局の現場が、一言で言えば区におろすことについて冷たい。","id":"exchange-056"},{"speaker":"伊藤委員","kind":"提案","question":"品川区のやっていること自体は応援したいと思っているけれども、現実の問題としては進んでいない。だから、これに対して問題を分析することをやっていったらどうですか、同じ提案ですけれども。その今の流れで難しいかもしれませんけれども、はっきりとスケジュールを区切ってそれを出していくとか、そこまで区長会内部を含めて議論はしているんですか。","respondent":"濱野区長","answer":"そのどこかというのは、もう少し先だろうと思います。平成１２年の改革よりこの議論というのは、政治の要素が絡んでいる内容ではないかと思いますので、そういったものを加味すれば、もう少し後にスケジュールを考える時期が来るのではないかと思っています。","id":"exchange-057"},{"speaker":"南委員","kind":"質問","question":"私も区長の冒頭の報告を伺って、何か愕然としたというか、ギャップを感じたんです。いいかどうかは別として、全く個人的な視点ですけれども、区長が先ほど政治的な要素を含んだ状況になるというお話をなさっていたので、住民も含めた期成連盟のような形の運動をするのがいいか悪いかですけれども、その辺の見解を伺っておきたいと思います。","respondent":"濱野区長","answer":"おそらく、マスコミがそういう言い方をしてくるのではないかと、私自身は思っています。したがって、もしそういうことが必要だとするにしても、もう少し先ではないかと、これも個人的な見解ですが、そのように思っています。","id":"exchange-058"},{"speaker":"土井委員","kind":"意見","question":"今の話の中のマスコミもというところを、どうとらえていくかというのがあるのだと思うんです。要するに、マスコミに知らせるというか、我々の思いをわからせるというか、それを巻き込んで、都から漏れて聞いているけれどもおかしいではないかと、逆に言うようなマスコミをつくっていく方針をどうやって打ち出していくかというのが必要なような気がして仕方ないけれども。","respondent":"濱野区長","answer":"しかし、このことだけではありませんので、飯田橋からの情報発信力といいますか、メディアに対する発信力というのはもっと強くしていかなければいけないのではないかと思っています。","id":"exchange-059"},{"speaker":"土井委員","kind":"質問・要望","question":"片方では分権という言い方をすると、喜んでやってくれるわけです。だから、そういう切り口でぜひやっていただきたいなという感じです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-060"},{"speaker":"林委員","kind":"質問","question":"最後に、あり方検討委員会のメンバーの変更はあるんですか。任期というのか、どういう形になっているんですか。","respondent":"濱野区長","answer":"特に決めはありませんが、多分この検討会が続く限りは同じではないかと。特段の事情があれば別です。ですから、今年の４月に役員はかわりましたけれども、このメンバーはかわっておりませんので、そういう意味では続けていくことになるのかなと思っています。","id":"exchange-061"},{"speaker":"須貝委員","kind":"質問","question":"今、工事が進んでいると思うんですが、施設一体型の小中一貫校の建設ですが、工事は順調に進んでいますか。公表した期限どおり建設は進んでいるかどうか、それについて教えてください。荏原と八潮について。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-062"},{"speaker":"須貝委員","kind":"質問","question":"契約の案件で、状況によっては追加工事費が発生することも考えていかないといけないということですか。","respondent":"宍戸施設担当課長","answer":"そういった部分も含めて、調整を図っているところです。","id":"exchange-063"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/917943?Template=document&Id=1800#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":48239,"voices":158}},{"id":"h20-20081125-6","meetingId":"h20-cm11","date":"2008年11月25日","dateIso":"2008-11-25","committee":"区民委員会","time":"午前１０時０２分～午後１時３０分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を33件抜き出しています。","topics":[{"id":"topic-01","title":"第７６号議案「品川区特別区税条例の一部を改正する条例」","agenda":"第７６号議案「品川区特別区税条例の一部を改正する条例」","exchanges":[{"speaker":"若林委員","kind":"質問・要望","question":"大きく１、２、３、４とありました。それで、わかったところ、わからないところ、さまざまありますけれども、とりあえず、公的年金の特別徴収について伺いたいと思います。これまで普通徴収が、今やっている中での徴収できない部分、いわゆる滞納という言い方になるのでしょうか。そういう今まで滞納していた方へのお気遣い、配慮というんですか、そこら辺の対応についてお聞きしたいと思います。","respondent":"武内税務課長","answer":"ただ、さまざまな事情がありますので、年金支給時前にご相談に来ていただければ、それは何らかの形で、今後の検討課題となりますけれども、対応はしていかなければいけないのかなというふうには考えております。","id":"exchange-001"},{"speaker":"若林委員","kind":"質問・要望","question":"そういう意味では、そこら辺もしっかりとフォローしていただきたいなということなんですね。ひとつ、今、課長のほうから、最後のほうには、そこら辺のこともこれからの検討課題という、今、言葉でしたでしょうか。現状、今、そういう、４回から６回になって、当然、一回一回の税負担が軽く、軽減されるという、軽くなる一方、そういう方がいらっしゃった場合に、現状、何か仕組みがあるのか。","respondent":"武内税務課長","answer":"年金の受給者につきましては、原則、特別徴収をするです。とはいっても、今回、こういう提案をする中で、さまざまな、こういう、税金を特別徴収することによって、議論がある中で、今後、品川区独自の方法等で、検討できる部分は検討していきたいなという考えでいるです。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問","question":"天引きされてから、多分、すごく大変な事態になるということは目に見えていると思うので、そうなる前に、この機会をとらえて、減免、例えばありますね、品川区で今ありますけれども、新条文になっちゃっていますけれども、区税条例３６条で定めていただいている減免規定を、この機会に周知徹底するとか、あるいは、事前に、向こうから来れば相談を受け付けますよというんじゃなくて、具体的に、区側から。","respondent":"武内税務課長","answer":"そういった意味では、私どものこの年金特徴につきましても、地方税法の枠の中でとり行っていくものですので、国のほうも、その辺のルールについては今後の検討課題と言われておりますので、その辺の推移を見守りながら。","id":"exchange-003"},{"speaker":"安藤委員","kind":"質問・要望","question":"繰り返しになっちゃうんですが、明らかに、これ、来年に、１０月に天引きになってから、大混乱になることは目に見えていますので、先ほど言ったように、これを機会に減免措置制度がありますよとか、区税条例３６条のこういう減免規定もありますよと、そういうことも含めて周知徹底していくということが、具体的な手当というか、そういうのを行っていくことが必要だと思いますので、要望いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"渡部委員","kind":"質問","question":"広報とかに出て、こういうふうになりますよで終わりじゃなくて、やはり、当然、各々に、こういうふうになります。制度が変わりますというような形での通知があった上で、始まることなのかどうか、１点だけ教えてください。","respondent":"武内税務課長","answer":"もちろん周知するという、ＰＲというのは、私ども、一番大切なことだと考えていますので、もちろん広報、ホームページ等で周知するのはもちろんのことですけれども、来年になりましたら、それぞれの関係機関、あるいは高齢者のグループなどに、会合のある際に。","id":"exchange-005"},{"speaker":"渡部委員","kind":"意見","question":"要するに、確定したときに知るというよりも、できれば確定前に、制度が変わるんだというようなので、広く伝わるような方法をぜひとっていただければと思います。よろしくお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-006"},{"speaker":"若林委員","kind":"確認","question":"１点、今の特別徴収で、確認をさせていただいて、寄附金のほうもちょっと聞きたいんですけれども、確認は、かなり遠いところで、私は、区のほうであるんですかというニュアンスでお聞きしているんですが、もともと国のほうの検討ということを見ながらというふうに、品川区のほうが考えているのかということを１点お聞きしたいと思います。答え、中の計算はちょっとよくわからない。この２つ。","respondent":"武内税務課長","answer":"進んでいるところもあるわけですけれども、そういった意味で、このシステム改修が間に合わないような自治体については、それの推移を、その状況に応じて、年金特別徴収を開始すればいいということになっておりまして、私が、今後の検討課題と言ったのは。","id":"exchange-007"},{"speaker":"若林委員","kind":"質問","question":"寄附控除のほうは、要するに、社会福祉協議会のほうへ５万円を入れた場合に、実際に寄附金としては社会福祉協議会に幾ら入るんですか。控除としては幾ら戻ってくるという言い方があったので、戻ってくるのか。同じように、品川区に５万円入れた場合は、幾ら品川区に寄附金としてプールされて、自分のところに戻ってくるのかという、そこだけ。","respondent":"武内税務課長","answer":"ただし、品川区にやっていただきます品川区の税収は５万円、５万円というか３万６,０００円の部分がマイナスになるという、税収が下がるということです。","id":"exchange-008"},{"speaker":"若林委員","kind":"質問・要望","question":"とりあえず、特別徴収のほうは、要するに、特別徴収するか、しないかという判断の検討はどうですかという、私は質問はしていませんので、そこら辺の軽減策について、国のほうには検討とあったので、国のほうで軽減策をこれから検討して、それを見て、自治体として判断をするのかということをお聞きしたので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"本多委員","kind":"質問・要望","question":"４番目の規定の整備のところの1)の公益法人に関するところで、公益法人に財産を寄附した場合という、そのケースなんですけれども、大体、土地ですとか、箱ものですとか、主立ったものはそういうところだと思うんですけれども、ほかにそういう主立ったケースが、どういうのが可能性としてあるのか。それと、あと、交付の日について教えていただきたい。交付の日。","respondent":"武内税務課長","answer":"交付の日から施行というのは、今回の品川区の条例改正の交付する日というようなことで考えてよろしいかと思います。","id":"exchange-010"},{"speaker":"本多委員","kind":"質問・要望","question":"先ほどから出ています公的年金の特別徴収のところで、それぞれ出ておりますけれども、ちょっと確認させていただきたいのは、４ページ目の、補足説明資料の４というところで、絵がかいてあるんですけれども、特別徴収義務者の社会保険庁の税負担が、平成２１年１月ごろに市区町村に報告がされるということで、それがまた、市区町村から対象の方に情報提供があったりして。","respondent":"武内税務課長","answer":"委員、言われるとおり、平成２１年６月１０日を予定というのは、今後、前年の所得に対して、住民税の課税はこういうふうになりまして、こういうふうに払っていただきますよという通知を６月に行う予定ですけれども、先ほど言われるとおり、それ以前に、確定申告時期や。","id":"exchange-011"},{"speaker":"安藤委員","kind":"質問・要望","question":"それで、税収を移すというか、自分が納めたいところに税金を結果として納めるような形になるシステムなのかなと思うんですけれども、これ、そもそも、このふるさと納税というのは導入をされた、かなり複雑な制度だと思うんですね。区としては導入された理由というんですか、これをどのようにとらえているのかなということをお願いします。","respondent":"武内税務課長","answer":"今後、状況に応じて、他の社会福祉法人等も検討していかなければならないと考えております。","id":"exchange-012"},{"speaker":"安藤委員","kind":"質問・要望","question":"特に、こういった減税で恩恵を受ける方というのはかなりの高額所得者だと思うので、そういうふうな印象をどうしても受けてしまうんですが、特例措置のところで、譲渡益と配当所得に対する２カ年の経過措置のところで、５００万円以下の部分というところと、１００万円以下の部分というところがあるんですけれども、実際、本当なら、翌年にすぐ廃止ということだと思うんですけれども、２年間ですかね。","respondent":"武内税務課長","answer":"ふるさと納税を２３区、東京都を含めて、推進しないというのは、先ほど説明したとおり、都市圏に集まっている税を地方に配分したいという考え方がありまして、いわゆる東京都の住民の方は、多くの方は地方からお住まいになっている方が多いということが当然考えられる。","id":"exchange-013"},{"speaker":"安藤委員","kind":"質問","question":"私も株というのをやったことがないもので、イメージがつかないなという意味で質問させていただいたんですが、５００万以下ということなので、５００万以下ですから、もちろん１万円でも、２万円でも、ささやかにやっている方々も含まれると思うんですけれども、譲渡益で５００万円の利益を得るとか、あるいは配当所得１００万円以下ということで、１万円から１００万円。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"渡部委員","kind":"質問・要望","question":"先ほど、ほかの委員からあった寄附金控除のところで、まだ胸に詰まっていて、しっくりこないので、１つ確認させていただきたいんですけれども、僕が例えば多摩川をきれいにしたいというので、川崎市に５万円寄附をしました。なおかつ、本来、僕が東京都に払うべき都民税１万２,６００円と区民税１万８,９００円が入ってこなくなっちゃう。それで、多摩川がきれいになるという考え方なわけですよね。","respondent":"武内税務課長","answer":"品川区民の方が品川区にやっていただきますと、税収はもちろん下がってしまうんですけれども、実際的には、５万円という金額、同じ金額が形をかえて収入になるわけです。","id":"exchange-015"},{"speaker":"安藤委員","kind":"質問","question":"同時に権利もあるわけですから、それを侵害することになりますし、あと、やっぱり高齢者の生活を実際脅かすということからも認められませんし、しかも、システム改修に６,０００万円という税金が使われるというのも納得いかないということです。ますます加速させるものじゃないかと思いますので、長くなりましたが、反対です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"}]},{"id":"topic-02","title":"第７７号議案「品川区国民健康保険条例の一部を改正する条例」","agenda":"第７７号議案「品川区国民健康保険条例の一部を改正する条例」","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"６ページの資料のところで、内容を教えていただきたいんですけれども、「産科医療補償制度の概要」というところの２番目の「補償の仕組み」というところなんですけれども、2)で、「運営組織が契約者となる損害保険に加入する」という文言があるんですけれども、損害保険、この中身なんですが、損害保険というのは、これはどういう、民間なのかどうかということと、あと、補償を実際に、対象者というのは。","respondent":"本城国保年金課長","answer":"そういう意味で、保険会社自体は民間ですが、それを取りまとめる財団法人として１つの機構があって、そこで全体を集約するような、そんな形になっています。","id":"exchange-017"},{"speaker":"若林委員","kind":"質問","question":"こういう新たな制度ができたということで、例えばこれまでの品川区においては、こういう事例に該当する方というのは、どういう推移があったのかなというのをひとつ、お聞きしたいなと。もう一つは、一時金が３万円上がった背景は、妊産婦さんが３万円を医療機関、分娩機関に保険料を払うということですか。","respondent":"本城国保年金課長","answer":"それと、もう一つの３万円の、先ほど、保険会社とか、運営組織とか、病院とか、いろいろな登場者を、錯綜した中で説明いたしましたが、基本は、妊産婦が病院に分娩費を支払うですが、その病院としての分娩機関が、運営組織です財団法人の全国組織に。","id":"exchange-018"},{"speaker":"宮崎副委員長","kind":"質問","question":"何点か伺いますけれども、品川区の国保の関係で、どのぐらいの負担増になるのか。そこのところはどういう。立証責任というのは、もしかしたら軽くなるのかもしれないけれども、やっぱり判断というか、グレーゾーンというか、そういうところがやっぱり出てくるんじゃないかなと思うんですけれども、そこら辺の、だれが、どういうふうな基準で判断していくのか、そこはどうなんでしょうか。","respondent":"本城国保年金課長","answer":"それと、あと、１級、２級という要件がございまして、それについてだれが判定するかというものですが、それについては、この制度自体は、１級、２級が認定されたその土台の上に乗っかっているような仕組みになっておりますので、１級、２級自体が。","id":"exchange-019"},{"speaker":"宮崎副委員長","kind":"質問","question":"予算のところは、平成１９年は４９０件。それから、３万円だと１,３００万円から１,４００万円ぐらいの増ということなんですけれども、これというのは、基本的に、いわゆる保険料とか、そこへの影響ということになっていくんでしょうか。","respondent":"本城国保年金課長","answer":"異常分娩につきましては、今回、新しくいろいろな課題を解決する中で、こういう制度が生まれて、そういう意味では、今回の対象ですけれども、統計的には全国で５００人から８００人ぐらいの方がこれの対象に含まれるというふうに想定されているですので。","id":"exchange-020"},{"speaker":"宮崎副委員長","kind":"質問","question":"さっき、保険料というのは、要するに国保の会計のところ、品川区の会計のところでは、３万円が出る部分、要するに１,３００万円から１,４００万円ぐらいかなと思うんですけれども、これがそのまままた加入者の負担のところに行くということになるのかなと思うんですけれども、やっぱり今の不景気のところなので、ここのところはもっと工夫が必要じゃないかなと思うんですけれども。","respondent":"本城国保年金課長","answer":"今回の出産育児一時金の財源につきましては、保険料の算定基礎となる賦課総額には含まれるものではなく、一般会計からの繰入金を財源とするもので、したがって国保の被保険者の保険料にはねかえる性格のものではございません。","id":"exchange-021"},{"speaker":"稲川委員","kind":"質問","question":"本当に細かいことで申しわけないんですけれども、この一時金とか、受け取ったことはもちろんないわけであり、あれなんですけれども、保険を掛ける、要するに病院側が、多分掛けるということだと思うんですけれども、掛けるタイミングって、いつ掛けるんですか。ちょっと細かい話で申しわけないんですけれども。その辺を教えてください。","respondent":"本城国保年金課長","answer":"例えば双子なんかが生まれた場合も、２人出生したということで、出生してからわかったりすることもありますので、いずれにしても１人について、１分娩当たり、生まれたことによって掛け金が生ずるという仕組みになっていると考えています。","id":"exchange-022"}]},{"id":"topic-03","title":"第８８号議案「指定管理者の指定について」","agenda":"第８８号議案「指定管理者の指定について」","exchanges":[{"speaker":"安藤委員","kind":"提案","question":"選定の経過ということでご説明があったんですが、選定理由のところで、簡単過ぎるというか、もう少し知りたいんですけれども、新たな取り組みや地域への展開などの意欲が高くというところなんですが、どういうところでそういう高さを感じたのかというのと、あと、利用時間の延長や会館利用予約の区民優先措置を提案、具体的な提案があったということなんですが。","respondent":"小野区民課長","answer":"その後に書かれております、会館の利用時間、あるいは優先受付、これも新たな取り組みですけれども、この会館の運営については、例えば新たなコンサートの実施でありますとか、あるいは文化振興事業団といたしまして。","id":"exchange-023"},{"speaker":"安藤委員","kind":"質問・要望","question":"といいますのは、管理に係る経費の縮減ということで、経費の削減に取り組むということを求めているわけですけれども、一方で、３番目、人員の配置計画は適切かということで、人的能力を有していることも大事であるということを言っているんですけれども、２番目の経費節減を求めていくと、どうしても人件費というところでしわ寄せが来てしまうんじゃないかなという危惧を持ってしまうんですが。","respondent":"小野区民課長","answer":"２番目の選考基準ですね。管理ならびに管理に係る経費の縮減が図られるということと、それから、管理を安定して行う物的能力および人的能力ということが矛盾するのではないかというふうなお話ですけれども、これは決して矛盾するものではないと考えております。","id":"exchange-024"},{"speaker":"安藤委員","kind":"質問","question":"その２点をお伺いしたいと思います。","respondent":"小野区民課長","answer":"現在の価格、３,０００円ぐらいのところで、非常にいいものが見られるというところについては、今のレベルというものが妥当なレベルではないかというふうに考えているところです。","id":"exchange-025"},{"speaker":"稲川委員","kind":"質問・要望","question":"要望的なことになってしまうかもしれないんですが、１番の利用者の平等な利用の中に、サービス向上につながる事業計画がどこに当てはまるかあれなんですが、きゅりあんの例えば８階、７階に行くのはダイレクト、駅に近いと言われている正面からすぐ行けると思うんです。それとも、今までそういう話があって、改善をしたのかどうかというところを教えてください。","respondent":"小野区民課長","answer":"いろいろな表示の部分で、きゅりあんともこれまでもいろいろと工夫をしてまいりましたけれども、今後も、もっとわかりやすい形の誘導はないかどうか、文化振興事業団のほうに、十分にその辺、要請をしてまいりたいというふうに考えております。","id":"exchange-026"},{"speaker":"宮崎副委員長","kind":"質問・要望","question":"直接、今回の議案と関係、関係もするんですけれども、別な角度になるかもしれないですけれども、選考基準ですね。これ、１、２、３、４つ、それぞれ部長決定としてやられているんですけれども、この選定の基準をこういうふうに書くのであれば、それぞれの基準でどうだったのかと。指定管理者の問題として受けとめていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"}]},{"id":"topic-04","title":"を聴取します。(1)の第九回品川区中学生の主張大会","agenda":"を聴取します。(1)の第九回品川区中学生の主張大会","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"１６名の方が主張されるということで、表彰ということなんですけれども、優秀賞みたいな形で１人表彰する。何人を表彰し、どういう賞なのかというのを教えていただきたいのと、あと、これは審査員の方によるものなのかと思うんですけれども、この主張大会の趣旨に照らして、どういう考えで表彰する対象の方を選ぶのかなという、基本的な考え方みたいなものがあれば伺いたいと思います。","respondent":"中山地域活動課長","answer":"こういう結果です。審査の基準、考え方ですけれども、内容と発表の聞いた印象、こういうものを総合的に判断していこうということで選んでいるものです。","id":"exchange-028"},{"speaker":"安藤委員","kind":"意見","question":"総合的に判断というのは、ちょっとあまりにも漠然と。この大会としての基本的な、中学生の方に主張してもらうということなので、趣旨というか、どういった方向で総合的に進めさせていくのかという、もう少しちょっと、お開きしたいなと思います。","respondent":"中山地域活動課長","answer":"それで、内容については、５人の委員、審査員の方に、一定、お任せしていますので、大きく、主張の内容。","id":"exchange-029"}]},{"id":"topic-05","title":"の地域食事サービス及び訪問ボランティア事業","agenda":"の地域食事サービス及び訪問ボランティア事業","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"昼食と夕食の配食数の差が随分あるんですが、この理由は何なのかということと、あと、裏面の訪問ボランティアの対象者数と配食の対象者の数というのは若干ずれがあるのは、これはどういうことなのか、細かいんですけれども、お伺いします。","respondent":"中山地域活動課長","answer":"お弁当の内容がお年寄り向けに工夫されたのかですけれども、先ほど、(1)の２に書いたように、事前に事業者に説明会をちょっとやりまして、お年寄りに配るお弁当ということで、保健所の栄養士等の指導もして、留意してもらいたいこと、また担当から。","id":"exchange-030"}]},{"id":"topic-06","title":"の平成２０年度「第２５回防災フェア」の実施","agenda":"の平成２０年度「第２５回防災フェア」の実施","exchanges":[{"speaker":"安藤委員","kind":"意見","question":"日時なんですが、防災意識がすごく今高まっていると思うんですが、金曜日と土曜日ということなんですが、日曜日のほうがより多くの方が参加できるんじゃないか。一般的にはそういうふうに思っちゃうんですけれども、今回、そういった、日曜日の実施というところの検討はあったのかなということと、あと、もしそういうことが必要であれば、日曜日への変更ということは考えていらっしゃるのかなというところを。","respondent":"斉藤防災安全担当課長","answer":"これにつきましては、消防、警察、または防災協議会等、関係していただいている機関の方々との話し合いによりまして、本来であれば土曜日、日曜日というのが、人が一番集まる曜日かもしれませんけれども、業務の調整の結果、こういった形で、平日１日。","id":"exchange-031"},{"speaker":"稲川委員","kind":"質問","question":"これは内部資料的なものだと思うんですけれども、参加団体のところに、最後「機関他」と書いてあるんですけれども、例えば、普通にコマーシャルをする、区民の、一般的にコマーシャルするところには、この「他」じゃなくて、どういう団体が参加するか、全部、明示はされるのかですね。その点、１点お伺いいたします。","respondent":"斉藤防災安全担当課長","answer":"昨年の、昨年といいますか、厳密には今年の１月の広報ですけれども、こちらのほうにつきましては、「他」という言葉でなくて、すべての団体について記載をさせていただいておるところです。","id":"exchange-032"},{"speaker":"本間委員長","kind":"確認","question":"先の一般質問の中でも、住宅火災警報器の件で質問させていただきましたけれども、まだまだ、聞くところによりますと、３割ちょっとぐらいで進んでいるということでございました。それで、助成制度について触れたことがありますが、これは確認になりますけれども、高齢者のひとり暮らしに云々というのがありますけれども、この部分について、助成制度ですね、もう少し詳しく教えてください。２点です。","respondent":"斉藤防災安全担当課長","answer":"当日は、品川区のほう、また葛飾福祉工場のほうが出向いていただきまして、住宅用火災警報器の展示のブースを設けまして、そちらのほうでＰＲをしていただく。さらには、そこのほうで、場合によっては販売をしていただくという形で考えております。","id":"exchange-033"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/487097?Template=document&Id=2534#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":44956,"voices":107}},{"id":"h20-20081125-7","meetingId":"h20-cm11","date":"2008年11月25日","dateIso":"2008-11-25","committee":"厚生委員会","time":"午前１０時０２分～午後５時１１分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を116件抜き出しています。","topics":[{"id":"topic-01","title":"議案審査","agenda":"議案審査","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"１点だけ、お伺いしたいと思います。ここに、第２条(1)の中で、ということで、法第６条第１１項を第１２項に改めるというところなんですが、この第１１項自体がどういう中味なのか、ちょっと教えていただけないと判断できないので、よろしくお願いします。","respondent":"吉田品川区保健所保健サービス課長","answer":"申しわけございませんでした。法第６条第１１項と申しますのは、感染症指定医療機関の定めでございまして、そこに勤務する医師から委員を選定するといったことです。実際には、感染症を専門に見る医療機関がそこに述べられているといった内容です。","id":"exchange-001"},{"speaker":"浅野委員","kind":"確認","question":"例えば、今回第１２項になりましたけれども、この中にさまざまな疾病とか、そういうものが追加になったときに、ここに出てくる可能性があると思うんですけれども、それは特に、ある意味では論議なく、こちらのほうで必ず参考するものと考えてよろしいのかという確認だけ、お願いしたいと思います。","respondent":"吉田品川区保健所保健サービス課長","answer":"委員ご指摘のとおりでございまして、すべてそういった形で進めていきます。","id":"exchange-002"},{"speaker":"堺委員","kind":"確認","question":"この医師については、今、浅野委員が言ったように、結核指定医療機関となっていますが、今回、変更した中の一部に、おわかりのとおり、この法律において「感染症指定医療機関とは、特定感染症指定医療機関、第１種感染症指定医療機関、第２種感染症指定医療機関および結核指定医療機関をいう」と、そこにはまた詳しくいろいろ出ていましたけれども、その中の医師が協議会の委員になるということですが。","respondent":"吉田品川区保健所保健サービス課長","answer":"法律に関して学識経験を有する者といったことで、これは弁護士を２名、それから、医療および法律以外の学識経験者といったことで大学教授を２名充ててあります。","id":"exchange-003"}]},{"id":"topic-02","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"きちんとした図面を見るのが初めてなので、ちょっとつくりについてお伺いしたいと思います。それから、ここに特別保育事業が４点書かれていますけれども、これが行われる場所がどこなのか教えてください。","respondent":"小林保育課長","answer":"お尋ねのありました部屋の間仕切りですけれども、子どもの状況、あるいは保育の展開の状況に応じて床を柔軟に対応できるようにということで、基本的には、園児の各クラスの連携に応じて間仕切りをしておりますので、一概に可動間仕切り。","id":"exchange-004"},{"speaker":"飯沼委員","kind":"意見","question":"０歳児と１歳児の保育室が、図で見ると一つの部屋になっていますけれども、乳児、特に０、１歳児というのは睡眠の確保がすごく重要であると思うんですが、その辺、十分に睡眠がとれる態勢になっているのか。この辺はどこら辺で論議されて、こういう図面というか、多分運営側の意見も入っていると思うんですけれども、その辺がどうなっているのかが１点。","respondent":"小林保育課長","answer":"０歳児の睡眠等につきましては、位置的にはコーナーということで、左上の部分を想定していくようです。保育の状況に応じてじっくり休めるようなスペースの確保も含めて、その辺は対応できていると考えております。","id":"exchange-005"},{"speaker":"飯沼委員","kind":"質問","question":"最後です。１階の真ん中の白い部分と屋上庭園を合わせると、今の品川保育園の園庭と比較して、どういう割合なのか教えてください。","respondent":"小林保育課長","answer":"エントランスと廊下で７０.３３m2、プラス付帯設備ですし、屋上につきましては、この図でわかりますように、建物の塔屋、その他エレベーター等があるところ以外は空地という形で園庭に使えるところが、図面の推量ですけれども、およそ半分以上はありますので。","id":"exchange-006"},{"speaker":"飯沼委員","kind":"質問・要望","question":"後で結構なので、数字がわかりましたら、お知らせいただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"阿部委員","kind":"確認","question":"移転に際して、住所に伴って電話番号も変わるんでしょうか。それが一つです。それから、一時保育で部屋ができているということは、ここはオアシスルームがずっと常設になるのかということを確認させてください。それから、屋上の園庭なんですけれども、（芝）とあるのは、天然芝ということでよろしいでしょうか、お願いします。","respondent":"小林保育課長","answer":"ちゃんと確かめてないんですけれども、電話番号は、同じ局内ですので、今のまま移設が可能かと思います。それから、オアシスルームにつきましては、４月開設当初、ここでの開設を予定しておりません。","id":"exchange-008"},{"speaker":"阿部委員","kind":"質問・要望","question":"電話番号は、もし変わるのであれば、十分な周知を、と思ったんですけれども、変わらないということでしたら大丈夫です。それから、オアシスルームについては、ぜひ前向きにご検討いただきたいと考えています。それから、保護者との話し合いの中でも、何か進捗、変化等があれば、教えてください。","respondent":"小林保育課長","answer":"それ以外には特に大きな変化はございませんが、品川保育園の地域交流事業が軌道に乗りました暁には、むしろ品川保育園を主たる実施場所として位置づけてまいりますので、大井保育園の地域交流の事業を一部移行する等の小さな調整は、随時。","id":"exchange-009"},{"speaker":"阿部委員","kind":"質問","question":"一本橋保育園の０歳児と１歳児の調整は、定員はまだ決まっていないということですか。","respondent":"小林保育課長","answer":"今のところ大きな混乱はございませんが、１点、柔軟に、というところの例を申しますと、もう既にご兄弟が在園していて、今度、下の子どもが入るというような場合、もちろん基本的には、新しく入った方については、夜間保育をお受けしないという形でご説明しているんですが。","id":"exchange-010"},{"speaker":"浅野委員","kind":"質問","question":"何点かお尋ねしたいと思います。ここの道路は、私のかすかな記憶ですと、かなり細いのではないかと思うので、自転車で来ると、結構危険を伴うのではないかと感じたことが１点あります。いろいろな道を通って来れると思うんですけれども、ここの動線は、駅から来る最短経路であるというだけなのか、それともこちらを推奨されているのかということをお伺いしたい。この２点を、まずお伺いしたいと思います。","respondent":"小林保育課長","answer":"基本的に、今の品川区の保育園の状態ですと、前の門にセキュリティをかけて、その前に自転車をとめていただくという一義的な対応で、ほぼ間に合うかなと想定しております。","id":"exchange-011"},{"speaker":"浅野委員","kind":"確認","question":"地下にいちいち行くということではないということなので、一つは安心しました。もう１点、例えば、周辺の道路が狭いということがあって気になるのが、やはり何かあったときの避難経路というんでしょうか、園児をどちらの方向に誘導されるのか、ちょっと気になりました。西側ですと、結構狭いというのが気になっていまして、多分、東かどちらかに誘導されるのかと思いますが、この１点を確認したいと思います。","respondent":"小林保育課長","answer":"その辺は、もう一度、通る動線をチェックして、できるだけ距離は短く、だけれども安全な道路幅員を確保した通路選定をしてまいりたいと思います。","id":"exchange-012"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"ですから、浅野委員が言ったように、あまりこの道はお勧めではなくて、ことに自転車だったら無理だなという状況を考えると、浅間台公園側から一般的に通すという話を聞いていたので、ちょっとこれは考えたほうがいいんじゃないかと思います。そこら辺の対応ができているのかということが１点です。とりあえずその辺で、先ほど、何点かお聞きした点を教えていただきたいと思います。","respondent":"小林保育課長","answer":"それに対応しまして、園庭入り口の左側に設置を予定しておりました自転車のスペースを約２倍に広げて、制約はありますが、台数を増やす等の対応を最大限取ってまいりました。","id":"exchange-013"},{"speaker":"堺委員","kind":"確認","question":"１歳児については、現在１０名が１５名ということで、周辺保育園との関係から調整するというようなことで、また、０歳児についても９名となっているんですけれども、増えることについては、それだけの体制ができたのでありがたいことだと思うんですけれども、すみません、今言った、２歳児、３歳児の２名ずつ減について、その辺の状況がわからなかったので、確認だけさせてください。","respondent":"小林保育課長","answer":"これは、例年の退園、入園の動向から言って、調整がつくという見込みでやっておりますが、もちろん、今おられる方、また、どうしても品川保育園でないと支障をきたすというような特殊な事情がある方等が、新たな申込の中にもしおられた場合には。","id":"exchange-014"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"今の定員のことなんですけれども、１００名ということで、０歳児、１歳児が増えてよかったなと思うんですが、前の議事録を読んでいましたら、２００６年２月の説明では、今の９０名から１１０名に２０名ほどの増員に耐えられることを前提に施設計画をおつくりいただきたいということで説明がされていまして、その後の５月にも、１１０名となっているのが、８月になったら、定員が１００名になっていて。","respondent":"小林保育課長","answer":"確かに、この床の中で、すべてを最初から満杯まで入れようと思えば、１１０名はゆっくり可能な施設状態になっておりますが、地域の需要や、それから、他の園との調整等によって、むしろ柔軟に弾力化の枠の中で。","id":"exchange-015"},{"speaker":"飯沼委員","kind":"質問・要望","question":"改正の内容が３点あるわけですけれども、まず、１番目の現状のところなんですけれども、指定福祉施設に、新たに特定施設が加えられたんですが、この指定福祉施設がどういう範囲なのか、まずおおもとの基本のところを教えていただきたい。それから、３点目、「区長が特に必要と認めた者」を「区長が指定する者」と変わるわけですけれども、この中味がどういうものなのか、教えてください。","respondent":"冨岡高齢福祉課長","answer":"第２条第３項第４号につきましては、老人居宅介護事業、老人デイサービス事業、短期入所事業、小規模多機能型居宅介護事業、認知症対応型老人共同生活援助事業、デイサービスセンター等々、いわゆる高齢者の事業について経営する事業です。","id":"exchange-016"},{"speaker":"飯沼委員","kind":"質問","question":"指定福祉施設というのが、ものすごく範囲が広いんだなと、改めて感じました。いろいろな施設に就職される方を応援していくという中味であるという認識を持ちました。そこにおいて、(3)で、そういう範囲の中で、さらに区長が指定をした場合に、ここに当たるという理解でよろしいんでしょうか。","respondent":"冨岡高齢福祉課長","answer":"具体的に、介護福祉専門学校を卒業される方がどこの法人に就業されるかということを踏まえまして、その方の免除を図っていくですので、その都度、規定をしているです。","id":"exchange-017"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今回の改正の理由で、新たにケアホーム西大井こうほうえんが該当していくための拡大と、受けとめるわけですけれども、特定施設の1)に有料老人ホームとあるんですけれども、今回はこうほうえんというお話なんですが、特定施設というのを加えることで、有料老人ホーム、株式会社でもオーケーという方向になるのか、どうか。それから、西五反田のケアホームがどういう扱いになるのかを教えていただきたい。","respondent":"冨岡高齢福祉課長","answer":"指定するものにつきましては、対象となる方が、卒業見込みが出て、就職の見込みが出る場合もありますので、そういうものを含めて、今回、拡大をしていただきたいということで、指定施設を条例の対象にさせていただいたということであります。","id":"exchange-018"},{"speaker":"飯沼委員","kind":"質問・要望","question":"現状は、社会福祉法人にある程度限定をされているのが、今後、拡大をされていく上で、特別養護老人ホームの人材不足に拍車をかけてしまうのではないかという心配をしているわけですけれども、その点をお伺いしたい。この中で、この免除を受けられた方がどのぐらいいらっしゃるのか、もしわかったら、教えていただきたいと思います。","respondent":"冨岡高齢福祉課長","answer":"何人ぐらいが免除されているかですけれども、免除者については、申しわけございませんが、数字を把握してございませんが、区内に就職された方ですと、平成１７年度が２２名、平成１８年度が２８名、平成１９年度が１７名ということになっております。","id":"exchange-019"},{"speaker":"阿部委員","kind":"確認","question":"先ほどの話の確認になるんですけれども、今回、新たに加わる特定施設というのは、事業主体にかかわらず、と理解してよろしいでしょうか。そうすると、例えばある会社がやっている区内の有料老人ホーム等に１年目に入ったとしても、翌年はほかのところに異動になるかもしれない。そういった捕捉なんかもするんでしょうか。それとも、そういうところに入れば、もういいのですか。そのあたりも教えてください。","respondent":"冨岡高齢福祉課長","answer":"民間事業者についてはどうなのかということでありますと、ある程度、経営が安定しているのかということも考えなきゃいけないということで、現在のところは、区内の事業をしていただいている法人、あとはケア協議会の事業者という形にさせていただいているです。","id":"exchange-020"},{"speaker":"阿部委員","kind":"質問","question":"先ほどもお伺いしたんですけれども、今後指定していくことになると、民間の場合、やっぱり区外も含めて異動なんかもあるだろうと。あまり固いことは言いたくないんですけれども、そういったことは捕捉をしていかれるのか、その辺の減免の扱いはどうなっているのか、教えてください。","respondent":"冨岡高齢福祉課長","answer":"チェックにつきましては、私どももサービスの事業内容について調査をしたりする部分もありますので、連携を取りながら、状況は大丈夫かという形で把握をしておりますので、具体的に何年おきにどうこうするという形ではしておりません。","id":"exchange-021"},{"speaker":"阿部委員","kind":"質問","question":"今後も、民間の介護業者といったところに就職された場合は、授業料の減免の対象にならないということでよろしいんでしょうか。それですと、逆にほかの疑問はわいてこないんですが。","respondent":"冨岡高齢福祉課長","answer":"すみません、ちょっと答弁不足で申しわけございません。民間の有料老人ホームにつきましては、区内だけの勤務ではございませんので、これについてはやらないという形で申し上げたです。","id":"exchange-022"},{"speaker":"阿部委員","kind":"質問","question":"特定施設のうち、有料老人ホームについては、民間事業者のものは減免の指定はしないということですか。逆に言えば、特定施設の中でも、例えば適合高齢者専用賃貸住宅などの民間業者だと、就職による免除の指定にある可能性はあるということなんですか。なんでそこに線引きがあるのか、よくわからない。ますますわからなくなってきたんですけれども。すみません、私の理解力不足でしょうか。","respondent":"木下福祉高齢事業部長","answer":"ちょっと整理をいたしますと、まず、基本的に、介護学校を卒業する学生がどこに就職するかということは、本人の自由なわけです。そういう中で、なるべく区内の福祉施設にきてもらいたい。若い学生ですから、在宅は難しいですから、おそらく通常は施設のほうに行きます。","id":"exchange-023"},{"speaker":"阿部委員","kind":"質問","question":"大体了解できたかなと思います。対象の大枠は広がったけれども、当面、民間は入ってこないというのが、現実的な品川区の選択ということでよろしいでしょうか。違うんでしょうか。","respondent":"木下福祉高齢事業部長","answer":"この後出てまいりますけれども、例えば都南病院跡の部分について言うと、まず法上の体系で言うと、あそこはケアハウス制度ですから、軽費老人ホームのほうで入ってきて、区の指定管理でやっていきますから、当然。","id":"exchange-024"},{"speaker":"鈴木（真）委員","kind":"質問","question":"都南病院跡の件はどうなるのかなと、ちょっと気になっていたんですけれども。ただこれは、ここまで条例改正していくと、どこが対象になったかというのは、我々議会側にはどういうふうにわかるのかなと、ちょっと今、気になったんです。要するに、対象になっているところを、議会側にどういうふうに出してもらえるのか。それとも出さないでいいという考え方なのか、そこだけちょっと教えてください。","respondent":"冨岡高齢福祉課長","answer":"募集案内とかという形では出ておりますけれども、今後、整理の仕方について、検討させていただきたいと思います。","id":"exchange-025"},{"speaker":"鈴木（真）委員","kind":"意見","question":"当然、専門学校の入学案内はあるけれども、それを議会が実際にもらってこない。状況の話といったときに、例えば、こういう委員会の中で報告事項でもいいんじゃないかなと、私は考えるんです。それ以上深く指定に反対するとかではなくて、どこか事業概要に出ているんでしたか。出ているんだったら、ごめんなさい、そこだけ気になっているんです。","respondent":"冨岡高齢福祉課長","answer":"ただいま、品川区の福祉という事業概要の中に入れる等を含めて、ちょっと検討させていただきたいと思います。","id":"exchange-026"},{"speaker":"浅野委員","kind":"質問・要望","question":"ここの部分につきましては力を入れていっていただきたいということ。この話ですと、償還ですけれども事由が生じた日の翌月から６カ月間据え置いて、５年間以内に償還ということですから、例えば、途中で退学をしたりやめちゃった人は、その日が事由の発生した日で、それから６カ月据え置いて、５年以内に返せばいいというような考え方なのか。ちょっと細かいことですけれども、お伺いしたいと思います。","respondent":"冨岡高齢福祉課長","answer":"短い期間で退職されて、また復帰された方についてはどうかですけれども、やはり３年ですので、２年以上につきましては月割でお返しいただくということになるかと思いますけれども、１回やめてまたお入りいただいても、お返しいただくです。","id":"exchange-027"},{"speaker":"浅野委員","kind":"意見","question":"決意をされて学校に入って、貸し付けを受けるという形になると思いますけれども、途中でほかのところに行ってしまうというのは、ある意味では悲しいことですので、そういう意味では、在学中からしっかりと介護の福祉人材を育てられるように、これからもよろしくお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-028"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"ちょっと確認をさせていただきたいのは、今回、特定施設ということで新たに入ることで、こうほうえんが入るのと、それから、今、既にやっている西五反田ケアホームはどうなるのか、一つ教えていただきたい。それから、ケア協議会の事業者が運営する福祉施設は、具体的にケア協議会の事業者は、今、どういう状況になっているのかということを教えていただきたいと思います。","respondent":"冨岡高齢福祉課長","answer":"西五反田ケアホームですけれども、これは、ケアハウスということで、既に社会福祉法上の部分に入っているです。それから、ケア協議会関係ですけれども、ホームヘルプ事業、あるいは、認知症のグループホーム温々というところが対象です。","id":"exchange-029"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"ケア協議会の事業者は何事業者あって、ヘルパーステーションとかも対象になるんですか。","respondent":"冨岡高齢福祉課長","answer":"ケア協議会の事業者は１０事業者です。ヘルパーステーションも対象になってくるです。","id":"exchange-030"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"品川ケア協議会の事業者の１０事業者は対象にするけれども、ほかの事業者は対象にしないという、多分、ケア協議会に入られているところには株式会社もあると思うんですけれども、そこら辺の、ケア協議会の事業者と、それ以外との線引きはどういうふうにされているのかということをお聞かせいただきたいと思います。そういうことに対しては、どう考えられているんでしょうか。","respondent":"冨岡高齢福祉課長","answer":"ほかの事業者についての指定とかの部分でありますけれども、やはり一つには、先ほど、お話もありましたように、修学生が介護の仕事につくためにどういう事業者を選んでいったらいいかという部分も含めて、安定した生活ができるということも考えておりますので。","id":"exchange-031"},{"speaker":"堺委員","kind":"質問・要望","question":"私なんか、単純に計算しますと、修学資金の貸し付けが、月５万円ですから、１年間で６０万円、修業年数が２年間ですから１２０万円で、区内の指定された事業所に３年間勤務すれば、その１２０万円が免除になるわけですから、そういう面では、いろいろな苦労があるかもしれないけれども、３年間、そこで一生懸命働いちゃおうかというような気もするんですけれども、ただ、働く側の人にしてみれば。","respondent":"冨岡高齢福祉課長","answer":"その中で、償還が免除になった方ですが、それぞれ卒業された方ですので、対応がずれておりますけれども、その年度でということでお答えすると、平成１６年度で１９名、平成１７年度２１名、平成１８年度２０名、平成１９年度２５名という数字でございまして。","id":"exchange-032"},{"speaker":"鈴木（ひ）副委員長","kind":"確認","question":"品川区の考え方としては、民間の有料老人ホームは対象にしないということで、それははっきりと確認をさせていただいて、この条文からすれば、区長が指定するという考え方になれば、指定できるとなっているわけですから、そこら辺の担保がどういうふうになっているのか、ちょっと改めて確認させてください。","respondent":"冨岡高齢福祉課長","answer":"今度、特定施設を条例の中に入れていただくということで、特別養護老人ホームにお勤めになる方が厳しい状況になるんじゃないかというご指摘ですが、特別養護老人ホームについては、区内にも１カ所ありますし、これから先を考えたときに。","id":"exchange-033"},{"speaker":"阿部委員","kind":"質問","question":"やっぱりちょっとはっきり頭の中で整理できない部分があるものですから、特定施設については、当面、こうほうえんのみということでご説明いただいたんですが、それ以外の、従来の対象になっていたところの、対象になる要件を備えた第一段階での施設と、実際に区長の指定を受けている施設と、後でも構いませんので、ちょっと教えていただけないでしょうか。","respondent":"木下福祉高齢事業部長","answer":"在宅は難しいので、これはある程度経験を重ねた人のほうがふさわしいわけです。施設系というと、今までの福祉基盤は何があったかというと、社会福祉法人、あるいは、区立の特別養護老人ホーム関係が中心なわけです。","id":"exchange-034"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"在宅でケア協議会のヘルパーステーションとかは、実際にはそんなに希望する人がいないというのが実態なのかもしれないんですけれども、ケア協議会だけに限らず、いろいろなヘルパーステーションも、もう介護保険が始まって８年経つわけですから、品川区の中で実績を積んでいるので、ケア協議会に限らずに、品川区で実績を積んでいるところであれば、そこに就職したいということがあれば。","respondent":"冨岡高齢福祉課長","answer":"もう一つのヘルパーステーションの問題ですけれども、やはり、修業生が長く同じ事業所で働いていただくですけれども、現在のところは、ケア協議会が、ある程度実績を積んでやっているということで考えているわけで、今後につきましては、またいろいろな評価ができれば。","id":"exchange-035"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"西五反田はさくら会立ですけれども、そこを運営しているのはマザアスだと思うんですよ。そういう点で言うと、特別養護老人ホームなんかは、介護報酬しかないという中で経営をやりくりせざるを得ない、そういう中でぎりぎりで何をしてもらえるのかという悲鳴のような状況の中で、そこのところがますます大変になっていくというような感じがして仕方ないんですけれども、いかがでしょうか。","respondent":"木下福祉高齢事業部長","answer":"特別養護老人ホームのほうが賃金が低いんじゃないかということを前提に言われていたと思うんですけれども、必ずしもそういうことはないと思います。そういう点では、今、危惧されたようなことは、心配ありませんということを申し上げたいと思います。","id":"exchange-036"},{"speaker":"鈴木（真）委員","kind":"質問","question":"実際に、この修学資金の免除を受けて喜んでいる方を何人もお聞きしています。この条例の第１条の最後のほうにありますけれども、「介護福祉士の確保を図り、もって地域福祉の向上に寄与することを目的とする」という条例の趣旨からしましても、本件には賛成いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"飯沼委員","kind":"意見","question":"苦渋の選択ですけれども、反対いたします。区内の特別養護老人ホームの存続を、という立場で、今の時期での拡大は時期尚早ではないかといった立場で反対いたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-038"},{"speaker":"阿部委員","kind":"意見","question":"この条例そのものには賛成いたします。ただ、対象になる施設について、ちょっとわかりにくいところもありますので、条例そのものではなくて、条件等も含めて、わかりやすく何かの形でお示しいただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-039"},{"speaker":"阿部委員","kind":"質問","question":"今、創意工夫を生かした運用というのが何度か出てきたんですけれども、ちょっと浮気な話になってしまうんですが、裏にもあるように、区立シルバーセンターは幾つもあると思うんです。すみません、ちょっと外れてしまうかもしれないんですけれども、西大井以外のところでの、日々の創意工夫というのは、シルバーセンターはどうなっているのかということを、まずお聞きしたいと思います。","respondent":"永尾高齢事業課長","answer":"というのは、区のほうで検討をして、実際に運営を委託しているのはシルバー人材センターの受付等の担当になるというような流れになっているんですけれども、ただ、こうほうえんというのは、そういうものについてかなり専門的な経験と知識があるですので、今後の試験的というか。","id":"exchange-040"},{"speaker":"阿部委員","kind":"質問","question":"さらに離れてしまったらごめんなさい。今後、ここ以外の、つまり区立で残るシルバーセンターについても、例えば民営化ですとか、あるいは、ある種施設を地域に任せていくとか、そういったことも含めて検討されるということなんでしょうか。","respondent":"永尾高齢事業課長","answer":"ほかのシルバーセンターにつきましては、今のところは、民営化するのか、それとも地域に任せるかという決定はしていないんですけれども、今回の西大井の状況を見まして、それが効率的で好評であれば、そういうことも一つの考えとして検討していってもいいかと考えています。","id":"exchange-041"},{"speaker":"飯沼委員","kind":"質問・要望","question":"シルバーセンターなんですけれども、以前は敬老会館とかいった名前で呼ばれていたわけですけれども、根拠となる法律が老人福祉法だと、ちらっと伺ったんですが、どこに規定してあるのか、まずその辺をお伺いしたい。なぜかというところに答えていただきたいと思います。","respondent":"永尾高齢事業課長","answer":"次の質問なんですけれども、なぜ民設民営にしたかですけれども、指定の法人がこうほうえんで行うということで、一緒に建てておりますケアホームの関係で、ケアホームのほうの高齢者優良賃貸住宅制度を利用することになりますと、民間でないとできないという決まりがあります。","id":"exchange-042"},{"speaker":"飯沼委員","kind":"質問","question":"別にそれで不都合はないのではないかと思っていることが１点です。今回、この間、ずっと西大井シルバーセンターを移すという言葉を使っていらしたんですよね。どこがどう変わるのかというところを、もうちょっと聞きたい。それから、民間になるということで、ほかの１５のシルバーセンターと同じようなチェックというか、中味がわかって、議会に伝わって、意思疎通ができるのかどうか。その点もお伺いします。","respondent":"永尾高齢事業課長","answer":"ただ、この二つの協定と助成金要綱だけですと、シルバーセンターのほうだけを見てみますと、細かいところについての規定がいま一つはっきりしていないという部分がありますので、やはり今までの西大井シルバーセンターの事業を継続するということと。","id":"exchange-043"},{"speaker":"飯沼委員","kind":"質問","question":"ここを機会に、新しい試みをしながらということですが、今あるシルバーセンターを全部、民設民営の方向に持っていくのかという危惧さえ持ってしまうというか、そういうことが、なぜ今この時点で必要なのかと思います。それから、助成金要綱に基づいて助成金を出して、そこで運営をしていくということですけれども、従来の委託の場合と助成金との場合で、どういうふうに変わるのか、中味を教えてください。","respondent":"永尾高齢事業課長","answer":"二つ目のチェックの関係ですけれども、今、実施協定については、こうほうえんと調整をしているところで、まだ発表には至っていないんですけれども、先ほど説明をいたしました、従来のシルバーセンターを継続するというところは、細かいところまでの規定は。","id":"exchange-044"},{"speaker":"飯沼委員","kind":"質問・要望","question":"委託と助成金のところは、金額的にどのぐらい変わってくるのかを教えていただきたい。それから、協定書は、今、つくっている最中ということですけれども、私は、変化の内容も伺ったから、世代を超えた交流と、今までのシルバーセンターではなくて、もうちょっと違った部分も加味していくととらえたんです。それから、さっきの委託と助成金の、金額的なものも教えてください。","respondent":"永尾高齢事業課長","answer":"今後のシルバーセンターのあり方の部分ですけれども、やはり今までの長い歴史がありますので、急に変えるということに対して、やはり反対の意見をお持ちの方もいらっしゃるし、また賛成の意見をお持ちの方もいらっしゃるということで、改修にあわせて、その辺の検討をしながら。","id":"exchange-045"},{"speaker":"浅野委員","kind":"質問・要望","question":"これにつきましては、ぜひとも高齢者が過ごしやすい施設を、これからも維持していっていただきたいという要望が一つあります。これについては、要望だけです。この場にはそぐわないかもしれませんけれども、この点をお願いしたいということです。それから、どういう紹介の仕方をするのか、また、この扱いについて。もう３月は迫っているわけですので、ここら辺の計画等を教えていただければと思います。","respondent":"永尾高齢事業課長","answer":"シルバーセンターの箇所数ですけれども、民設民営と言えども、シルバーセンターには変わりはありませんので、１６カ所という表示はそのまま継続する予定です。","id":"exchange-046"},{"speaker":"阿部委員","kind":"質問","question":"すみません、今のお話に関連してなんですけれども、ということは、新しい民設民営のシルバーセンターについては、特に品川区の条例のどこにも書かれないことになるんでしょうか。例えば、これが区立ではなくてシルバーセンター条例か何かで、区立１５館、私立１館とかだと全体がわかるかなと思うんですが、ちょっとその辺はどうなんでしょうか。","respondent":"永尾高齢事業課長","answer":"民設民営になりますと、公の施設という扱いにならないので、条例の中には入ってこなくなります。普通財産という扱いを行いますので、普通財産として、こうほうえんに貸し付けをするというような形態になります。","id":"exchange-047"},{"speaker":"阿部委員","kind":"質問","question":"とすると、シルバーセンターの職員の研修なんかがあるかどうかわからないんですけれども、その辺の例えば資質向上のための何かがあるときは、多分、私立のほうの方も対象になるかと思うんですけれども、全くそういうものは何もないんでしょうか。それとも、全くないけれども、個別に声がかかるとか、そういう状況になるんでしょうか。扱いというか、位置づけがあいまいになっちゃうかなと思ったんです。","respondent":"永尾高齢事業課長","answer":"実施協定の中で、シルバーセンターで、現在、毎月、事務連絡会というのを行っておりますので、そちらにも参加するというようなところも定める予定になっております。","id":"exchange-048"},{"speaker":"阿部委員","kind":"質問","question":"とすると、条例規則その他のところで同列に扱われることはないけれども、事実上の運営では仲間に入れますということが、今後、私立のものが増えたとしても、個別にそういう声かけだけはするという関係なんですか。","respondent":"永尾高齢事業課長","answer":"今のご質問のとおり、シルバーセンターの従来の機能自体は変更する予定はありませんので、その辺はきちんと実施協定の中で定めて、運用していこうと考えております。","id":"exchange-049"},{"speaker":"阿部委員","kind":"意見","question":"私も、それが将来的にどういう影響を持ってくるか、ちょっとまだ予測できないんですけれども、少なくとも区民の目に触れるところでは、例えばホームページでも、シルバーセンターとなれば、１５プラス１が出てくるとか、多分従来と変わらない形なんだと思いますけれども、将来的にも、私立であることで何か違いが出てこないような、位置づけ上の違いがマイナスに働かないようにお願いします。","respondent":"永尾高齢事業課長","answer":"実施協定は、今、考えているところですので、そういうところも中に盛り込む形で検討していきたいと思います。","id":"exchange-050"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"今のお話を聞いていて、今度のこうほうえんに移行するということですけれども、そうすると、民設民営ということで、老人福祉法に定める施設ではなくなるということになるんでしょうか。それが１点。それから、あとはこうほうえんが専門的な経験と知識があるということだったんですけれども、そこら辺の中味について、教えてください。","respondent":"永尾高齢事業課長","answer":"こうほうえんの専門的な知識ですけれども、こうほうえんも、地元でかなりいろいろな事業をやっているし、ほかの区でも事業をやっているということですので、そこら辺のノウハウを活用していきたいと考えております。","id":"exchange-051"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"地元でこうほうえんがシルバーセンターというか、敬老会館の委託を受けて、そういう実績があるということなんでしょうか。","respondent":"永尾高齢事業課長","answer":"シルバーセンターの運営につきましては、こうほうえん自体としては経験があるわけではありませんが、高齢者関係のいろいろな施設等での地域の交流等はやっていると伺っております。","id":"exchange-052"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"はじめは区立にして、指定管理者制度とずっと思っていたんですけれども、それがなぜだめなのかというところを、もうちょっとお聞かせいただきたい。それからもう一つ、利用者にとっての使い勝手というか、そういうところでは変わらないのか、どうなのか。そこもあわせてお聞かせください。","respondent":"永尾高齢事業課長","answer":"料金につきましても、目的外については、今、検討中ですが、ほかのシルバーセンターと同じような基準で検討をしています。","id":"exchange-053"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"指定管理者では経費の節減にはならないということなんですけれども、利用料を取らないというところで、そういうことになっていくということなんでしょうか。それから、さっき、今までの西大井シルバーセンターと、今度の移行したところでは、シルバーセンターという名前は使わないのかどうかということも、一つお聞かせいただきたいんです。そのことを、ちょっとお聞かせください。","respondent":"永尾高齢事業課長","answer":"今までのシルバーセンターより、今度のシルバーセンターのサービス内容が充実するかですけれども、今までのはそのまま継承して、さらに上乗せで考えております。","id":"exchange-054"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"一部改正の条例については賛成です。利用者は、今、資料を見ると、１年間に２万人からが使っていらっしゃるので、利用率が高いので、これからもうまく運営のほうに、区のほうも十分に注意していっていただきたいということをお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-055"},{"speaker":"堺委員","kind":"質問","question":"公明党も、この件については賛成です。今、鈴木真澄委員からもお話がございましたように、ここは非常に利用者が多いですから、こういう形になっても、利用する側の人に、従来よりさらにサービスがよくなったと言われるように、ひとつしっかりお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-056"},{"speaker":"飯沼委員","kind":"意見","question":"予算もどのぐらいだかわからないし、協定も、今、詳細なところはつくっているところであるということで、議会に全く示されないで、どのぐらいの規模なのか、建物の形状は図面でわかりましたけれども、どういった中味なのか、ほんとうに不明瞭なままです。区有の財産を民間に渡していくということで、なぜここで踏み切らなくてはいけないのかということに、大きな疑問を持ちましたので、反対します。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-057"},{"speaker":"阿部委員","kind":"意見","question":"私は賛成です。この移行によって、ここのシルバーセンターだけではなくて、区全体のシルバーセンターの活性化の一つの契機になればいいなと考えています。ただ、民設民営ということで、このセンターが他のセンターと比べて不利のないように詳細に詰めていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-058"},{"speaker":"阿部委員","kind":"質問","question":"あまり少なければ、もう１回募集のかけ直しなんていうこともあり得たのではないかなと思うんですけれども、２団体の中で選ぶというのは、実際にこの趣旨から言ってどうなんだろうかということ。これは２社での共同事業体で、指定管理者となるということで、それぞれには、それなりの実績があると書かれていますが、２社で一緒にやる実績があるのかどうかということを教えてください。その２点を。","respondent":"山岡健康課長","answer":"２団体だけで、透明性が確保されているかというご質問ですけれども、実は、先ほど申し上げましたように、提案説明会のほうには９事業者が参加しました。","id":"exchange-059"},{"speaker":"阿部委員","kind":"質問","question":"要は、２種類の趣の違う仕事を一遍にやってくれるところは、この組み合わせしかないということになると、ますます、そもそも選べる選択肢がすごく狭き門であるということになってしまって、では何でそこまでして、できる人がぐっと減ってしまうやり方で募集したのだろうかと、そこまで疑問が出てしまうんです。指定管理ではないんですか、ごめんなさい、今の話はなしです。前半の質問だけです、すみません。","respondent":"山岡健康課長","answer":"結果として、こういう事業体という形の応募が２団体あったです。事業者側で、よりよい事業運営をするには、そのほうがよいと判断したんだと思います。結果として、２団体になったということだと思います。決して、少なくなるように、私どものほうで考えたわけではございません。","id":"exchange-060"},{"speaker":"飯沼委員","kind":"質問・要望","question":"改めて、今までの委託、コナミから新たに指定管理者になって、ここが選定された理由を、もうちょっと中味を教えていただきたいんです。今までとどこがどう違ってきているのか、お話ししていただきたい。それから、住友不動産エスフォルタ株式会社は、従業員が３５８名、売上高約７０億円と書いてありますけれども、従業員というのは正規職員のことですよね。","respondent":"山岡健康課長","answer":"事業の内容につきましては、基本的には、教室、コース、フリー、あるいはコース立ては、この辺は原則として継続してやっていただきたい、事業運営については、同じような形でやっていただきたいとしております。","id":"exchange-061"},{"speaker":"飯沼委員","kind":"質問","question":"区民の健康状態がどうなっているのか、かつ、どういう悩みを持っているのかと。私が、今日、どんな事業内容になるんですかと聞いた中味がそこなんですよね。その点と、それからコナミの職員の方が、今後どうなるのか、ちょっとお伺いしたい。利用者が、結構、えっ、そっくり変わっちゃうんですかと、以前変わったときにも、とても評判が悪かったんです。どうしてなのかと。","respondent":"山岡健康課長","answer":"職業の選択の自由がありますから、私どもでいかんともしがたい部分もありますけれども、今やっている事業者および新しく指定管理になる事業者の両方に、私どもが中に入って調整をして、ある程度継続してやっていただけるようなことができないか。","id":"exchange-062"},{"speaker":"飯沼委員","kind":"質問・要望","question":"最後のところなんですけれども、ほんとうにぴったり自分のことをよくわかって指導してくださるというところで、インストラクターの存在って大きいので、ぜひ、区ができるところは十分に中継ぎをしていただいて、首切りにならないで継続して働いていただけるようにしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-063"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"前のときに、たしか４階をどう活用するかという質疑もあったと思ったんですけれども、今回、どんなプロポーザルで出てきているのかというのが１点。今後、指定管理になったときに、運営事業者としてのエスフォルタのほうは、その辺の判断を変えることがないのか、その点の確認をお願いします。","respondent":"山岡健康課長","answer":"これは一つの提案ですので、今後、議決をいただきまして、正式決定になった後、協定を結ぶ際に、どのようにやっていくか協議をしてまいりたいと考えております。レストランの継続ではなくて、違う展開のほうが、私どもも、よろしいのではないかと考えております。","id":"exchange-064"},{"speaker":"鈴木（真）委員","kind":"確認","question":"大体わかりました。今ので、１点、確認だけ。コースが４月から変わるということは、２月、３月にはもう申し込みが入ってきますよね。そこは、電話でも何でも、今の委託先が申し込みを受けるんですか。そこのところをやっぱり気をつけてうまくやっていかないと、後でトラブルになっても困ると思いますので、その辺もう１回、ちょっとお願いします。","respondent":"山岡健康課長","answer":"基本的には、４月から使う部分については利用料金制ですので、指定管理者の収入に入る部分です。正式に決まった後、これから急いで調整したいと思いますけれども、新しい事業者が受け付けできるような形を取れないかということで、検討してまいりたいと思います。","id":"exchange-065"},{"speaker":"浅野委員","kind":"質問","question":"今、私が疑問に思っていたところを、ほとんどお話を聞いたわけですけれども、保健センターのほうで、こちらのほうは事業運営と、施設管理を含めての指定管理ということですけれども、先ほどの説明ですと、４階から上と３階会議室を利用されるということで、施設管理の範囲も、ここだけなのかどうかということ。ここの１点を、お伺いしたいと思います。","respondent":"山岡健康課長","answer":"施設維持管理の範囲です。先ほど、申し上げました、健康づくり部分、４階から上、それから３階の会議室は一般貸し出しをしておりますので、この貸出運営につきましても指定管理者にお願いする予定です。","id":"exchange-066"},{"speaker":"浅野委員","kind":"質問","question":"例えば、施設管理をこの業者がやっていたのかどうか、私も調べていないので、わからないんですけれども、何らかの応募が難しかったのかなと思われるところも、今回の中味ではあるかと思うんです。もし差し支えない範囲で、お話を伺えたらと思うんです。今までの委託業者が、今回選ばれなかったということに関して、ご回答できる範囲で結構ですので、お願いします。","respondent":"山岡健康課長","answer":"現在、やっている事業者がそのままできないということではございません。十分にやる能力はあろうかと思いますけれども、より優れていたと、お考えいただければと思います。","id":"exchange-067"},{"speaker":"堺委員","kind":"質問","question":"今、うちの浅野委員から質問ありましたように、今回、選定されたところのほうが、前に比べるとよりいいサービスの提供の可能性があるというか、できるというか、そういうことで、選考基準にのっとって、次年度からここにするですので、公明党としては賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-068"},{"speaker":"飯沼委員","kind":"意見","question":"反対です。どれだけ増やして利用料で利潤が上げられるのかというところは、大変疑問です。利益を上げるということは、先ほども申し上げましたように、職員、人件費を削るということにおいては、この間、ほんとうに不安定雇用を増やしていて、こういうことを区が率先してやるべきではないと思っていますので、民間が指定管理者になることについては反対をいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-069"},{"speaker":"阿部委員","kind":"意見","question":"結論としては、賛成です。が、この件に限らず、指定管理者に関する議論は、どこかやはり限界といいますか、無力感というか、感じます。あるいは、心証を形成するところまでしかなかなか議会では議論が尽くせないというところに、少々の限界を感じつつも、この件については賛成です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-070"},{"speaker":"飯沼委員","kind":"質問・要望","question":"４の(1)候補者選定の方針のところで、運営者に連続性が要求されるため、候補者を公募によらなかったと、この辺は十分に理解するんですけれども、内容的なところで、９月３０日に、指定管理者管理に対するモニタリング評価の結果というのが出されましたけれども、この中味で、例えば改善が必要な事項とか、幾つかあったので、今後またさらに指定管理者を新たにするというところにおいて。","respondent":"小林保育課長","answer":"私ども、団体と新たな保育園、保育者、そして親との子育ての連携を強化して、パートナーとして一緒に子育てをしていこうといったときに、短い時間だとしても、保護者がどういうかかわりを持って子どもとのきずなを深めていってくれるのかという点から言うと。","id":"exchange-071"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そういうところにおいて、精神的に親子のきずなが大事だという援助は、ほんとうに大いにしていっていただきたいし、また、そういった面は、きっと施設の中だけでは完結しなくて、社会全体の問題点を改善していくような力にも、お母さんやお父さん自身にも向かってほしいし、施設を運営していて、そういう問題に直面をしていらっしゃる施設の方々も一体になって。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-072"},{"speaker":"阿部委員","kind":"質問・要望","question":"１点目は、今のお話と重なるところが多いので、簡単に言います。ぷりすくーるの理念は、ほんとうにおっしゃるとおり、わかるんですけれども、オープン当時は、あそこは０、１、２歳児は保育園の子どもでしたが、３、４、５歳児はわりと幼稚園型の利用といいますか、あまり長時間就労していないご家庭の利用がほとんどだったと思います。これは要望です。そこのところを、少しご意見をいただければと思います。","respondent":"小林保育課長","answer":"もう一つは、この指定管理者の意義でもあろうかと思うんですけれども、基本的な目的を共有化したら、その実行段階のプロセスについては、相手の裁量を認め、いわゆる人、物、金の経営資源の配分については、ある意味で柔軟に相手の進捗を見守るという形でも。","id":"exchange-073"},{"speaker":"浅野委員","kind":"質問","question":"候補者選定の件ですけれども、運営者に連続性が要求されるため、候補者を公募によらない事業者として選定するです。今回のＮＰＯにつきましては、前回が最初ということで、過去の議事録を引っ張り出しましたら、５年前にも、ＮＰＯとの関係とか、いろいろな論議があったかと思われます。ちょっと事業の継続性の観点から質問をします。","respondent":"小林保育課長","answer":"何からの特別な事情により、一時的にそれが期待できなくなったとき、その後の事業の受託の団体を探すまでの間は、あくまでも、これは区の方針に従ってやっている幼児教育の取り組みですので、相当期間、区直営でその間、それを継続して。","id":"exchange-074"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"ぷりすくーるを開設した当時、ちょうど私も厚生委員会にいたので、その当時から、ときどきぷりすくーるにお邪魔することがあるんです。だから、区のほうで申し込みを受ける段階において、そこら辺のところをよくお願いしたい、理解を得るような形をとってもらいたいんですが、そこら辺をもう１回、お答えいただきたいと思います。","respondent":"小林保育課長、古川児童保健事業部長","answer":"０歳、１歳、２歳と進む中で、その大切さと、得られる成果を十分に、保護者会等で運営者も説明していくという形で、引き続きご理解が得られるように努めてまいりたいと考えております。一言だけ。時間が長くなって大変恐縮ですが、ぷりすくーるのこの５年間に関して、保育課長のほうから、ご説明させていただきました。","id":"exchange-075"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"大変よくわかりました。今、思い出したのは、開設のときに、厚生労働省の課長と文部科学省の課長が２人並んで、初めて座ったということを思い出しました。議決はこれからですから、まだ決まってはいないですけれども、ぜひこれからも、主導のほうも一緒に、うまくその辺はやっていっていただきたいとお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-076"},{"speaker":"堺委員","kind":"意見","question":"それでもあえて選考基準にのっとって、再度選定した結果、候補者の選定理由ということで、３点にわたって理由を述べられています。運用者の連続性が要求されるという視点からも、公募によらない形をとりながら、子育て品川を今回も選定をされるということについては、冒頭に申し上げましたように、我々も十分に理解できますので、賛成としたいと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-077"},{"speaker":"飯沼委員","kind":"提案","question":"先ほどの指定管理者のところでも伺ったんですが、今回のところも、結構あちこちで事業展開をされているし、今回は品川区の提案をされているということで、福祉の仕事はよい仕事をしていただくためには人手が大事というところで、先ほども伺ったんですが、職員配置をここでぜひ答えていただきたいのは、正規職員とか、非正規職員の割合とか、離職率とか、その辺。","respondent":"冨岡高齢福祉課長","answer":"職員配置といいますか、今の大起エンゼルヘルプに職員が何人いてという内訳等の話だと思いますが、これにつきましては、申しわけありません、ちょっと把握しておりません。","id":"exchange-078"},{"speaker":"飯沼委員","kind":"質問","question":"やっぱり、どういう姿勢でこの仕事に当たっているのかというところがすごく大事なんですが、この間、品川区も、厚生委員会でも視察に伺ったり、個人的にもあちこちの法人に伺って、お話を聞いたりして、やはり社会福祉の仕事というのは、子どもから障害者にも、高齢者にも、どういう思いで仕事をしていくのか、何を大事にしてこの仕事をしていくのかという理念がものすごく大事であると思っているんです。","respondent":"冨岡高齢福祉課長","answer":"今回、お願いします施設は、やはり地域密着型の多機能ホームですので、例えば小規模多機能型の施設を運営したことがあるのか、ユニットケアに実績があるのか、あるいは認知症のグループホームを運営に実績があるのかというところを考えますと。","id":"exchange-079"},{"speaker":"飯沼委員","kind":"意見","question":"さっきのところで、職員の配置は全く把握していないというか、職員の状況を把握しないで選定ができるのか、どうか。選定をするときに、そういった情報というか、資料が提出されているのか、どうか。ちょっとそこをお聞かせください。","respondent":"冨岡高齢福祉課長","answer":"職員配置につきましては、申請事由の中に、事業所としては出ているところです。それから、人員ですけれども、１対２以上を目指していきたいと考えているところです。","id":"exchange-080"},{"speaker":"飯沼委員","kind":"意見","question":"１対２ということで、かなり努力をされているのかなと思いますけれども、そこのところだけではなくて、ほんとうにこういう職場は、非正規の方たちの支えがすごく大きくて、その辺を含めないと、離職率なんかも出ないですよね。正規職員だけの離職率を出していても、そういうのってしっかり把握して、働いている方がどういう条件で働いているのかということも、把握しているんでしょうね。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-081"},{"speaker":"鈴木（真）委員","kind":"確認","question":"平成１８年５月に報告をいただいて、その時点で大起エンゼルヘルプということで出ていて、正式な決定になるわけですけれども、その前に、最終確認もなさっているということで、中味は全然心配していないけれども、私ども実は、この前、方南二丁目の小規模多機能の施設を見せてもらいに行ってきました。なかなかアットホームだし、地域で４棟か、５棟か建ててやっている。","respondent":"冨岡高齢福祉課長","answer":"おっしゃったとおり、指定管理が決まってからですけれども、その段階で内々の話を始めまして、地域の方に来て食べていただけるような、大井町食堂という名前がついております。そういう方向で、介護予防も含めて進めてまいりたいと思っているところです。","id":"exchange-082"},{"speaker":"阿部委員","kind":"確認","question":"すみません、ちょっと本質から外れるんですけれども、午前中の話を多少ひきずっておりまして、確認なんですが、こちらでお仕事をされる方は、介護福祉専門学校の、例の修学資金減免というか、免除の対象になるのでしょうか。","respondent":"冨岡高齢福祉課長","answer":"事業といたしましては、小規模多機能もすべて入っておりますので、対象になります。","id":"exchange-083"},{"speaker":"阿部委員","kind":"質問","question":"こちらは、異動はないんですかね。要は、ここに入って、現地採用ということでずっといらっしゃるのか。大起エンゼルヘルプは数カ所で展開されていますので、異動もあるのか、その辺、おわかりでしたら教えてください。","respondent":"冨岡高齢福祉課長","answer":"あくまでも介護福祉専門学校の修学生が、区内施設で３年間お勤めいただくということを前提で償還を免除するという制度ですから、入った途端に移られて、その事業だからというわけにはいかないと理解しています。","id":"exchange-084"},{"speaker":"阿部委員","kind":"質問","question":"考え方として、それでいいと思うんですけれども、要は、その対象になった方のそのときどきの勤務地というのは、異動しましたということは、それぞれ個人の異動の状況についても、事業者から区、学校に報告が来るようになっているんですか。その仕組みができていれば、全然問題ないと思います。","respondent":"冨岡高齢福祉課長","answer":"こちらの法人に話をして免除していることですので、異動があれば、当然、報告をいただくです。","id":"exchange-085"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"これを見ていたら、ほんとうに職員体制は大丈夫なんだろうかという思いがしたんです。ここのほかの施設のそういう状況、体制とか、経営の状況とか、そしてまた、先ほど、２対１ということで、職員の配置についてはご答弁がありましたけれども、これは正規職員が２対１ということになるのか、しかも資格というところもきちんと保証されるのか、そこら辺をひとつお聞かせいただきたいと思います。","respondent":"冨岡高齢福祉課長","answer":"１対２、１.０の話ですけれども、これは、常勤換算して、当然、そういう話と理解をしています。","id":"exchange-086"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"エンゼルヘルプのインターネットを見ると、そういう状況なので、ほかの施設の職員体制の把握とかはされていますでしょうか。それから経営状態がどういう状況になっているのか。そういうところとか、ほかの社会福祉法人もあったと思うんですけれども、そういうところではなくて大起エンゼルヘルプにしたところが、いま一つよくわからないので、そこもあわせてお聞かせいただきたいと思います。","respondent":"冨岡高齢福祉課長","answer":"それはご案内のとおりですけれども、やはり適格性を考えます場合に、利用者へのサービスの問題、それから、施設の維持管理、今のこの複合施設を維持管理する部分、それから、収支計画の問題等、家族の保護者会との懇談とか、いわゆるさまざまな評価点で総合的に判断いたしまして。","id":"exchange-087"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"それで、今回の大起エンゼルヘルプの地域密着型多機能ホームですけれども、ケアホームの収支がどうなっていくのかというあたりも、お聞かせいただきたいんです。このケアホームが２対１という人員配置になって、利用料とかはどうなっていくのか。それから、全体の総事業費と補助金もどのぐらいになったのか、改めて、ちょっと教えていただけたらと思います。","respondent":"冨岡高齢福祉課長","answer":"それから先ほど申し上げましたように、これは４月１日から管理が始まるということで、すべて新年度に属する話ですので、予算編成の問題もございまして、今のところ、最終的には、まだ細かい数字までは固めておらない状況です。","id":"exchange-088"},{"speaker":"鈴木（ひ）副委員長","kind":"提案","question":"前の委員会のときには、多分、大起エンゼルヘルプのほうからの提案でも、ケアホームのほうは大体２０万円ぐらいということで出ていたんじゃないかと思うんですけれども、そういうところで、原小学校跡のほうには、品川区のほうから助成金を出して部屋代を安くするということが、対策としてとられるようになりますけれども、あそことここは同時期にできるわけですけれども、同じような施設で。","respondent":"冨岡高齢福祉課長","answer":"その辺のところがベースで、具体的にどういうふうに、今回の部分が決まっていくのかということになるかと思いますけれども、これは申しわけありません、先ほどの大体２０万円前後ということは申し上げられますけれども、今後、調整して。","id":"exchange-089"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"でも、区民からすると同じような施設で、名前、中味も同じようであれば、やっぱり利用料は、当然同じようでないと納得いかないと思いますので、利用料については、これから検討されるということであれば、ぜひ、こちらのほうも２０万円前後でずっといくんじゃなくて、それは検討をよろしくお願いしたいと思います。","respondent":"木下福祉高齢事業部長","answer":"そうすると、グループホームは、区内については、大体介護保険の１割負担も入れて、約１７万円ぐらいでやってありますから、ケアホームという性格から言うと、その辺よりももう少し上ぐらいの数字だろうということで、大体２０万円ぐらいということを。","id":"exchange-090"},{"speaker":"鈴木（真）委員","kind":"意見","question":"賛成です。先ほども、質疑の中でちょっと話しましたけれども、１０月に選定委員会をもう１回開いたということも、十分に正しいやり方だと思います。それから、当初、プロポーザルしたときの思いとか、保育園との交流ということもずっと出ておりますので、この候補者に対して賛成します。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-091"},{"speaker":"堺委員","kind":"確認","question":"理由は、今、鈴木真澄委員がおっしゃっていたこととダブりますが、これについては、当初、８事業者から応募があって、学識経験者や地域福祉代表等で構成する選定委員会の中で、まずは、８事業者から５事業者、またその中から３事業者を選定しながら、何回かヒアリングを経ながら、平成１８年５月には一たん候補者を決定したけれども、なおかつ、平成２０年１０月２４日に。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-092"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"共産党としては、反対ということでお願いしたいと思います。そういうところで、選定というところでの議会への資料の提供というところも、まだまだほんとうに不足をしている状況なので、これからぜひ改善をしていただきたいということも合わせて、お願いしたいところです。今回は株式会社というところが介護の指定管理者にはなじまないというところで、反対をします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-093"},{"speaker":"阿部委員","kind":"質問","question":"結論から言えば、賛成です。ただ、福祉系サービスで指定管理者制度を使う場合で、民間事業者に指定管理をする場合は、やっぱり民間ですから、その会社に何かあったときにどうするかという仕組みを、ここだけではなくて、ある程度仕組みをつくっておく必要があるだろうなと、一方で思っております。今回のこの件については、まずは大起エンゼルヘルプにお願いするということで、よろしいかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-094"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"選定理由の中にあるように、区と一体になって福祉行政を行っているという意味で、このまま社会福祉法人品川総合福祉センターの指定管理をやっていただきたいと思いますので、賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-095"},{"speaker":"堺委員","kind":"意見","question":"賛成です。なお選考基準、あるいは選定理由の中にも、今、事業をやっていただいているところは、ここにもあるように、設立当初から区と一体となって福祉行政を推進してきた大きな実績があり、また来年度からも事業を予定している障害者自立訓練センター事業についても、質の高いサービスが期待できるという面から言っても、何ら問題はないと判断をいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-096"},{"speaker":"飯沼委員","kind":"意見","question":"昨年４月から障害者生活支援センターが開設されて、今、区内の障害者のケアマネージメントが始まっていますけれども、障害者自立支援法が始まって以来、障害者の方々の立場に立った福祉が組み立てられるように、一層のケアマネージメントの充実を期待して、賛成いたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-097"}]},{"id":"topic-03","title":"請願・陳情審査","agenda":"請願・陳情審査","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"区への影響はどういうふうになっていくのか。今、区の段階で、国の動向をどのように、どこをどうとらえていらっしゃるのか、ちょっとその辺を具体的に教えてください。","respondent":"小林保育課長","answer":"本年度中に検討に着手し、ということで、５月段階で情報を入手しておりますので、今後もその状況について、動向を注視してまいりたいと考えています。現段階で内容がわかりませんので、それに対するコメントは差し控えします。","id":"exchange-098"},{"speaker":"飯沼委員","kind":"質問","question":"５月段階の情報ということですけれども、かなり明確に何点か絞り込んで出ていると思うんです。今年度中にまとめて、これから先のことを示すって、品川区は、今、長期基本計画で中味も策定中ですけれども、かなり先を見通して計画も立てていると思うんですが、この辺の影響は、既にもう検討をされていると思うんですが、再度、お伺いします。","respondent":"小林保育課長","answer":"それぞれ基本的な考え方、方向性につきましては、その結果、影響が出るところがあろうかと思いますが、その内容をよく検討してみないと、具体的な対応は考えられないところですし、いずれにいたしましても、品川区として、区の乳幼児に対して。","id":"exchange-099"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ちょっと質問の角度を変えますけれども、児童福祉法には、国と自治体の保育に係る責任が、私は主に三つ明記されていると思うんです。この三つの責任が、公的保育制度が崩れたら、保育園がどうなるのか。具体的にこの三つが崩れたとしたら、今の保育園がどういうふうになっていくのかというところを、見通しも含めて、教えていただきたいと思います。","respondent":"小林保育課長","answer":"社会的な変化や、保育を取り巻く環境の変化に適合しながら、各世代の理解と納得が得られる、そして子どもがすくすくと育てられるような環境を、みんなでつくっていく。そういった検討の途上に、今あるのであろうと考えております。","id":"exchange-100"},{"speaker":"飯沼委員","kind":"質問","question":"保育課長の姿勢は、大変よろしいかと思います。公立の保育園よりも、認証や認定子ども園を足した数のほうが３倍ぐらい多くなっているということで、ほんとうに企業化が進んでいるわけです。この辺の認識は、いかがでしょうか。だから、既に起こっているこの現象について、どうとらえているのか。私は崩れていると思うんですが、この点。私は、このように危惧をしていますが、この点はいかがでしょうか。","respondent":"小林保育課長","answer":"これは、ある面から言うと、それぞれの市町村、自治体が、その状況に応じて柔軟、かつ効果的に財源を配分し、子どもの環境を整えていく、ある意味では、責任を持った対応をやっていくという地方分権の流れからすれば、評価すべき点があろうと思います。","id":"exchange-101"},{"speaker":"飯沼委員","kind":"提案","question":"大もとと言えば、国における予算の使い方で、保育予算をもっと増やしてほしいというところは、国基準の支弁費が低くて、課長、部長おっしゃっているんじゃないですか、国の計算の大もとが足りないので、自治体が大幅に負担をしていると。これははっきり違反ですよね。そういった面で、国がしっかりと責任を持っていくベースがかけがえのないことであると思うんですけれども、その辺はいかがでしょうか。","respondent":"小林保育課長","answer":"逆に指導しているから、ぱっと行ったときに、今日は子どもの予定数がきていて、保育士がもう１人足りないんじゃないかですかという一過性の話が出るわけで、そういった指摘ができるのも、指導している一つの成果であると思っています。","id":"exchange-102"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今回の請願は、国に対して意見書を上げてくださいと、私たちに求められていますので、ちょっと皆さんと議論ができたらと思います。国会において、ほぼ今日挙がっている１項目と同じ内容が採択をされている状況なんですけれども、私はぜひ、皆さんで一緒にこの請願、意見書を上げていく立場に立っていただきたいと思うんですが、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-103"},{"speaker":"阿部委員","kind":"質問・要望","question":"請願項目に沿って議論を、ということでしたので、請願の項目の1)は、前回、出てきた意見書を求める請願と、求めるものはほぼ一緒かなと思います。今、逆に、国会のほうで、こういう内容で採択されたのであれば、国全体として、そういう気があるのであれば、逆に、品川区が、一自治体としてお隣の自治体を縛るような中味の意見書を出すべきではないのではないかというのが、私の考え方です。全部意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-104"},{"speaker":"浅野委員","kind":"質問・要望","question":"私も、請願項目に沿って、ちょっと質問させていただきたいと思います。その間、例えば区として意見を、また自治体として意見を申すだけの余裕というのか、機会があるのかどうかということを、まず１点、お伺いしたいと思います。この２点について、お考えをお聞かせいただきたいと思います。","respondent":"小林保育課長","answer":"これは、当然のことながら、国も、全国一律に仕切れる内容ではないと考えていますので、こういう考え方で、こういう方向に進めていこうと思うんだけれどもどうかということで、具体的な基準の設定までは、当然、十分な議論の余地があって、そしてまた、変化があるときには。","id":"exchange-105"},{"speaker":"浅野委員","kind":"質問・要望","question":"ぜひとも、設置基準を守りなさいという限定したような国からの意見とか、また、今回でありますと、直接契約方式を必ず導入しなさいと、そういうようなことが出た場合は、必ず反対をしていただきたいと思います。これにつきましては、これからの子育て支援ということで、力を入れていかなければならないところと、私ども認識しておりますので、これについては引き続き力を入れていっていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-106"},{"speaker":"鈴木（真）委員","kind":"質問","question":"質問というより、意見というか、態度を含めての話で言わせていただきます。ただ、1)の項目につきましては、先ほど来出ていますように、９月２９日の厚生委員会の中でも、かなりの時間をかけて、相当長時間にわたって質疑をした部分です。もっと大きな面で見てほしいということを考えると、やはり2)、3)についても、今回、ちょっと賛成しにくいという状況が、自民党としての態度表明も含めた意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-107"},{"speaker":"飯沼委員","kind":"質問","question":"４月段階で、区の公式発表だと、待機児が１１５名、でも、実際に認可の保育園に入れなかった子どもで認証に行った方は、東京都の調査だと、６割は公立、私立の認可保育園を希望しているというデータが出ています。その経過の中で、今はもう１１月ですから、その後、生れた赤ちゃんとか、よそから移ってきた方とかを入れたら、ほんとうに５００名近くが入れない。こんな悲惨なことがあっていいんでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-108"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"今の皆さんのご意見をお聞きしていて、保育園の最低基準は守るというのが必要だというところでは、一致できるのかなという思いがしたんです。この保育所の最低基準というのは、戦後まもなく出されたもので、この基準に対して、区はやっぱり、この最低基準は守っていくべきだというところでは、区としても、そう考えられているんでしょうか。","respondent":"小林保育課長","answer":"そうです。","id":"exchange-109"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"ほっとしました。そういう流れだと思うんです。私たち共産党でも、第１回定例会のときには、総括質問でも取り上げたところなんですけれども、オアシスルームが常態的な業務というところで、しっかりとここにも予算をかけて、本来、やっぱり正規職員で行うべきというのが、私はこの請願の趣旨じゃないかなと思っているんです。そこら辺のところは、今、どんな現状になっているのでしょうか。","respondent":"古川児童保健事業部長、小林保育課長","answer":"今回、検討されているのは、あくまでも６月に地方分権改革推進本部が出したものと、私は判断をしておりまして、この最低基準については、今、全国津々浦々に一つの基準がありますが。したがいまして、だれがやるかということから言えば、職員主導のもとに人材派遣が対応しているところもありますし、非常勤職員にお手伝いいただいて、地域の子育ての一貫で取り組んでいるところもあり。","id":"exchange-110"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"今のことに対して、最後に言わせてください。オアシスルームなんですけれども、一時的、臨時的ということで雇用するのが派遣の趣旨ですから、やっぱり、オアシスルームはずっとそういうことが常態化した仕事ということであると思いますので、私は、ぜひ正規職員でということで予算を増やしていただきたいとお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-111"},{"speaker":"鈴木（真）委員","kind":"意見","question":"自民党としましては、先ほど、態度表明を含めて、意見というお話をさせていただきましたが、品川区の中で、もう保育に対して最低基準以上のもので実施していることを含めて、品川区議会として、この意見書を出すというのは、ちょっと方向性が違うのかなと、私は思っております。前回も、そのような意見が出ていたと思います。お願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-112"},{"speaker":"堺委員","kind":"意見","question":"今、鈴木真澄委員がおっしゃっておられましたように、請願の文章を全部、先ほど書記が読んでくださいましたけれども、はっきり申し上げると、非常に耳障りのいい、耳当たりがいいというか、これを読むと、全くそのとおりだなと、１日も早くそういう形で実現してほしいという気になるんですけれども、やっぱり今まで冷静に質疑を聞いておりますと、ちょっと待てよ、という気にもなります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-113"},{"speaker":"飯沼委員","kind":"質問・要望","question":"だからぜひ、国に対して意見書を上げていきたいと思いますし、今の子育て中の仕事をしていらっしゃる方も、在宅の子育てをしていらっしゃる方も支えていく意味で、保育園の重要性が増しているし、期待されているというところでは、予算もぜひ増やして、充実をしていただきたいということで、採択を主張いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-114"},{"speaker":"阿部委員","kind":"質問・要望","question":"国に求めるべきは、制度上の全国一律の制約ではなくて、むしろお金であろうと、保育予算であろうと思います。先ほども申しましたように、2)、3)については、より一層の努力をしていただくという考え方です。いろいろな思いはありますけれども、請願そのものについては、ちょっと採択しにくいかなと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-115"},{"speaker":"飯沼委員","kind":"意見","question":"川西絹子委員の、１点目の高齢者住宅の建設促進についての中味なんですけれども、東大井林町の都営住宅の後のところで、高齢者向けの住宅を建設するようなお話だったので、この辺の中味を、もう少し詳しくお伝えいただけたらと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-116"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/481603?Template=document&Id=3220#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":90913,"voices":289}},{"id":"h20-20081125-8","meetingId":"h20-cm11","date":"2008年11月25日","dateIso":"2008-11-25","committee":"建設委員会","time":"午前１０時０２分～午後３時１９分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を46件抜き出しています。","topics":[{"id":"topic-01","title":"議案審査","agenda":"議案審査","exchanges":[{"speaker":"菊地委員","kind":"意見","question":"今の実際に自転車が置かれている状況を見ますと、ここで言っている６５０台という台数では全然ない、１,０００台を超えるのかなという感じがしますけれども、実際の数との関係で、東急のほうが当面８００台とか９００台とかで開始するということだけど実際に間に合うのかどうか、そこについてお聞かせ願いたいと思います。","respondent":"諸石交通安全担当課長","answer":"それで、今までもずっとお話をしておりますけれども、無料の駐輪場から有料化をすると、大体ご利用される台数が７割ぐらいになるというのが今までの例でございまして、大体１,０００台としますと７掛けで７００台ということで、今回、東急のほうは。","id":"exchange-001"},{"speaker":"菊地委員","kind":"意見","question":"西小山駅の話は最近の話ですね。それからもう１つ、これは現地でもらった東急の資料で、附置義務で２５０台とか出されていますけれども、通常、一般的に商業施設のある場所での駐輪場は、２時間無料とか、そういうのがありますよね。今回の場合は、今の計画だけで見ると、そうした整備がないようですが、この辺は別枠で商業施設の附置義務として２５０台というのか、その辺をちょっとお願いします。","respondent":"諸石交通安全担当課長、浜脇街路事業担当課長","answer":"ただ、きょう、東急のほうも委員の皆様への説明の中でお話がありましたけれども、駅を利用してくださる皆様のご利用を考えてですので、当然。やるとすれば、それは東京都、品川区という、そういったものとのまた協議になりますので、私どもはこれで今、それは考えていないという状況です。","id":"exchange-002"},{"speaker":"菊地委員","kind":"質問・要望","question":"それともう１つは、実質的に武蔵小山駅を中心にして、今、まちづくりそのものが、広く言えば、５６haですか、ああいう広い範囲でのまちづくりというものを今考えておられるわけですから、やっぱりこういう商店街にしても、それから新たなマンションができて、実際に入ってくる住民の皆さんも多くなるということを想定すれば。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"井上委員","kind":"質問","question":"きょうのところで相当多いという、ただただ３００台あるんじゃないでしょうかみたいなお話だったんですけれども、実測したことが過去にあるのかということ。把握の仕方によっては７割の見込みというところで、また対応が変わってくるのではないかというふうに思いますけれども、基礎的なデータとしてそういうふうに数えたことが過去にあるのでしょうか。","respondent":"諸石交通安全担当課長","answer":"当然のことながら、撤去活動、あるいは警告活動、これを定期的にやっておりますので、そうした中で、例えば武蔵小山駅前、今日は何台ぐらいあったということで、当然１台１台数を数えるわけではありませんけれども、毎日、放置自転車の対策をやっている人間が、今回。","id":"exchange-004"},{"speaker":"井上委員","kind":"質問","question":"ちゃんとそういった把握をされているということでわかりましたけれども、ちなみに、ここの武蔵小山でいいますと、近々でしたらいつごろの実測だったのでしょうか。","respondent":"諸石交通安全担当課長","answer":"一番新しいものは、平成２０年、今年の５月に台数を数えさせていただいたものが最新のものです。","id":"exchange-005"},{"speaker":"井上委員","kind":"質問・要望","question":"ここでそういう状況で把握されているということで、有料になると７割の方ではないかということで、そのときに交通機関を使うための利用なのか、その辺の把握で随分変わってくると思うんですね。その辺の把握はどういうふうに検討がされたのかということと、この９００台の月極めと当日利用の台数を決められているのでしたら数字を教えていただきたいんです。","respondent":"諸石交通安全担当課長","answer":"それと、今度、有料化になって、定期、それから当日利用の台数の関係ですが、まだ何台規模ということで具体的にはもらっていませんけれども、これは平置きの、それから人を配置しての有料駐輪場ですので、当然。","id":"exchange-006"},{"speaker":"井上委員","kind":"確認","question":"１つ確認です。先ほど、この仮の駐輪場、Ｍ－７のところですが、今あるところの無料のものを１２月８日に閉鎖をしてというような、東急の方の説明だったんですが、仮駐輪場はいつからなのか、その辺がどういう予定になっているのか教えてください。","respondent":"諸石交通安全担当課長","answer":"事前の広報関係ですけれども、駅周辺に１２月８日から有料駐輪場が運用開始になります、場所はここですという内容のお知らせは、遅くとも１１月２８日から東急のほうで駅周辺を中心に実施をするということで話をいただいております。","id":"exchange-007"},{"speaker":"三上委員","kind":"質問・要望","question":"そうなったときに、結局、あのときに駐輪場として整備すると言って、１回話は出たんだから、近隣の皆さんは東急がそういう計画がありますよというようなことが前提として、その時点から皆さんは知っているのでしょうと、だから少し時間がたったのだから、またつくるということを、少し景気がよくなったり、３年か４年くらいたって景気がよくなってきたら、じゃあ。","respondent":"諸石交通安全担当課長、浜脇街路事業担当課長","answer":"間もなくこの協議会も開催する予定となっておりますので、この協議会を通じて地元の皆様と我々区と共同で放置駐輪に対する強力なアピール、キャンペーン等をやっていきたいというふうに考えております。それから最後の住宅の件ですが、議事録については、住民とのお話し合いといいますか、説明会の中でも住民に対して、とりあえず白紙に戻してといいますか、見直しますと言ってありますので、今。","id":"exchange-008"},{"speaker":"三上委員","kind":"意見","question":"それぞれ懸案となっていることが含まれておりますので、そういう形でしっかりとお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-009"},{"speaker":"菊地委員","kind":"提案","question":"前回の道路の廃止のことですとか、その前の都市計画審議会ですとか、いろいろ聞いてきたんですけど、今回のようにこういう地区計画が変更されるまでの流れなんですけれども、当初、白紙でというか、事業者から提案をされる前は、こうした定めをしないまま動いていったと思うんですけれども、実際にソニーからはどういう整備計画、事業計画が出されたのかというのをちょっとまず最初に確認をしたいと思います。","respondent":"青木都市開発課長","answer":"その際に概略は申し上げておりますけれども、今、担当課長のほうからご説明がありましたとおり、地区計画そのものについては平成１４年に全体の大まかな方針は既に定まっております。","id":"exchange-010"},{"speaker":"菊地委員","kind":"提案","question":"そうすると、ここでいう、２ページ目の資料１にある、この容積率６５０％だとか、高さの最高限度１４４ｍというのは、このソニー、事業者から提案された内容をそのままここにこういうふうに設定をするということなんですか。","respondent":"青木都市開発課長","answer":"そういうことと、あとは、これは都市計画の一般論なんですけれども、直近の駅の乗降者数等を考えて、そういったものから総合的に判断して、このソニー地区、Ｃ地区につきましては、現在。","id":"exchange-011"},{"speaker":"菊地委員","kind":"提案","question":"要は、ソニーから、事業者からの提案の内容でこの容積率と高さを決めているのだと。課長が前段でおっしゃっていたセンター・コア・エリアという関係なんですけれども、都市活性化拠点の形成を推進するのに必要な開発という位置づけのようなんですけれども、都市活性化拠点という言い方というのは、このソニーのビルが建ち上がることでどういう役割を果たすのかという説明を少しお聞かせ願えますか。","respondent":"青木都市開発課長","answer":"委員の今お使いいただいた言葉自体、都市活性化拠点という言葉自体は、品川区のほうの市街地整備基本方針の言葉ですけれども、おおむね東京都と類似の言葉であるということで、あわせてご説明申し上げますけれども、大崎駅周辺地区。","id":"exchange-012"},{"speaker":"菊地委員","kind":"質問","question":"要は、企業のまちという感じになるんですかね。環境省に聞くと、企業によってまた随分違いがあるみたいですけれども、企業の平米床単位でいうと、９９kgの排出量、大企業だけれども、そういうところで今わかる範囲で教えていただければと思います。","respondent":"青木都市開発課長","answer":"過去、研究所である大崎西テクノロジーセンターという昔の建物があった時代の正式な記録としてのＣＯ2の排出量等が把握できておりませんので、過去との比較というのは、今ここでは正確なご説明はできませんけれども、委員ご指摘のとおり。","id":"exchange-013"},{"speaker":"菊地委員","kind":"意見","question":"そうすると、環境確保条例みたいなものとの関係というのはどういうふうになっていくのか、お願いします。","respondent":"青木都市開発課長","answer":"ですので、それに対しては各事業者がいわゆるテナントビルであればテナントに対しての省エネを奨励するとか、いろいろな対策をする中でいろいろなＣＯ2削減に資するような具体的な取り組みをやっていくことが義務づけられるというふうに理解しております。","id":"exchange-014"},{"speaker":"井上委員","kind":"提案","question":"このＣ地区は、Ｄ地区だと高さは１２０ｍというところもあるんですけれども、こういったところで計画で１４４ｍというのは企業のほうからそういう提案でここに盛り込んでいると思うんですけれども、これは単純に企業側のこういう判断でなっているものなのか、そこら辺をちょっと説明をしていただきたいんですけれども。","respondent":"青木都市開発課長","answer":"今回、それを超える１４４ｍにしたというのは、先ほども別の委員にお答えしましたとおり、航空制限、羽田空港に対する建物の高さ制限がきいてくるのが、この地区ですと、ほぼ１４４ｍ、海面から１４４ｍになるということで。","id":"exchange-015"},{"speaker":"井上委員","kind":"質問","question":"最高限度が１４４ｍということで、基本的に企業のほうから整備計画が既に出されているということで、企業側としては１４４ｍ、今のものだと最高限度はそうですよということなんですけれども、もう出されている計画案としては１４４ｍで出されているのでしょうかということと、また、これから各地域、個々に整備をされて進められていくところが変わっていくと思うんですけれども。","respondent":"青木都市開発課長、片田建築課長","answer":"現在のところ、この事業者は１４４ｍという都市計画の制限の中、あるいは条例による制限の中で、つい先日、近隣の方々にまたご説明を申し上げた資料によりますと、軒高が１３８.５ｍ。それを基本としてどこで決めるかというと、いわゆる建築物の外壁を基準とした平均地盤面、それから相対的な高さをおさえておけば、仮に地盤面が若干変わったとしても。","id":"exchange-016"},{"speaker":"井上委員","kind":"質問","question":"このエリアの外というか、百反から上がっていったところとか、切れた部分でそういったところの逆というか、そういうところを品川区としてはどういうふうに、先ほど、これから景観計画などで拠点のデザインとかを検討していくということなので、それはそれでいいんですけれども、今ここで、ここの部分は土地の有効活用をして高層な建築物を全体でつくっていこうというふうにここは定めたものなんですけれども。","respondent":"青木都市開発課長","answer":"これも先ほど別の委員のご質問にお答えする中でご説明しました東京都全体のまちづくりの考え方として、日本橋とか皇居あたりを中心にするセンター・コアという広い範囲、おおむね山手線の内側と言われておりますけれども。","id":"exchange-017"},{"speaker":"井上委員","kind":"提案","question":"ここの部分は、ここをこういう形でつくっていこうというエリアで、今までずっと計画をされてきた中で、いろいろ地域の住民との協議というものは、本当に十分されたのかというところも、長い年月かかっているので、結果的に形になってきてからの議論になってしまうと、もうどうにもなりませんよというお話になってきているので、やっぱり地域の人たちがまちづくりをもうちょっと考えられるような。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-018"},{"speaker":"菊地委員","kind":"質問","question":"反対します。意見も述べしますけれども、都市再生緊急整備地域の中で、今回はソニーは単独ですけれども、これまでやっぱり６０haの開発の中で膨大な税金が投入されてきて、これも以前にも申し上げましたけれども、新築の隣の西口中地区では、従来いた住民の皆さんがどんどんと追い出されていく。ですから、こういう開発はもうやめていくべきだということを申し上げておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"三上委員","kind":"意見","question":"ここに関してはそういうことがあるのかないのかということについては、やはり明確にそれはきちんと考えるべきあって、一般的なことの次元で言っているのかどうかわかりませんけれども、そういう言い方というのは、私はもうやめたほうがいい、そういうことも私はもしあれだったら、理事者だってはっきりそういうことを言ってもらいたい。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-020"},{"speaker":"菊地委員","kind":"質問","question":"この表の左側にある例えば管理運営の理念、こういうもの１つ１つに点数をつけていっていますよということなんですね。１位と２位の差が３０点だと言われたんだけれども、その点数というのは明らかにできないのでしょうか。","respondent":"齋藤住宅課長","answer":"申しわけございません。配点と、各社の採点が何点とはっきり申し上げることはできないのがルールです。","id":"exchange-021"},{"speaker":"菊地委員","kind":"意見","question":"確かに住宅とはいえ、それぞれ住んでいる方がいらして、そことの管理上の問題とかいろいろあるかもしれませんが、管理者をこうやって今までの管理者から切りかえる以上は、審査の段階で点数が変わっていったのかというのは、出してもそれは別に大きな問題になるとは思えないんですけれども、もう少しその辺をお願いします。","respondent":"齋藤住宅課長","answer":"２つございまして、何点と評価したかというのは、事業者を評価することになり、今後必要な情報が得られないおそれがあります。次回にどこをどうすればいい結果が出るかということになり、プロポーザルの審査を形骸化します。そこで配点と採点は伏せてやっていきたいです。","id":"exchange-022"},{"speaker":"菊地委員","kind":"意見","question":"私はヒントになってよりよい管理ができるのであれば、そのほうがよほどいいのではないのかなというふうに思うんですね。それをヒントにして区民住宅に住んでいる皆さんがよりよい管理をしてもらえるのだったら、私はそのほうがよほどいいと思うんですけれども、どうもその辺がよくわからないですね。","respondent":"岩田まちづくり事業部長","answer":"我々審査委員はそれを全部見て、それぞれに項目を入れる。ですから、議会にお出しするというと、この程度の内容と点数をもとに出てしまいますと、第三者が見ますと、その業者の評価が誤って認識される危険性がある。いわゆる業者のブランド名を傷つけてしまう可能性があるんです。","id":"exchange-023"},{"speaker":"菊地委員","kind":"提案","question":"これもちょっと前の話になりますけれども、港区のようなエレベーター事故、ああいう場合においても、どこかにどんどん委託しているからという話ではなくて、やっぱり港区自体の管理体制が問われたわけですし、議会そのものの体制についても、もし何かあれば問われるということになるわけですから、ぜひそこは何らかの形でやっぱり明確にして、こういう提案をしていただきたいなというふうに思います。","respondent":"齋藤住宅課長","answer":"指定管理者制度の仕組みですが、これは指定する権限は首長にあります。したがって、説明責任が議決をいただく議会に対してあります。区は公平公正な手続きで、業界トップ１０に入る定評のある企業からご応募いただきました。","id":"exchange-024"},{"speaker":"石田（慎）委員","kind":"質問","question":"１点だけお伺いしたいんですが、今回は東館に関しての指定管理者の変更ですが、東急コミュニティーが西館を管理していて、一体的な管理ができるよということがメリットとして書かれているんですが、西館はいつまで指定管理者になっていて、例えば変更のときに、西館が違うところになった場合、一体感はなくなってしまうわけですよね。","respondent":"齋藤住宅課長","answer":"今度、４年後か５年後にまた指定更新となりますけれども、そのときにまた一体的に管理をやったほうがいいのかどうかを含めて判断して、あわせて議会のご意見をいただきながら、その時代の業界の状況も踏まえまして考えていきたいと思います。","id":"exchange-025"},{"speaker":"井上委員","kind":"確認","question":"私は、１つは、先ほど、個人情報の保護のところで、東急コミュニティーのところでは、２段目に再委託先に事前審査、採用時の確認書という項目があるんですが、隣の三井不動産のところも再委託先との誓約書というのがあるんですが、そこのところで、再委託というものがどういうところで発生して行われているのかということを１つ伺いたいのと、あと、収入および支出のところで、人員の配置計画では。","respondent":"齋藤住宅課長","answer":"個人情報については、個人情報をどのように守るために会社の中で対応していますかという質問をしたときにいただいた会社の考え方です。区では、本件について再委託することをお願いはしていません。経費の算定は各事業者がします。そのご提案をお願いします。","id":"exchange-026"},{"speaker":"井上委員","kind":"提案","question":"そうすると、そういう意味では、業務重点方針の３番目のところで、三井不動産住宅リースは、入居者入れ替え時のエアコン設置とか、防犯カメラ増設とか、こういうことが提案として、これが維持管理経費とか、そういうところに入っての算出だというふうに考えていいですか。要するに、提案のところが含まれた維持管理経費ということだというふうに判断していいんですか。この表を見る限り。","respondent":"齋藤住宅課長、岩田まちづくり事業部長","answer":"そのエアコンと防犯カメラ増設につきましては提案があったということの具体的なものは記憶になくてすみませんが、これらは区が設置し、防犯カメラも２２台ありますので、提案のあった経費の中には入っていません。予算額はあらかじめ３社にはオープンにしております。いわゆる予算上限は幾らと想定していますと。","id":"exchange-027"},{"speaker":"井上委員","kind":"質問","question":"この区民住宅に対して、こういう防犯カメラの増設とか、エアコンの設置とかというのは、区としてはやってもらったらありがたいという、そういうものなのでしょうか。多分違うのではないかと思うのですが、その辺の考え方だけ教えてください。","respondent":"齋藤住宅課長","answer":"東館には、今現在、２２カ所、防犯カメラがあります。エアコンもついています。区がつけているので、故障したら区が直します。入居者がかわるたびに新しいエアコンをつける、こういう話ではないと思います。","id":"exchange-028"},{"speaker":"原委員","kind":"質問","question":"品川区は新規参入が難しいのではないかというようなことをまち場でよく耳にするんですけれども、それはちょっと意見なんですが、総務委員会とか、行財政改革特別委員会が契約をやっていますので、そこに触れないような形で建設のところで質問します。簡単に答えられるところから、選定委員会のメンバーですけれども、これは答えられたらで結構なんですけれども、全員一致なのかどうかというところが１点。","respondent":"齋藤住宅課長","answer":"間違いのないように引き継ぎができ、やはり民間のノウハウ、力量ということで感心しました。引継ぎをしっかりすることが、指定管理者制度の活用の大きなポイントだと思います。防犯カメラにつきましては、区のものです。防犯カメラが壊れた場合も区の負担で修理をします。","id":"exchange-029"},{"speaker":"三上委員","kind":"質問","question":"通常だったら競争するためのそれなりの努力をするはずですよね。少なくとも何かあったのかと読み取ってもいいはずだし、ないけれども、作成した文書の中で、これはちょっと不安だなというふうに受けとめたのか、現実に何か不安なことがあったというのであれば、それは大変なことですから、やはりそれは修正していかなければならないということで、そこらあたり現実的にはどういうふうに読み取ったらいいのか。","respondent":"齋藤住宅課長","answer":"区としては、当然、社会経済状況に従って、ご提案いただき審査判断します。プロポーザル方式は、社会経済の変化に対応する優れた方式だと思います。期間の問題ですけれども、これは総務課と協議し、今回、４年でやるとか、昨年のときに１年考えるとか、検討したところです。","id":"exchange-030"},{"speaker":"三上委員","kind":"質問","question":"不安要素についてはわかりました。５年間の議決をしたということがあるならば、総務課とのそういう調整をもうちょっと先にして、今回出すときに４年間で出せばよかったんですよ。どうも対応が私は後手に回っているような気がしてならないです。だから、こういうようなことで、当然、選定理由を明確に出すという話になってきたとするならば、もうちょっと工夫してほしい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"菊地委員","kind":"質問・要望","question":"反対です。意見を申し上げします。さきほど資料が少ないという批判云々という話がありました。民間の事業ですから、ここでどういう矛盾が生じているかというのが基準になるわけですから、その中でもっともっと判断しうる材料をぜひ提供していただきたいなというふうに思います。この議案については反対します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"井上委員","kind":"質問・要望","question":"賛成ですが、一言要望もあります。公募のことは、業者を公募し、決定するのは区ということだったんですけれども、ここのところがやはりとてもいろいろな問題が、今でも裁判とかそういったところもありますので、いろいろなケースの検討を重ねて、適正にしていただきたいなということを要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"}]},{"id":"topic-02","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"菊地委員","kind":"意見","question":"損害賠償をしたということは、区の管理不足があったということで解釈していいのかどうかということ、そうすると、もし区の管理不足ということであれば、通常、どういう管理をしているのか。もちろんこういう場合、例えば身近なおうちの方が区に報告してくれるとそれで直しに行かれるのかもしれないですけれども、通常の管理はどういうふうにされているのかお聞かせ願えればと思います。","respondent":"藤田道路公園課長","answer":"そういう中で、私どもも気がつけば１日でも早く直したいということで行っておりますので、今後とも区と地域の方々の連携の中で日々道路管理ができればいいなというふうに考えているところです。","id":"exchange-034"},{"speaker":"井上委員","kind":"質問・要望","question":"ちょっと関連してなんですが、道路のこういう構造のところでお伺いしたいんですが、以前ちょっとお話ししたことがあるんですが、雨天時、大雨のときに道路に下水として流れるんですけれども、そのふたみたいになっているところの形状が大きく水が落ちる形状と、ただ下水というマークですか、ああいうふたになっているところがあって。","respondent":"藤田道路公園課長","answer":"その細長い穴が３つあいているものから細い編み目のものに変える、これは雨のますから雨のますのふたに変えるだけですから、これは簡単にできるんですけれども、先ほどの下水のます、これについてはふたを変えることは、まず下水道局の財産であるということと。","id":"exchange-035"},{"speaker":"三上委員","kind":"質問","question":"文書的にどうなのかなとちょっと思うんですけれども、事故の概要のところで、「左中足骨」と書いてあるんです。左中足骨というのは、どこを指すんですか。","respondent":"藤田道路公園課長","answer":"実際のけがをされた場所というのは、左足の中指のつけ根の部分です。それを骨折されたんですけれども、ちょっと私もここまで確認していないんですけれども、そこの骨の呼び方というのがこういう呼び方なのかなと思います。","id":"exchange-036"},{"speaker":"三上委員","kind":"質問","question":"専門家の使う言葉と一般的なものはちょっと違うのかなと、診断書がそうなっているんでしょうね。それはわかりました。それと、治療費と慰謝料というので、トータルして７万３,０００円といいますけれども、こういった場合の慰謝料額というのはどんな感じでかかってくるんですか。","respondent":"岩田まちづくり事業部長","answer":"そのうち、今度は瑕疵割合、責任割合です。今回の場合は１対９で、区が１割、本人の過失が９割と認定していますので、その全体にかかった１０分の１がこの７万３,０００円、その他の分はこの方が自己負担をしているです。","id":"exchange-037"},{"speaker":"原委員","kind":"意見","question":"今の説明は非常によくわかりました。ただ、一般的なケース、これはケース・バイ・ケースのご判断なんでしょうけれども、こういうことになってくると、まだ出ていないということですよね。そこが心配です。","respondent":"齋藤住宅課長","answer":"出ない場合には、１２月８日に強制執行します。ご本人からは、今月１１月２０日から３０日に出るということで、今日現在出ておりませんが、１２月８日までには出るというようなことを発言をしているようです。弁護士には電話してきたようです。","id":"exchange-038"},{"speaker":"原委員","kind":"質問・要望","question":"その辺についてお考えを伺いたい。","respondent":"齋藤住宅課長","answer":"本人が帰ってきても入れない。それは間違いないです。和解金については、結果として私の説明不足だったんですけれども、保証人の方から、１６０万円は払えない。","id":"exchange-039"},{"speaker":"原委員","kind":"質問","question":"そのときに社会的弱者という表現で、けがとかをされている場合ですとか、すごく高齢だったり、いろいろなケース、それが法的に勝つのかというと、なかなか難しい今までのケースがあるものですから、できることだったら順番的には逆にしていただいたほうがよかったのではないかと。当然、ルールはわかりますので、そういうことでお願い事項ということで、次のそういった件があったらお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"菊地委員","kind":"質問","question":"一つだけお聞きしたいんですけれども、この都市計画の変更が決定して、決定後に、例えば実際の建物の配置とかというのを変更しようとした場合に、また変更手続きというのは地区計画の場合は生じてくるのでしょうか。地区計画の変更として届出をしていかなくてはならないということですか。","respondent":"吉川住環境整備担当課長","answer":"今回、地区計画を定める内容につきましては、今申し上げました内容ですが、それにかかわる部分の変更が仮に将来生じたとすれば、それについては地区計画変更の必要がありますが、今、例で委員が言われました駐輪場については、今回、地区計画の中では。","id":"exchange-041"},{"speaker":"三上委員","kind":"意見","question":"武蔵小山駅ビルの６ページの図を見てもそうですし、地区計画の計画図を見てみましても、康済会病院とぎりぎりになりますよね。そういうふうにして考えていったときに、本当に病院のほうから、もうこんな工事はやめてくれという声１つ聞かないで今日まで来ているんですけれども、ここらあたりが大変心配しているわけですが、そこらあたり、現状はどういうふうにつかまれていらっしゃるのかお聞かせください。","respondent":"吉川住環境整備担当課長","answer":"ただ、これは将来的な話でございまして、今回東急が駅ビルをつくるわけですが、将来、病院を建てかえたときに両者の間で４ｍの道路を整備するという計画方針は立てられております。それについては私どものほうも病院と東急のほうには説明をしています。","id":"exchange-042"},{"speaker":"三上委員","kind":"確認","question":"そうしますと、将来的には４ｍ道路にするというお話であるならば、今この駅ビルも既に康済会病院との中間からは、２ｍ以上はきちっと離れて建物が建てられるということで、それは確認されているわけですね。そうなると、この２ｍの道路というのは、暫定的にも駅ビルができ上がった段階では、一般の人たちにも暫定的にここを通れるように開放するという考え方で今いるのかどうかということはどうなんですか。","respondent":"吉川住環境整備担当課長","answer":"ただし、駅の施設からはみ出ている柱みたいなものがございまして、それが一部２ｍの中に食い込む形となっておりますので、そこを事実上の歩道として整備するのは非常に困難なところでございまして、歩道にするのは将来的に病院の開発と合わせてということにいたしまして。","id":"exchange-043"},{"speaker":"三上委員","kind":"質問","question":"そうすると、駅施設の高さが邪魔してということは、駅前通り商店街のほうでも、要するに、道路の部分が七、八十cm高くならざるを得ないという、そういう現状と同じということでよろしいですか。","respondent":"吉川住環境整備担当課長","answer":"委員のおっしゃるとおりです。","id":"exchange-044"},{"speaker":"三上委員","kind":"質問","question":"そうすると、この６ページの計画概要のところで、駅前広場のところにアーケードを延長するような形で駅まで計画だとつながっていますよね。これで行くと。この形でということでいいんですか。","respondent":"浜脇街路事業担当課長","answer":"おおむねこういうことでやる予定であります。","id":"exchange-045"},{"speaker":"三上委員","kind":"意見","question":"何か広場と言うより、うっとうしいようなところになっているような感じ、暗いような感じでしかないよね。何でも歩行者のための雨よけを囲いですればいいということでいいのかどうかということも考えるとどうなのかと。そこらあたり、景観を担当しているところとしてはどうなんだろう。","respondent":"岩田まちづくり事業部長","answer":"果たしてこれがいいのかどうかというのは非常に難しいところで、何もなくて青空がポーンと駅をおりたときに満天の空が見えるというのも、それはそれで一方で景観上すばらしい景観でしょうし、一方で、ユニバーサルデザインというものでは。","id":"exchange-046"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/803869?Template=document&Id=3928#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":43509,"voices":145}},{"id":"h20-20081125-9","meetingId":"h20-cm11","date":"2008年11月25日","dateIso":"2008-11-25","committee":"文教委員会","time":"午前１０時０３分～午後３時２４分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を82件抜き出しています。","topics":[{"id":"topic-01","title":"平成２０年請願第３１－２号 一人ひとりの子どもが大切にされる品川区を求める請願（請願項目4)）","agenda":"平成２０年請願第３１－２号 一人ひとりの子どもが大切にされる品川区を求める請願（請願項目4)）","exchanges":[{"speaker":"山元委員","kind":"質問・要望","question":"課長もおっしゃっていたんですが、この４番目のところを読んだときに、やはり空間を確保しというのがちょっと引っかかったんですが、実際現状どういうふうにすまいるがなっているのか教えていただきたいなと思います。","respondent":"田村庶務課長","answer":"空間ということで、ご存じのとおり品川区のすまいるスクールの特徴は、すべての３８校全校、学校の敷地内にすまいるがあります。","id":"exchange-001"},{"speaker":"山元委員","kind":"質問","question":"そうすると、ぎゅうぎゅう詰めにということではなく、ある程度の子どもに対しての広さは十分とってあるということでよろしいですか。","respondent":"田村庶務課長","answer":"各学校の状況は異なりますけれども、文部科学省の指針だと一人当たり１.６９m2ということで、これはあくまで指針で、そういうふうにしなさいというのではなく、それが望ましいという記載の仕方なので、強制するものではありませんけれども。","id":"exchange-002"},{"speaker":"石田（秀）委員","kind":"質問","question":"今の話はこの請願が出てきた、もちろん私が知っている限りでも１０年ぐらいの間はいろいろな形があって、今のすまいるスクールという形も学童を存続してほしいという請願も時々出てきた中で、今こういう形になっているわけですけれども、ぜひ今の疑問点、市川委員が署名議員になっているわけですから、そこら辺のところもおわかりになって署名していただいたのでしょうから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"市川委員","kind":"意見","question":"特に人数の多い学校ですね。子どもがゆっくりくつろげるというような空間ではないのではないかということで、このくつろげる空間の確保ということで、私はこういうことを確保してほしいなというふうに思っています。すべての学校ということではなく、特に人数の多い学校に関してです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-004"},{"speaker":"石田（秀）委員","kind":"意見","question":"今の小中一貫校とか人数の多い学校、そこが学童クラブのときと比べて非常にくつろげない空間になっているという言い方をされているということなんだけれども、その事実関係は行政側から説明してもらったほうがいいのではないか。","respondent":"田村庶務課長","answer":"伊藤学園も大体２.２から３ということで、学童のときの比較という形ではありませんけれども、文部科学省の指針で出ている数値は実態的に通われているお子さんに対応しているということです。","id":"exchange-005"},{"speaker":"石田（秀）委員","kind":"質問","question":"今、お話を伺うと、そういう空間というところもある程度私はできていると考えていますし、今のお話の中でも学童保育と比較をしてという話なんだけれども、私は比較対照する話ではなくて、これは新たにすまいるスクールというものができたわけですから、その中で子どもたちのしっかり放課後対策もある程度できているんだろうと考えていますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"川西委員","kind":"質問","question":"私も質問ではなく意見なんですけれども、いいですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"川西委員","kind":"意見","question":"私は年代的に古い人間なんですけれども、学童保育を自分の子どものときに、今で言えばＮＰＯみたいな形で、非常勤の講師の方、指導員の方をお願いしてつくってきた１人なんですけれども、それからずっと発展しまして、学童保育というのがあちこちに区営でできました。そういうことでずっと来まして、厚生委員会に所属していましたときに、当時の学童保育を何回も視察させていただいた。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-008"},{"speaker":"中塚委員","kind":"質問","question":"先ほど平米数の話が出たんですけれども、ちょっと分母が何で分子が何なのか教えていただけたらと思っています。それと、今の議論の中で、今の経過の中で学童からすまいるという話がありましたけれども、現状のすまいるで学童保育クラブがどんなふうに保証をされているのか。その視点でちょっとご説明いただけますか。","respondent":"田村庶務課長","answer":"それと、学童保育の保証という意味では、基本的にはすまいるスクール、学童部門も含んだ形の対応をしていますので、細かい話ですが、やはり違いということになると、おやつを出さないとか、特に審査基準がありませんから。","id":"exchange-009"},{"speaker":"中塚委員","kind":"質問","question":"平米数のほうで、先ほどの日野が２.２４で伊藤が２.２から３、分母と分子がそれぞれどういう計算で出たのか。文部科学省の説明はわかりましたけれども、さっきの数字の根拠を教えてください。それと、学童の保証のところですけれども、今、教育委員会のほうにすまいるが来ているという関係で伺うと、一体学童保育というのをどのようにとらえているのか。","respondent":"田村庶務課長","answer":"あるいはお勤めになっていないという方もすまいるスクールで大きくくくって対応していますので、その意味からすれば、学童の部分を吸収合併といいますか、それも含めた形で対応しているというふうに考えています。","id":"exchange-010"},{"speaker":"中塚委員","kind":"質問","question":"数字のほうですけれども、占有スペースの話ですけれども、それには校庭とか体育館も入るんですか。それともすまいるとしての専用だけなんですか。それを教えてください。先ほどからのご説明、なかなか学童とは一体どういう事業なのか。どういう事業だと思っているのか、ちょっと詳しくご説明いただけますか。","respondent":"田村庶務課長","answer":"あわせて、厚生労働省の放課後児童健全育成事業という形で、あわせて一体的に実施するものです。","id":"exchange-011"},{"speaker":"中塚委員","kind":"質問","question":"私は改めてよく点検すべきだと思います。もう一つ、体制の問題なんですけれども、確かに専任指導員が１人いらっしゃいますけれども、特別子どもと接する機会が多いのは、今、Ａ勤、Ｂ勤というんでしょうか、委託されているところとそうでないところと非常に複雑になっておりますけれども、基本的に１年間の雇用で繰り返されているのか切りかわっているのか。ちょっと状況を教えていただけますか。","respondent":"市川教育次長、田村庶務課長","answer":"この学習ということについては、就労家庭の保護者も等しくすまいるスクールに望んでいるところはアンケートからも明らかでありますので、そういうことを考えていったときに。それで全体の区のほうの体制が５人から６人ぐらい、もちろん規模によって、学校によって違いますけれども、そういうような体制で対応しています。","id":"exchange-012"},{"speaker":"中塚委員","kind":"質問","question":"そのことを心配しているんです。実際によくお母さんから伺うと、せっかく少し仲よくなれたり、親も職員も少し知り合えたのに、年度が変わると人が変わってしまう。継続した子どもの成長を支えるという点であまりにも足りないのではないかなと思うんですけれども、その１点はどうか。子どもの成長を見届けられる、そういう仕事としてとらえる点もあると思うんですけれども、待遇面についてはいかがですか。","respondent":"市川教育次長","answer":"１点目のご指摘ですけれども、私たちもすまいるスクールでの子どもの指導にあたっては、委員がご指摘なさったような、子どもに接している指導スタッフの継続性、これは必要だと思っていますし、そういうことが望ましいと思っています。","id":"exchange-013"},{"speaker":"中塚委員","kind":"意見","question":"学童保育、すまいるスクール、専門性が非常に問われる。単に子どもと遊ぶと言っても、子どもと過ごすということでも非常に専門性が問われる。そのように大事なものだと思います。今日は直接的には触れませんでしたけれども、障害を持っているお子さんも通われる。今の状況では、不安も感じるし、改善していくべき点、小学校全部を総点検する必要があるなというふうに思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-014"},{"speaker":"西本委員","kind":"質問","question":"今、すまいるスクールを利用している子どもたち、働いている親、保育が必要だというお子さんの中で、６時までというのはかなりいらっしゃるんでしょうか。大体基本は５時ですね。６時まで残っているお子さんというのは全体的な割合でどのぐらいいらっしゃるんでしょうか。","respondent":"田村庶務課長","answer":"それぞれの常勤の職員の判断ですけれども、私の聞いている限りでは６時まで居残りというのは少数、本当の少数で、事前に連絡を取ってどうしても６時まで預かってくださいということで、数的には私のほうで承知しているのは少ない数字です。なくはないですけれども。","id":"exchange-015"},{"speaker":"西本委員","kind":"質問","question":"やはり問題も多々あったわけですよね。ですから、子どもたちが成長してくると、ほかのお友達と遊びたいという要求もいろいろありながら、わりと規制がかかっていたという現実もあったんですね。先ほど６時までの子があまりいないということを考えると、非常にすまいるスクールを利用する子どもたち、親たちの考え方が変わってきているんじゃないかなと思うんですが、この辺はどのようにお考えでしょうか。","respondent":"田村庶務課長","answer":"ですから、そういう意味では、遊ぶ以外の勉強だとか、すごく大きな取り決めをしているという形ですから、すべてについて今１００％ですとは言いませんけれども、やはり課題はあれば、その都度要望等もあれば、対応できるものについては具体的に対応して。","id":"exchange-016"},{"speaker":"西本委員","kind":"質問・要望","question":"これは意見もありますし、ちょっとお答えいただきたいところなんですが、学童保育と違うところは、やはり集団の考え方だと思います。そういう集団というのをどうとらえているのかな。その辺が、すまいるスクール自体の学童保育の時代を知らない親たちになってきていますので、新たな放課後生活というのを親たち、子どもたちが要求しているのではないかなというところはいかがでしょうか。","respondent":"田村庶務課長、市川教育次長","answer":"もともとの申し込み資格のときに、先ほどもちらっとお話ししましたけれども、私立に通っているお子さんもオーケーしていますので、ですから就労している方の多様化にやはり対応している部分も、学童保育に比べてあるのかなと。子どもの集団のとらえ方の問題は、２点目のご質問の保護者の説明会はどうなっているんだということと結構関連していまして、すまいるはすまいる独自の保護者説明会もやるんですけれども、あまり参加される親御さんはいらっしゃらない。","id":"exchange-017"},{"speaker":"西本委員","kind":"質問・要望","question":"わかりました。先ほどアンケートの結果を教えていただいたんですが、子どもたちの満足度は８０％ですかと、親たちが９３％ということで非常に満足度が高い。安心のあらわれなのかなというふうに思います。すまいるスクールでも本当にこまめにいろいろやっていただいているようなんですが、どこも非常に参加率が高い、好評だということがありますので、このまま頑張っていただきたいというふうに思っています。","respondent":"田村庶務課長","answer":"というのは、学校を通じて地域のイベント等に学校とセットで参加するというやり方もありますし、あるいは児童センターと１３ブロックであるので、そこと連携してというやり方、いろいろ地域によって多分若干動き方が異なるかもしれないですけれども。","id":"exchange-018"},{"speaker":"市川委員","kind":"質問・要望","question":"それをまた教育委員会がどうやって工夫していくのかということを伺いたいということと。それから、課題や要望についてはそれぞれ聞いていきたいというふうなご答弁があったかと思うんですけれども、保護者のほうから直接教育委員会、それから専従職員のほうへ課題や要望というところが実際にあれば、どういう点でそういう要望が上がっているのか、お聞かせいただきたいと思います。","respondent":"田村庶務課長","answer":"は個別に、例えば事故の対応、あるいは具合が悪くなったり、預けている保護者とのトラブル等については、随時すまいる担当というのが本課にいますので、常勤の職員あるいは常勤が出張中のときには委託のスタッフから直接、本課のほうに上がってきて。","id":"exchange-019"},{"speaker":"市川委員","kind":"質問","question":"日々のトラブルに対しては、連絡が入ってくれば現場のほうに対応を伝えるということだったんですけれども、こういったときに、教育委員会としては対応を伝えるだけではなく、実際どういう状況になったのかという、現場に行って調べるとか、その辺の話を聞くということはされているわけですか。","respondent":"田村庶務課長","answer":"いろいろなケースによって違いますが、例えば事故については緊急性が問われるので、もともと事故の対応マニュアルだとか災害の対応マニュアルというのは各すまいるにあります。","id":"exchange-020"},{"speaker":"石田（秀）委員","kind":"提案","question":"結論を出していただきたいと思います。最初にお話をしたように、我が会派、私もそうでありましたけれども、すまいるスクールを提案をして、全児童のすこやかな育ちを全児童という意味でとらえて、学童からすまいるスクールに移行すべきだという提案をしてきた経緯もあります。それで、今すまいるスクールがスタートして全校で行われるようになってきました。我々も学童のときも見てきました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-021"},{"speaker":"山元委員","kind":"質問・要望","question":"先ほど私も空間のことに対して質問させていただいて、庶務課長のお話を聞いて、空間に対しても対応しているということなので、今日、ぜひ結論を出していただきたいと思います。今、結論を、採択か不採択か出さなければいけないんでしょうか。不採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"中塚委員","kind":"意見","question":"請願につきましては、子どもたちが毎日安心して通えるように、安心して過ごせるようくつろげる空間を確保、保護者の願いは当然だと思いますので、採択としたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-023"},{"speaker":"川西委員","kind":"質問","question":"結論を出すほうでいいです。保育園、幼稚園が終わって、学校へ入学するわけですから、やはり１つは自立ということも育てなきゃならない。ですから、どうしたものかなとこれも１つの課題として、すまいると並行して子どもたちの学校が終わって、すまいるが終わっての過ごし方についても随分悩んだり、検討している関係からしまして、それなりの親としてのお気持ちはわかるんですけれども、結論としては不採択。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"西本委員","kind":"提案","question":"今日結論を出します。その指導員の要望を聞くとあまりないんですよね。ですから、気持ちはわかりますが、もう少し保育問題協議会ということで長年活動されていますので、実態をもっと把握をした形で、もっと将来的なところを見すえていろいろと考えてご提案を私たち議会のほう、区のほうに要求していただきたいなというふうに思います。残念ながら今回は不採択と。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-025"},{"speaker":"市川委員","kind":"質問・要望","question":"このすまいるスクールを始めたときに、学童機能を備えるということと、それから、発展的な吸収だということでご説明をされたということですので、これはすまいるスクールが軌道に乗るまでは品川区は学校選択制をとっていますので、人数の差もそれぞれの学校によっても変わってきているということで、すまいるスクールの中でも変わってきていると思いますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"}]},{"id":"topic-02","title":"の専決処分の報告","agenda":"の専決処分の報告","exchanges":[{"speaker":"西本委員","kind":"意見","question":"事故はいろいろあると思うんですが、こういう事故を起こした場合に、当人の処分というのはどういう処分をされるのかなと思って、そういうことがあるのかどうか。","respondent":"堀越生涯学習課長","answer":"個別のケースに応じて懲戒処分的なことになると思います。今回の場合、事故の状況等を考えまして、人事のほうとも相談をいたしました結果、私から口頭で厳重注意という形で処理をしております。","id":"exchange-027"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"この書類で基準を教えていただきたいんだけれども、これは普通に職務中、例えば事故を起こしたと。今回は名前は出ないじゃない。それを教えていただきたいのと、相手方は住所と名前まで出ているんだよね。相手方の住所と名前まで、ぶつけられたほうなわけだから、別に保険のあれでいいんだろうけど、例えば車種を書くとか、そういうことぐらいで、どういう基準があって書くのかというのを教えてくれるかな。","respondent":"堀越生涯学習課長、市川教育次長","answer":"今後、今ご意見をいただいているように、ちょっと議会事務局、総務とも相談しまして、対応できるものであればそのような形にしてまいりたいと考えています。一定の範囲内のものについては専決処分ということで対応させていただいているんですが、その一定の範囲内のものについて、どこまでこういう社会状況の中で相手の名前、住所を示していくか。","id":"exchange-028"}]},{"id":"topic-03","title":"の小中学校の耐震診断","agenda":"の小中学校の耐震診断","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"ちょっと幾つか伺いたいと思うんですけれども、まず、清水台小学校と荏原第六中のところでは、耐震補強をすると教育環境上悪くなってしまうので改築というお話でしたけれども、もう少しその辺のところを詳しく教えていただきたいというのが１つです。それと、御殿山小学校なんですけれども、再開発の関係なんでしょうか、ここだけ改築予定がいつかというのが載っていないわけです。","respondent":"田村庶務課長","answer":"ただ、Ｉｓ値をＡランクにしてありますけれども、特にもう基準法の数値はクリアしていますので、０.６以上、ですから、その辺については対応できているので、ただ、改築という意味で年度がここだけはちょっと今調整中なので入れられないです。","id":"exchange-029"},{"speaker":"中塚委員","kind":"質問・要望","question":"まとめてもう１点、本来の計画だと今年度中だったけれども、それがちょっと延びたといういろいろな理由の中に、工事期間がどうしても品川だけではなくてほかの区も含めて集中してしまうので、職人さんがなかなか集まらないという話も以前聞いたことがあるんですけれども、この立てた計画をこのとおり進めるためにも、そういう職人さんの確保というか、そういったところはどんな工夫を今考えがあるのか。","respondent":"田村庶務課長、市川教育次長","answer":"それで、一時的には校長先生とご相談して、対応についてはこういう計画ですという話をするだけなので、例えばそれが先ほど委員からも質問ありましたけれども、前倒しするだとか、今すぐやれという話に仮になっても。ちょっと御殿山の件にも関連して１つだけ、私のほうから補足しますけれども、御殿山以外の学校でも、平成２１年度、来年度以降の改築ということで具体的に記載をさせていただいてありますけれども、本来これ。","id":"exchange-030"},{"speaker":"中塚委員","kind":"質問","question":"この耐震補強工事を来年やりますよ、１年じゃなくて２年間にまたがりますよという保護者への説明のところなんですけれども、学校長とは調節していきたいという話ですけれども、多分校庭で野球の練習、部活動を含めてなかなかどうしても制約はあるわけで、この計画を学校長を通じて教育委員会のほうからも保護者にこういうふうに進めていきますというふうには説明するものではないのかなと思ったんですが。","respondent":"田村庶務課長","answer":"やはり規模が大きければ、教育委員会も学校と合同で説明会をするという話になるのかもしれないですが、その辺はちょっと内容もバランスがあるので、一概に全部説明会という取り扱いではなく、柔軟に対応していきたいと考えています。","id":"exchange-031"},{"speaker":"石田（秀）委員","kind":"質問","question":"何点かお伺いします。それで、英断をするんだけれども、ということは、かじを切ったわけですから、二重投資はやむを得ないという可能性もあるわけで、この二重投資をしてでもしっかり耐震補強工事はしていくよという強い意思で、かじをしっかり切られたと思うんだけれども、そこら辺の考え方を再度お聞きします。","respondent":"田村庶務課長","answer":"先ほど私のほうでご説明したように、もう今の時点で計画途上に上がっている学校については、もちろん耐震の診断結果も踏まえて何とかやっていこうという意味からすると、ある程度計画も進みつつ、石田秀男委員がおっしゃっているように。","id":"exchange-032"},{"speaker":"石田（秀）委員","kind":"提案","question":"その中で幾つかご質問させていただきたいと思います。荏原第六中というのは上に入るのではないのかなとちょっと思っていたんだけれども、それを教えていただきたいのが１つ。児童の生活環境といったら教育環境を整えてあげるのに、わざわざ耐震補強したから、その運動場はもう固定よというのでは、わざわざプロポーザル提案する必要の中で、１つのそういうものが残ってしまうわけだよね。","respondent":"市川教育次長、田村庶務課長","answer":"それと、日程の関係ですけれども、今後のことを、この時点であまり身勝手なことを言うわけにはいきませんけれども、考え方、こういう調整枠を持っているということでお聞きいただければと思うんですが、通常２年かかる基本設計。１点目の記載の仕方ですが、委員おっしゃるとおり、２枚目は公表しますが、新しく直してあるんですが、１枚目のほうはあくまで平成２１年度の耐震補強工事の一覧表にしたんですが。","id":"exchange-033"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"強い決意を伺ったので、それはそのとおりやっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"西本委員","kind":"質問","question":"１２月１１日に公表するという形ですけれども、この表が出るというふうにおっしゃっていましたが、多分わからないだろう。判定なんですね。Ｂ１、Ｂ２というのが、だから何と思うのではないかなと思うのですけれども、ですから、Ｂ１は非常に危ないよとか、この書き方とか説明とか、これはどういう程度というのが多分恐らく多くの中では分からないという気もするんですが、いかがですか。","respondent":"田村庶務課長","answer":"ただ、ここでも生のＩｓ値は意識的に出していませんし、今までも繰り返し答弁しているように、やはり一部分だったりすると、図面を見せながらここがこうなんですと説明しないと、例えば０.３未満は文部科学省の基準だと建物等の倒壊の危険性が高いという表示なんですよ。","id":"exchange-035"},{"speaker":"西本委員","kind":"質問","question":"それであれば、判定のところを書く必要があるんですか。だから、ここは書かなきゃいけない、これを見てもよくわからないから、じゃあ、お問い合わせくださいというのはあまりにも不親切のような気がするし、やはりよけいに不安感をあおってしまうので、だったら、判定は載せなくていいんじゃないですかと私は思うんですが。","respondent":"田村庶務課長、市川教育次長","answer":"しかし、区長の考え方としても、やはり耐震の診断結果とセットで計画もできたので、お知らせしたいということで考えていますので、その辺の表現の工夫があるんですけれども、やはり診断結果をくくりにしても載せないというわけには。確かに悩ましいところではあるんです。ただ、これまでは私どもの品川区の耐震診断の結果については、結果としては補強工事の必要がある、補強工事の必要なしと、これで説明をしてまいりました。","id":"exchange-036"},{"speaker":"山元委員","kind":"質問","question":"お願いなんですけれども、今、計画上さまざま書いておられました。我が会派としましても一般質問させていただいたりとか、いろいろ申し入れさせていただいたんですけれども、計画どおりというか、遅れないようにぜひ安全性のためにもお願いをしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"市川委員","kind":"質問","question":"ちょっとお聞きしたいんですけれども、工事のことはあまりよくわからないので、補強工事と一口に言いますけれども、何かパターンがあるんですか。何パターンかあるんですか。","respondent":"田村庶務課長","answer":"ですから、学校によっては、ばってんに外のところからやっているのもありますし、中を補強したり、あるいは窓の部分が弱いとやはりそこを補強するには窓を取っちゃうとか、窓の上にもう１回かぶせてしまうとか、そういうような工事で。","id":"exchange-038"},{"speaker":"市川委員","kind":"意見","question":"先ほど清水台小学校は補強工事を行うとほとんど窓が隠れてしまって、学校の環境としてはよくないということで、一部改築というご説明だったんですけれども、同じ判定がＢ２のほうが結果としては低いということの中で、このＢ２に対しては、そういう学校環境が非常に劣悪になるような心配というのはない補強工事が行われるのか。その辺がちょっとわからないんです。","respondent":"田村庶務課長","answer":"ですから、荏原第六中の場合にはＢ２ということで、やはり全体補強工事ができなくはないけれども、教育環境が劣悪で改築せざるを得ないだろうということで、清水台についてはＢ１ですが、やはり校舎によって建築年度も違うので。","id":"exchange-039"},{"speaker":"市川委員","kind":"質問","question":"そうすると、ここに判定基準のＢ２の第四日野小学校と鈴ヶ森小学校については、学校の環境としてはそれほど問題のない耐震工事で済むという計画でよろしいんでしょうか。","respondent":"田村庶務課長","answer":"清水台はという話ですが、清水台は何棟かあって、全体はＢ１ですがどうしても老朽度が高いところについては改築して、それ以外の棟については耐震補強工事を実施するということで、そのように理解していただければと思います。","id":"exchange-040"}]},{"id":"topic-04","title":"文教委員会を再開いたします。(3)の地方教育行政の組織及び運営に関する法律の改正","agenda":"文教委員会を再開いたします。(3)の地方教育行政の組織及び運営に関する法律の改正","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"具体的に伺うんですけれども、品川区の教育行政の中で何が問題点としてあって、これによってどんなふうに変わるのか、ちょっと品川区に落としてご説明いただけますか。","respondent":"市川教育次長","answer":"したがいまして、少し不遜な言い方かもしれないですけれども、品川区の教育委員会はプラン２１への取り組み、極めて他の自治体に比べて教育委員会制度のもとで教育委員ご自身のご意見、考え方が教育委員会の事務事業にきちんと反映されてきていると思いますので。","id":"exchange-041"},{"speaker":"川西委員","kind":"質問・要望","question":"少しずれるかもしれませんが、伺っておきたいんですが、ここに教育委員の数の弾力化というのが(3)であるんです。ずれるかもしれませんが、聞いていただきたいんですが、世間的な言葉で言う学級崩壊、保護者からの意見を消化し切れなくて、教員の方が病欠に入ったり、神経症で長期間お休みというようなことも昔よりありますよね。","respondent":"田村庶務課長","answer":"今回の国のほうの改正は、先ほどちょっとお話ししましたように、教育委員の中の保護者の選任の中で、特に教育委員会が地域の実情に応じて多様な地域住民の意向を教育行政に反映することができるということで、広い意味では川西委員の内容も入ると思いますが。","id":"exchange-042"},{"speaker":"川西委員","kind":"質問","question":"わかりましたが、そうすると、品川区としては教育委員会全体としては、そのような現況が入ってくる必要性は感じたことがおありでしょうか。","respondent":"若月教育長","answer":"まさに、これは１教員、今度は教員だけではなく親御さんの意識もまた変わっておりまして、そういった場合にはときには学務課長が出ていったり、庶務課長が出ていったりという事務局総出で、そういった具体的な事例に対しては対応しているというのが現実的な対応の仕方であるです。","id":"exchange-043"},{"speaker":"川西委員","kind":"質問","question":"その保護者の関係でいきますと、今、教育委員でやっていらっしゃる細川さんが、時々ものを書いておられますよね。ああいう方は保護者を対象に講師として呼んで講習会とか講演会はできるんですか。教育委員の立場でいると、できるかできないか。","respondent":"市川教育次長","answer":"恐らく今のご質問の趣旨は、公立の小中学校あるいは私立の幼稚園、保育園等も含めて保護者向けに何か啓発的な講座類を企画するということが前提でのお尋ねだと思いますけれども、これはもう品川区教育委員会委員ということで招聘していただければ、これは教育委員会のほう。","id":"exchange-044"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"もし抜粋をしたなら、なぜ抜粋をしたのか。それと、最後の５番なんだけど、これは何度読んでも意味がよくわからないんだけれども、私立学校に関する事務について、教育委員会に学校教育に関する専門事項について助言、援助とこうなるんだよね、求めることができる旨のことをしろということなんだけれども、具体的には私立学校に関する事務というのはどういうことを意味しているのか。","respondent":"田村庶務課長、市川教育次長","answer":"それを求めるに際しては、都道府県知事は私立学校と協議するものとして、教育委員会は都道府県知事に対して助言、援助を行う際、私立学校の自主性を尊重するなどの適切な配慮を行うというのが１つの要素であります。つまり、地方に頑張ってもらうことによって、全体の構図がすっきりする。それが今回の地教行法の改正の趣旨だというふうに説明を受けております。","id":"exchange-045"},{"speaker":"石田（秀）委員","kind":"質問","question":"どうしてこんなことを聞くかというと、これはもちろん知事からスタートして、都教委でもいいんですね。東京都もやっている部分ですよね。そうなってくると、今みたいに必要と認める助言とか援助とかいろいろ読んだら、学校教育に関する専門的なことというと、基本的に品川区の中の私立学校を見ても、中高一貫しているのが非常に多いじゃないですか。品川は小中一貫を強く打ち出している、義務教育の中で。","respondent":"若月教育長","answer":"しかし、逆に今度考えてみると、うちの小学校と例えば私立の中、高の連携といったようなものも、また同時に可能性としては考えられてくるということで、さまざまなこれからの方式というものがここから考えられるということでありまして、必ずしも今。","id":"exchange-046"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"今、教育長から非常にいいお話を聞いたと思う部分は、小中一貫教育をされていて、小学校で中高という私立との連携も、逆に言えばこれでできるんだということが考えられる。これをどこかに持っておいていただきたいなと思っています。そういう意味合いでやれればいいかなと思っています。これはお願いです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"},{"speaker":"中塚委員","kind":"質問","question":"文化・スポーツの事務を首長が担当できるようにするというここの部分をお伺いしたいと思うんですけれども、ここは生涯学習と呼ばれる部分、図書館も入るのかわからないですけど、今まで教育委員会においていた理由と、それとあわせて首長ができるようになったということの理由、何がどんなふうに変わるのか教えていただけますか。","respondent":"堀越生涯学習課長","answer":"地方公共団体においても、条例で定めるところによりまして、スポーツと文化について首長のほうで執行することができるようになったということでございまして、これにつきましては繰り返しになりますけれども、法改正の趣旨としては、スポーツ、文化の行政に関して地域の実情。","id":"exchange-048"},{"speaker":"中塚委員","kind":"意見","question":"同じ聞き方かもしれないけど、要は今まで教育委員会に生涯学習を置いてきたその理由ですね。それと、首長に移す理由で、一体化、総合化、ニーズという話がありましたけど、その辺をもう１回説明していただけますか。","respondent":"市川教育次長","answer":"教育委員会がこれまで所管してきた１つの由来というか、古くは社会教育、学校教育と社会教育という２つの大きな体系がありました。その後、その社会教育という考え方の中に、社会の側からの教育をするということではなくて、国民の側から生涯にわたって学習活動を展開する。","id":"exchange-049"},{"speaker":"中塚委員","kind":"質問","question":"その辺がちょっと気になるところでご質問したいと思うんです。文化だったり、スポーツだったり、さまざまな生涯教育がありますけれども、やはりあくまで本人の自由な意思と自由な参加と自発性とが保証されるものにならなければ、内容は豊かにならないのではないのかなと思うので、ニーズというそのとらえ方が、首長に変わったときに生涯学習の前提が変わりはしないかというところでお伺いしたいんです。","respondent":"若月教育長","answer":"そういう意味から、教育委員会で縦割りでやるのではなくて、総合行政の見地から生涯学習的な要素を含め、さまざまな人たちが逆に排除されないようにするために、区長部局に持っていったほうが多くの方のニーズに対応ができるんだろう。","id":"exchange-050"},{"speaker":"中塚委員","kind":"質問","question":"あくまで自由な選択、自由な発想、参加の中ではぐくまれる社会教育、生涯学習として保証する立場を貫かないといけないなというふうに思うんです。なかなかこういう話す機会がないので、こういうときにいろいろ伺いしたいとは思うんですけれども、社会教育、生涯学習、改めて位置づけについて教えていただけますか。","respondent":"堀越生涯学習課長","answer":"今、社会教育からの経過というのはご説明させていただいたとおりですが、今回の組織改正、大きな点でいうと、教育委員会から区長部局へということと、それから、生涯学習と今、区長部局で行っております文化、芸術の振興策。","id":"exchange-051"},{"speaker":"石田（秀）委員","kind":"意見","question":"あまりこれは言いたくなかったんだけど、内容を細かく説明していただいたので一言だけ。組織改正があって区長部局にいくんだから、教育委員会でそこまで突っ込んで言うべき話ではない。組織改正が終わったら、今みたいなこういうことを継続してやってほしいならまだいいけれども、やっていきますというのは今の段階で言う話ではない。これはちょっと言い過ぎだなと思うんだけど、それは。","respondent":"市川教育次長","answer":"道筋としてはご指摘のあったとおりだと思います。先ほど生涯学習課長が説明させていただいた前置きの言葉が抜けていたのが、そういうご指摘をいただくことにつながったかと思います。つまり、現在、組織改正ということで議会にご審議をこれからいただくことになっております。","id":"exchange-052"},{"speaker":"西本委員","kind":"質問","question":"３番のところの保護者の選任を義務化すると書いてあるんですが、義務化というのは具体的にしなければならないという形で受け取ることになるんでしょうか。","respondent":"田村庶務課長","answer":"規定は義務化はされましたが、いないから違法だというような形はとりませんという解釈です。","id":"exchange-053"},{"speaker":"西本委員","kind":"質問","question":"それで教育委員会としてどういうふうに対応を進めていこうとお考えなんでしょうか。","respondent":"田村庶務課長","answer":"先ほど川西委員のご意見の中にありましたが、先ほどの概念が広いですから、教育委員会の中では細川委員がまだお子さんが小さいので……。","id":"exchange-054"},{"speaker":"市川委員","kind":"質問","question":"３番の一番下のマルのところですね。県費負担教職員の転任についてのところなんですけれども、これは改正前はこの市町村教育委員会の内申に基づくということが盛り込まれていなかったということですか。","respondent":"河野指導課長","answer":"今回、この法改正に変わったのを受けて、あらかじめ教育委員会のほうに議案として提出させていただいて、教育委員会の承認を得た上で都教委のほうに内申をするという形に変更になります。","id":"exchange-055"},{"speaker":"市川委員","kind":"質問","question":"内申というのは具体的にどういうことをイメージすればいいんですか。","respondent":"河野指導課長","answer":"内申というのは、こちらのほうからこういうふうにしたいということで提出して、都教委のほうはそれを受けるという形です。原案として提出するという形です。","id":"exchange-056"}]},{"id":"topic-05","title":"の荏原西地区小中一貫校新築工事の進捗状況","agenda":"の荏原西地区小中一貫校新築工事の進捗状況","exchanges":[{"speaker":"石田（秀）委員","kind":"質問・要望","question":"計画変更になった。入札不調でこういうふうになったということをずっと含めると、やはりまたここで説明があるとなると、なぜというふうにはなるので、そこら辺のところはやはり丁寧に説明をぜひしていただいて、ご理解を求める努力をしないと、結構ふいちゃう可能性もあるから、そこら辺のところをぜひ丁寧にやっていただきたいなと思うし、そこら辺のところでご意見があれば伺いたいなと思います。","respondent":"田村庶務課長","answer":"委員ご指摘のとおり、この荏原西の小中一貫校については、いろいろなその時々の状況で統合の話あるいは設計変更の話あるいは入札の不調の話、今度で実質的には４回目ということなので、私どもも委員の意見も踏まえて本当に丁寧に経過も含めて。","id":"exchange-057"},{"speaker":"中塚委員","kind":"質問・要望","question":"庶務課なので環境課とか総務部じゃないから、どこまで聞いていいのかわからないから、わかる範囲で結構なんですけれども、いつわかったのかということと、普通検査したから進めるんですかね。つくっている途中に検査するんですよね。ちょっとこの辺の質問、どうしてわかったのかというところを教えていただきたいのと。指定物質というのはどんなものですかというのを教えていただきたい。","respondent":"田村庶務課長","answer":"それで、一定の体積を勘案しなきゃならないので、１カ所だけではなくどこからどこまでがそうなのかというのを調査して、分析調査を２４地点で実施したということです。","id":"exchange-058"},{"speaker":"中塚委員","kind":"質問","question":"だけれども量が多いからコンクリート化して処分するという話で、要は対策法にはあたらないけどそういう経過で処理をしていくんだという、そこをもうちょっと教えていただけますか。","respondent":"田村庶務課長","answer":"ただし、持ち込み先の基準値があるので、それに対応するような一定の処理量があるので一定の処理をする必要があるだろうということで、埋め立てに持っていける量と、あるいはコンクリート化する量とか、あるいはどこに搬入するか、その辺を今、調整していますけれども。","id":"exchange-059"}]},{"id":"topic-06","title":"の品川区学事制度審議会答申","agenda":"の品川区学事制度審議会答申","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"学校選択制に始まり、一貫校６校構想と小中一貫教育、プラン２１が行われてもう１０年ですが、やはり最後は学校統廃合だ。パブリックコメントのほうからちょっと伺いたいと思うんですけれども、パブリックコメントの目的とそれに対して１３人の応募があったんですけれども、これをどう評価しているのか。ここに寄せられたご意見をどう受けとめているのか教えていただきたい。それとも違うのか。","respondent":"富田学務課長","answer":"パブリックコメントで寄せていただいたご意見についてですが、周知に努めたというふうに私どもとしては考えておりますけれども、寄せられた意見の内容を見ますと、中間まとめで書かれた内容に、例えば学校配置についての考え方であるとか。","id":"exchange-060"},{"speaker":"中塚委員","kind":"質問・要望","question":"具体的に答申についてちょっとお伺いしたいんですけれども、端的にまとめられている部分があるので、どういう意味なのか教えていただきたいと思っているのが、１５ページのところに荏原東地区の配置に関する考察というところがありますけれども、抜粋すると改築時にあわせた近隣校のさらなる統合を検討する必要があるというふうにありますけれども、この近隣校との関係というのはどういう意味なのか。","respondent":"富田学務課長","answer":"したがって、そういったことを踏まえてここに書かれてありますように、人口が減少していくという中で、区民が望まれる意向よりも小規模な学校が増えていく可能性は高いということを踏まえ、改築時にあわせ、改築する場合には近隣校のさらなる統合を検討する必要がある。","id":"exchange-061"},{"speaker":"中塚委員","kind":"質問・要望","question":"教育長が諮問をかけて出て、今日夕方教育委員会の日程が入っていましたけれども、今後のスケジュールのことを教えていただきたいと思います。もう少し具体的に伺いたかったのは、前にもお聞きしましたけれども、２６ページに審議会の評価として品川区が行っている教育改革や小中一貫教育に対する期待にこたえて、いつもそういうふうに期待が高いとはおっしゃいますけれども、その根拠は何かと。","respondent":"市川教育次長","answer":"今後のスケジュールということですが、教育長からの諮問に答申をいただいて、教育長のほうから教育委員会に報告をして、教育委員会のご意見を伺った上で今後の対応策を検討していく。スケジュールとしてはこういう流れになる。","id":"exchange-062"},{"speaker":"中塚委員","kind":"確認","question":"それは意見で結構です。１つ具体的なことで伺いたいのは、学事制度審議会、付属の資料でもはじめから非公開とすると、その話をすると審議会の中でも非公開と確認したとおっしゃいますけれども、改めて答申が出されて、私は議事を公開すべきだと思います。職員の方なら当然出していいと思うんですけれども、議事を公開すべきだと思うんですけれども、それについてのお考えはどうですか。","respondent":"富田学務課長","answer":"そういったことを踏まえて、情報公開請求なりそういった手続を踏んでいただく。会議録はそういった上で公開をしていく予定です。","id":"exchange-063"},{"speaker":"中塚委員","kind":"質問","question":"議事録出しますよ。こういう理由で言うのであれば、今、もう途中経過も何も答申が出たわけですから、区はなぜ積極的に示さないのか。議論はしっかり公開すべきだと思うんです。改めて請求してから出すではなくて、みずから公開するべきであるということは議事録をつくっているんでしょうから、出して当然。それが品川区の情報公開の趣旨であるべきだと思うんですけれども、その点いかがでしょうか。改めて。","respondent":"富田学務課長","answer":"ご意見として承っておきたいと思います。","id":"exchange-064"},{"speaker":"中塚委員","kind":"意見","question":"最後に教育環境というのであれば、やはり３０人学級の実施が何より必要だと思うし、また学級数を変えただけでいいのかという議論でもない。それに合った豊かな教育実践ができるような研究も必要だと思う。今回の答申は保護者の参加も、パブリックコメントが行われていることすら知らない人のほうがむしろ私は多いと思う。私はそれについては納得できません。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-065"},{"speaker":"西本委員","kind":"確認","question":"ちょっと確認をさせてください。８ページのところから考察が入っているんですが、例えば８ページの下のイの配置に関する考察で、ピーク時には６校すべての存続が必要であるとかそういうことが書いてあると思うんですが、これは一貫校になって統合したところの前提で書かれているのでしょうか。","respondent":"富田学務課長","answer":"既に統合するところはした当然ながら現在でということで、ちなみに荏原東地区の検討につきましては、１４ページ、１５ページのところにその後書いておりますが、住基人口が１５％の増ということで杜松小学校。","id":"exchange-066"},{"speaker":"西本委員","kind":"質問","question":"地域割も含めた形で統合、例えば小学校などではくくりがありますよね、それぞれ。その中での配置というのは考えるとわかるんですけれども、中学校になると離れているところがあるので、そうなると数の上では読めない部分があると思うんですけれども、そこまで考慮した形で書いていただいているという理解でよろしいんでしょうか。","respondent":"富田学務課長","answer":"中学校については１６ページ以降ですが、まず１６ページのところで品川区全域、今、学校選択、区内どこからでも希望できるということになっていますので、全地区の中学生住基人口の予測というものを立て、それに対する必要学級数。","id":"exchange-067"},{"speaker":"西本委員","kind":"質問","question":"もう一つパブリックコメントのほうなんですが、１３人ですよね。それぞれいろいろなご意見はいただくんですが、大体ご意見というのがいろいろあるからご意見というのがあって、満足をされている方がわざわざご意見を書かないわけですね、アンケートじゃないわけですから。区の考え方というのを示していただいているんですけれども、これはどういう位置づけでパブリックコメントをするお考えでしょうか。","respondent":"富田学務課長、市川教育次長","answer":"そういう意味では、一概には論ずることができないのですが、皆様のご意見をいただいた上で、今後の審議の参考にしたいという学事審の皆さんの強い意向を受けまして、今回実施をしておりますので。委員の思いとしては、自分たちの想像もつかないような、あるいは自分たちと全く違う立場の人がこのことを考えたときに、今後審議を進めていく上で参考になることがあればというような思いが皆さんおありでした。","id":"exchange-068"},{"speaker":"西本委員","kind":"質問・要望","question":"区全体というような話になってくるので、教育委員会の方にというわけではないんですけれども、最近こういう手法でご意見を聞くというケースになっているんですが、往々にしてこちらが希望していたもうちょっと建設的な意見であるとか、それからもうちょっと違う考えだったりとかというようなものであると助かるかなとも思ってはいたんですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-069"},{"speaker":"市川委員","kind":"質問・要望","question":"２７ページの2)の最後のほうですね。最後の２行、「また、敷地面積等の制約により、建設可能な学級数があまりも少なくなってしまうような条件下での学校改築については、慎重に対応すべきと考えます」というあたりがちょっと読みこなせないんですけれども、説明していただきたい。","respondent":"富田学務課長","answer":"次に後段の計画的、早目に周知して準備を進める必要があるということについては、ここで人口が上昇中でありますけれども、下降のあたりが見えてきたところを見すえて、計画的にということにつきましても、ここに書かれているとおりというふうにご理解いただければと思います。","id":"exchange-070"},{"speaker":"市川委員","kind":"質問","question":"最初の質問に対する答えとしては、敷地面積の中で小さな学級数の少ない学校をつくることは許可がおりないということなんですか。","respondent":"富田学務課長、市川教育次長","answer":"これは審議会の意見として書かれているとおり、許可がおりるとかおりないとかでなく、要するに可能な範囲で、もし改築するとすれば法律を守って建てていくということになりますので、おのずから規模には制約があるということを踏まえて。この答申の２行の背景は、改築をするときに敷地面積が小さいときに一番わかりやすいんですけれども、近隣との日照の関係だとか何かで、今の学校規模が建たない。","id":"exchange-071"},{"speaker":"市川委員","kind":"質問","question":"今のお答えでわかりました。先ほどの計画の策定と区民周知については、今後はこの答申の意見を受けたということで、品川区としてもこれに即した形で進めていきたいという意向をお持ちだということでよろしいんでしょうか。","respondent":"市川教育次長","answer":"今、委員、要約していただきましたけれども、審議会でもそういう意見が出されまして、そういうことに今後留意するようにということで、いわば注文がついたという形になってありますので、これについては教育委員会としても今後どうしていくかということ。","id":"exchange-072"},{"speaker":"中塚委員","kind":"質問","question":"こういう審議会という仕組みがちょっと私自身よくわからないので、答申が出ますよね。教育委員会として答申に対する返事というか回答というか、今後の方針というか、そういう形で何か示されるのか。今日の文教委員会の報告、これから教育委員会定例会でもう１回議論して、今後こういう方向だというのは、委員会に報告があるのか。ちょっとその辺教えていただけますか。","respondent":"富田学務課長","answer":"今後のスケジュールということでお答えをしているとおりですけれども……。","id":"exchange-073"},{"speaker":"石田（秀）委員","kind":"意見","question":"１点だけお願いをしておきます。これを見ていて、過去品川区の中でも１つのものが出てきた。そのときの学校の適正規模検討委員会というのかな、あのときでも、必ず子どもたちにとって３クラスがいいのではないか。私はやはり基本的には２、３クラス、施設一体型、これは必ず今後も進めていくべきだろうと思っていますので、これを見ての私の感想だけは言っておきます。希望だけ言っておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-074"},{"speaker":"山元委員","kind":"質問・要望","question":"実際自分が住んでいるこの地域で、やはり小さい学校というのは危機感を感じていて、近所の学校にたくさん生徒を取られて、地元の方々というのは本当にその学校がもしかしたらなくなってしまうのではないかという思いがあるわけですが、今言った八潮の一番いい例が、やはり皆さんの地元の方とか、父兄の方とかいろいろな方のいろいろな話し合いがあって、こういう形になったわけなんですが、そういう意味では。","respondent":"富田学務課長","answer":"こういった視点、ご指摘もいただいていますので、まだ先のことを申し上げられませんが、十分こういったご意見を踏まえていろいろ検討していきたい。これからの課題というふうに考えております。","id":"exchange-075"},{"speaker":"川西委員","kind":"質問・要望","question":"学校選択もやり、一貫校もやりというような中で、やはり１つはこれまでのやってきたことを進めながら、住民の意向がここにも書いてありますけれども、十分に選択できるような中身、最後に書いてありますように、やはり２学級、３学級、アンケートが出ているように、これを入れて大胆に方針を出されていくことが早期に求められていると思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-076"}]},{"id":"topic-07","title":"の平成２１年度入学生の希望申請の集計結果","agenda":"の平成２１年度入学生の希望申請の集計結果","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"こういう乗り入れを去年からやめにしたという話で、選択制が始まる前からそれぞれ事情に応じて個々の判断に基づいて認めてきた経過があるわけですけれども、去年から一切どんな事情かあろうとだめだということですけれども、その理由がなぜかということと。これはちょっとひどい話だなと思っているんですけれども、ちょっと教えていただけますか。","respondent":"富田学務課長","answer":"この通学距離により、区域外にある区外からの就学を認めている区というのはほとんどございませんで、品川区は近隣の、決算特別委員会の折にも申し上げましたが、隣接しております港区、目黒区、大田区。","id":"exchange-077"},{"speaker":"中塚委員","kind":"質問","question":"実際、冨士見台中はすぐ先が大田区という関係があって、また、大田区の事情で言うと東馬込一丁目、二丁目というのは国道を渡らなければ学校に通えない。それはちょっとひどい話だなと。そもそももとに戻してほしいというのが第一義的。せめてという意味で言えば、今の兄弟関係は区が後からルールを決めたわけですから、それはちょっと認めるべきじゃないのかなと思うんですけれども、いかがでしょうか。","respondent":"富田学務課長","answer":"そもそも区民の皆さんでいっぱいになってくるような状況が先々含めて想定をされるといったこういう状況の中におきまして、区民の皆様の血税を使って区外の方々の受け入れを大勢していくということについて。","id":"exchange-078"},{"speaker":"中塚委員","kind":"質問・要望","question":"最後のほう、区民の血税を使って区民のほうは理解されないみたいな話がありましたけれども、大田区の子どもが伊藤小学校、冨士見台中に来ることをみんな理解していますよ、地域は昔から。学校は余裕と言ってはあれですけれども、入れるわけですからね、現状でも。これはぜひ子どもの立場に立って、地域事情に立って、地域はみんな理解していますから。再検討いただきたいと思います。要望でいいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-079"},{"speaker":"石田（秀）委員","kind":"意見","question":"これを見ると１０２人なので、多分２人の抽選をしたんだと思うのね。１００人ですよね、これ。そうすると２人でしょう。やらなくてもね、２人だと思うんだ、これ。２クラスだから多分抽選になるんだけど、ここら辺もね、もうちょっと弾力的なところがあってもいいような気がするんだけれども、毎回例年はわかっているんだから、だけどやはり抽選はせざるを得ないという方針なのかな。","respondent":"富田学務課長","answer":"第二日野小学校についてなんですが、実は第二日野小学校の通学区域の方で他の抽選校を希望している方が大勢出ているという状況がございまして、学校選択のルールといたしまして、抽選の結果、待機になった場合にはもとの通学区域の学校に戻すというようなことがあり、戻った結果。","id":"exchange-080"},{"speaker":"西本委員","kind":"質問","question":"ある地域の方から、これはかなりＰＴＡのお仕事をされている方で保護者の方なんですが、どうして選んだのですかという質問なんですね、大体。どうして選ばなかったんですかという、そういうのはできないだろうかということをおっしゃるんですよ。何で選ばなかったんですかという質問も意味があるのではないかということをおっしゃるんですけれども、そういうお考えはいかがでしょうか。","respondent":"富田学務課長","answer":"学校選択をされた保護者の方へのアンケートというのを毎年やっておりますが、経年変化を見るというようなことでもって、できるだけ設問を統一して動きを見るというようなことをやっておりまして、あとは個別の自由記載等々の部分もありますので。","id":"exchange-081"},{"speaker":"西本委員","kind":"質問・要望","question":"自由記載というところでご意見は皆さんいろいろとされているということでしょうか。若干それに近いことはあるかもしれないんですけれども、だけど、頑張ってやっているよというようなところも含めて、ちょっと校風までいかなくてもいいんですが、皆さん、地域の方たちに知っていただくという行動はするべきではないかなというふうに思います。ご意見がありましたらよろしくお願いします。","respondent":"富田学務課長","answer":"ただいまいただいたご意見を参考にさせていただきたいと思います。","id":"exchange-082"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/361184?Template=document&Id=4650#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":76188,"voices":218}},{"id":"h20-20081125-5","meetingId":"h20-cm11","date":"2008年11月25日","dateIso":"2008-11-25","committee":"総務委員会","time":"午前１０時０２分～午後 ２時３９分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を85件抜き出しています。","topics":[{"id":"topic-01","title":"議案審査をまず行います。 １番目の第７４号議案、品川区組織条例","agenda":"議案審査をまず行います。 １番目の第７４号議案、品川区組織条例","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"本来、学習というのは、自発的で内発的なものだと思うし、自由であるべきだと思うんですけれども、まず学習というものがどういうものかという認識を伺っておきたいし、これは区長部局のほうにいったときに、どういうふうにそのことが担保されていくのかというのを、まずちょっと伺いたいと思います。","respondent":"福島長期計画担当課長","answer":"生涯学習ということ自体は生涯にわたる学習すべてのことを示しているものだと考えています。では行政は何をするのかといいますと、その自主的、自発的に行われる学習に対する支援を行うのが行政の役割であると考えています。","id":"exchange-001"},{"speaker":"南委員","kind":"質問・要望","question":"先ほど紹介した４０ページの、それぞれしくみを構築するというここのところなんですけれども、学習成果を社会に還元する、これはどういうことなのか、また区長部局のほうにいって、それがどういうふうに具体的に、何を目的に学習成果を社会に還元するというふうに叙述してあるのか、どういうものを目指そうとしているのか、今後の課題についても、先ほど紹介した中身について。","respondent":"福島長期計画担当課長","answer":"だだそうしたみずから学んだことをみずからだけにとどまるのではなく、学んだことをほかの方に伝えたり、あるいは教え合ったり、そういった大きな意味での支え合えといったものが社会に必要であろうということで。","id":"exchange-002"},{"speaker":"南委員","kind":"質問・要望","question":"いろいろな事業を提供していく、あるいは自発的な事業をやりたいと申し込まれた団体や区民の方々には、オープンに支援していく体制を広げていく、そういう自治体としての仕事の姿勢が望ましいんじゃないかなと思うし、それが法の精神だと思うんですけれども、その点についてはどうなんでしょうか。","respondent":"福島長期計画担当課長","answer":"最初の質問にございましたように、学習というものは自発的なものでありますし、また自主的なものであろうと考えてございまして、また最初の質問ですけれども、行政といたしましては、それを側面から支援していくという役割であると考えています。","id":"exchange-003"},{"speaker":"南委員","kind":"質問","question":"そう言いながらも、やっぱり政策の方向性とか今後の課題については、そこが前面に出ているんですよ。今回、こういうのが出てきているのは。同時に、自由で自発的な学習を区民と協働するというここのところは、どういうふうにリンクして事業展開しようとしているのかが、全く別分野のものだと思っていたので、その辺について改めて伺っておきたいと思います。","respondent":"福島長期計画担当課長","answer":"区としましては、協働ということを今回、この長期計画では重点に置いてありますので、今回、こういう区民との協働による生涯学習という言葉を使わせていただきますけれども、区民の皆様が学び合っていく学習社会をつくるということについては。","id":"exchange-004"},{"speaker":"南委員","kind":"確認","question":"最後にちょっと意見だけ言っておきたいと思うんですけれども、自発的なもの、それを本当に担保するということと、それから、学んだことを他に伝えるとか、教え合うとか、そのことはさっきも申し上げたように否定するものではないし、大事なことだとは思うんだけれども、しかしある一定の法律が改正されて、学習成果を発表するとか、あるいはそれを社会に還元させるとか、そういう方向が強まっていき。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"林委員","kind":"意見","question":"最初に大きいくくりの中で、教育委員会が非常に変わった。学校教育と生涯学習。その教育委員会をここから外しちゃうところがどうかなと気がしているんですよ。","respondent":"福島長期計画担当課長","answer":"ただ一部残すものもありますので、そういった中では、社会教育に関するものそのものにつきましては、あくまでも教育委員会の仕事ですので、例えば社会教育関係団体の登録ですとか、そういった社会教育の根幹になるようなところは教育委員会のものとして残しますので。","id":"exchange-006"},{"speaker":"林委員","kind":"意見","question":"そういうことが変わってきているというか、行政の役割とは思わないけれども、行政のサービスの１つになってきたときに、教育委員会とこれとどこでだれが線を引くのか。教育長がうちのだと言ったときに、だれが言うの。企画部長が言うの。その辺の実質的な、４月１日から始まったら、そういう実際の区民の側がサービスを受ける場合や、職員の人が働く場合や、いろいろなケースとして混乱が起きませんか。","respondent":"福島長期計画担当課長","answer":"それにつきましては、この段階で考えられるのは両者が連携して進めていく。よく両者で協議しながら、どちらの部分なのかということを決めていきたいと思います。それは個々の事業あるいは施策によって違ってくると思いますので、ここはここにと考えています。","id":"exchange-007"},{"speaker":"林委員","kind":"質問","question":"１つずつ区のほうのサービスあるいは区のほうの事業で、これは事業部で受ける、これは教育委員会でやる、あるいは学校に出先のいろいろな細かい指示は出すとか、そういうところまでやっているんですか。","respondent":"福島長期計画担当課長","answer":"そういった意味では、現在行われております区の仕事、事務事業につきましての切り分けについてはしっかり、企画もそうですけれども、各所管と企画、さらには所管同士、十分な話し合いを行って切り分けてありますので、４月１日を安心して迎えられると考えています。","id":"exchange-008"},{"speaker":"林委員","kind":"質問・要望","question":"一般質問でもやったので重ならないようにしておきますけれども、どうも防災というのは気になってしようがないので、一言だけね。水辺をつくっていくという考え方、行政としてね。区民の人たちが水辺に憩いを求め、あるいはいやしを求め、今ある水辺プラス必要な水辺を整備していく。東京都がおまえら手を出すなと言われたら、ああそうですかと言わなきゃならない。","respondent":"福島長期計画担当課長","answer":"最初の清掃・リサイクルのことです。確かに考え方としましては、委員おっしゃいますように、リサイクルできるものはリサイクルして、それで実際できないものについて清掃に回すということは、考え方としては確かにそのとおりだろうかと考えています。","id":"exchange-009"},{"speaker":"林委員","kind":"質問・要望","question":"ないものをつくり出していったり、区民が求める何かを提供する、そういう考え方を持たないといけないと思う。企画から手が移る４月１日移行の話になると思うので、その辺をしっかり伝えておく。２つ、子ども未来事業部に子どもというのがない。それが１点と、もう１つは一般質問でも言った観光課。ここに一たん入るのはいろいろな事業の内容でわかるんだけど、早く返すべきだと思う。いかがですか。","respondent":"福島長期計画担当課長","answer":"観光につきましては、答弁でもお答えしましたとおり、観光協会というのが従来からありますので、そういった協会を区としても支援していくと、そういう課として支援することが主な仕事となりますので、決して横取りをする、横取りをして。","id":"exchange-010"},{"speaker":"林委員","kind":"質問","question":"一般質問でも言ったけれども、行財政改革という品川区がずっと持っている感覚がちょっと途絶えた、最初の名前のところもそういう部分があったけれども、それはずっと続いているというお話ですけど、それはそれで受けとめて、新しい組織がスタートするに当たっては、何でもやってあげるという自治体の組織じゃなくて、区民が何かやることに対するサポート、サーバーであってほしい。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"土井委員","kind":"質問・要望","question":"今までは教育委員会の後援をいただいていましたと、大変なお墨付きで皆さんやっていた部分があるんですね。その言葉をもらうために、必死になって、何カ月もかかってやっていらっしゃる場合もあるんですから、ぜひそこら辺は変わらないようにお願いして、これはさっきの観光のところでも同じようなことが言えるんですね。そういうぜひ組織にしておいていただきたいなと思いました。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"須貝委員","kind":"質問","question":"早く対応できるようにですね。対応する場所、特に名称も変更されるわけですから、本当に入ったら、あれ、昨日と全然違うなとか、１週間前と違うなと、やはりそういうことで混乱するんじゃないかなということは想定、もちろん区なども想定していると思うんですが、その対応ですね。","respondent":"福島長期計画担当課長","answer":"個別につきましては、個々に案内を出すつもりですし、また庁舎の全体的な案内のパンフレットといったものも作成する予定です。庁舎に出ています、入って入口の案内人がいるんですけれども、そこもその間は強化するように考えたいというふうに思ってあります。","id":"exchange-013"},{"speaker":"南委員","kind":"質問","question":"その児童センターを外したことはどういう理由だったのかを１点聞きたいのと、２つ目には、地域特性を生かして事業展開していくために、３つに分けて、それぞれの担当の地域を振り分けたんだということなんですけど、地域の特性を生かした事業展開という点では、それは否定しないいいことだと思うんですけれども、とりわけここの長期基本計画を読んだりすると、小学校に入学をスムーズに移行できるように。","respondent":"福島長期計画担当課長","answer":"小学校での円滑な入学ですけれども、小学校につきましてはブロック制をしいてありますので、違うところに入学するとか、そういうことは想定してございませんで、そのブロックの中での保育園ですので、保育園と小学校。","id":"exchange-014"},{"speaker":"南委員","kind":"質問・要望","question":"ですからそういう点で、地域展開、地域とのかかわりということは全く否定するつもりはないけれども、大事なことだと思うのでね。非常に心配していらっしゃいますよね。それとも、ほかの担当する課に行くんですか。それ辺は、区民に対してどういうふうに入園の段階から周知徹底するというふうに考えているのか、その辺を改めて伺いたいと思います。できたら私はそういうことはやめるべきだと。","respondent":"福島長期計画担当課長","answer":"今年も３月にティーンズフェスティバルを開きますけれども、そういった形で実施して、児童センター等が連携した事業を今行っているということもありますので、今年度につきましては、児童センターは一緒にしておこうということにしたものです。","id":"exchange-015"},{"speaker":"南委員","kind":"確認","question":"そうすると、申し出をすると、そこで申請事務は受け付けるということでいいんですか。ちょっとその辺の確認です。それで、子育て支援課が八潮地域、大井地域がそうなんですけど、ここのところは保育園に入ってからの事務になってくるという理解でいいんですか。だから、どの程度現場の声を聞いてこういう案が出てきたのか、その辺はしっかりと聞きたいと思うんですけれども、どうなんですか。","respondent":"福島長期計画担当課長","answer":"現場の声をということですけれども、当然ながら今回の組織改正を行っていく過程で、職員の意見を聞き、また意見を参考にしながら進めてきたものですので、当然ながら現場の声は聞いているものですし、こちら企画部としましても、情報については隅々まで流していると考えています。","id":"exchange-016"},{"speaker":"南委員","kind":"質問・要望","question":"したがって、きちんとした説明をし、そしてこういう考え方でやろうとしているけどいいだろうかという意見を聞いて、そして斟酌して、きちんとまとめていくと、そういうことが理事者のところには求められることだと思うんですけれども、そういう声というのは聞いているという話なんだけれども、聞いているということを言っておきながら現場ではわかっていない。","respondent":"福島長期計画担当課長","answer":"今、１１月の終わりになっていますので、その間、ずっと区としまして、また企画部としましては、職員と話し合いながら、またどういう組織がいいのか検討しながら、また総務委員会でもご報告し、ご意見をいただきながら、そういう中でつくり上げてまいりましたので、職員。","id":"exchange-017"},{"speaker":"金野委員","kind":"質問・要望","question":"前回のとき、私もこのことは大まかな言い方をしたんですけれども、特にこういった高齢者の方々への対応というのは非常に混乱を招くこともありますし、また手続上でも高齢者生きがい課もできてくるし、これは高齢事業課の事業の内容がそのまま移行しているものなのか、ちょっと確認させていただきたいのと、高齢者の対応に対して、この課での取組みの今の姿勢というか、お聞きしたいと思います。","respondent":"福島長期計画担当課長","answer":"来年以降につきましても、引き続きこちらを、今度は子ども未来事業部のほうで進めていく予定です。内容についても充実させていきたいと考えています。年金が高齢者のほうに移るです。","id":"exchange-018"},{"speaker":"金野委員","kind":"質問・要望","question":"それぞれまた、先ほどもほかの委員からもありましたように、スタートしていくと、個々に少しずつ手直しをしなきゃいけないところも出てくるんだろうとは思うんですが、より混乱のないように、これは重々皆さんもそのつもりだと思うのですが、あるいはお話を聞いて多少安心をしましたが、やはりスタートしていく意味では、そこら辺のところを万全を期していただきたいという思いで、終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"}]},{"id":"topic-02","title":"２番目、第７５号議案、品川区教育に関する事務の職務権限の特例に関する条例","agenda":"２番目、第７５号議案、品川区教育に関する事務の職務権限の特例に関する条例","exchanges":[{"speaker":"土井委員","kind":"意見","question":"中身はわかりました。すっかりわかったんですが、問題は根拠法に書いてある下のほうの２番、「地方公共団体の議会は」というくだりなんですけれども、そうすると、これは聴かなきゃいかんとなっておりますから、聴いたのかどうかという話と、それをこっちは聴かなければいけないので、どうなっているのか。文教委員会のところでちゃんと聞いているのか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-020"},{"speaker":"南委員","kind":"質問・要望","question":"そういう関係での事務というのはどういうふうになっていくのか。学校ですから、当然教育委員会の施設になるわけですけれども、そこと今度区長部局のほうに移ったときに、その辺がどういうふうになっていくのか、ちょっとその辺が見えないし、非常に心配、不安の声があると聞いていますので、その辺について教えていただきたいなと思います。","respondent":"福島長期計画担当課長","answer":"スポレクにつきましては従来どおりですので、特に変わることはございません。学校の体育館を利用しますので、学校とは当然ながら連携は強化してまいりますので、学校と調整しながら、今までどおり、あるいは今まで以上に使いやすいようにしていきたいと考えています。","id":"exchange-021"},{"speaker":"南委員","kind":"質問・要望","question":"そういうところの方々が今までどおり月、定例１回とか２回とか練習にいきたいというときには、スポレク委員の方々が招集する会議に参加をして、そこでうちは第何曜日とかということを申請して、調整して使えるようになっていくという、そういうことなのかなという最終確認が１つと、そのスポレク委員という方の位置づけというのは、これはどういうふうになっていくんですか。","respondent":"福島長期計画担当課長","answer":"申請につきましては従来どおりですので、変わるものではございません。スポレク委員の位置づけにつきましても今までどおりです。","id":"exchange-022"},{"speaker":"南委員","kind":"質問","question":"わかりました。その辺はスムーズに移行しなきゃいけないというのは当然ですから、そのとおりなんだろうなと思うんですけれども、できるだけ周知も徹底していかなきゃいけないと思います。課題としてあるんですけどね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"林委員","kind":"意見","question":"さっきの話から引き続いてくることになるんだけれども、このスポーツに関すること（学校における体育に関すること）、学校における体育に関することなんていう言葉ってあるのかい。次もそうなんだけれども、文化財の保護に関することを除く。文化に関することで、文化財の保護に関することを除く、そうすると、これはイコールになると、文化財の保護が文化に関することなの、この文章でいくと。","respondent":"福島長期計画担当課長","answer":"文化につきましては、文化財の保護イコール文化に関することでは、当然のことながら違いまして、広い文化の中の一部、文化財の保護については除くというものです。実際、品川区でも文化財につきましては、教育委員会のほうで今後も担当するものです。","id":"exchange-024"},{"speaker":"林委員","kind":"質問","question":"特に文化財の保護なんていうのは、文化財という価値によっては、まちの中にある古いものという言いわけになっちゃうこともあるわけだから、そういうことも含めて、教育委員会がしっかりと判断を持って学校に伝えなければならないし、学校以外で何かをするときに、その線引きをしっかりと教育委員会が持っていないと混乱が起きるというふうに心配するので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"須貝委員","kind":"質問・要望","question":"今回の法律改正は、抜粋すると、「教育に関する事務のいずれか又はすべてを管理し、及び執行することとすることができる」ということで、あえてしなきゃいけないとは書いてはいないんですが、今回こういうふうに品川区が条例制定するということは、何か問題があったんでしょうか。メリットとかデメリットがもしありましたら、ちょっと教えていただきたいなと思うんですが、よろしいですか。","respondent":"福島長期計画担当課長","answer":"今回、この条例を制定しましたのは、区長が一括して行っているということを内外にも示していくということも必要ですし、今言いましたように、一括してやるためにはこういった形の条例がないと、一部の補助執行にとどまってしまいますので。","id":"exchange-026"},{"speaker":"須貝委員","kind":"質問","question":"じゃ、別段何ら今まで問題はなかったけれども、今後は品川区レベルの、もうちょっと権限をというんですか、執行する権限を強くするという、区長レベルで強くするという意味合いで、今回、品川区も条例制定に踏み切ったと考えてよろしいですか。","respondent":"福島長期計画担当課長","answer":"問題がなかったというのは、特に法律上、補助執行ですとか、そういうことをすることについては問題がないという意味合いでございまして、区長部局のほうで一体的にこういった生涯学習行政を進めていくということについての課題はございましたので。","id":"exchange-027"}]},{"id":"topic-03","title":"３番目の第７８号議案、品川区保健所の設置に関する条例の一部を改正する条例","agenda":"３番目の第７８号議案、品川区保健所の設置に関する条例の一部を改正する条例","exchanges":[{"speaker":"林委員","kind":"質問","question":"線引きをされて、これが本庁舎のほうに移って、これが出先の保健センターでありましてと書かれてあるので、見ればわかるでしょうと言われればそれきりなんだけれども、４つにすると。例えば荏原の保健センターに行って話が解決しないから、本庁舎の保健所に行って手続をしてくださいよと、これでそういうことは起きないですか。","respondent":"福島長期計画担当課長","answer":"先ほど説明しました対物と言われているような分野で、例えば届出が必要なもの等につきましては、地域での保健センターでも受付はいたします。","id":"exchange-028"},{"speaker":"林委員","kind":"意見","question":"まれなケースなのに、何で保健所を本庁舎内につくらなきゃいけなくなったのかなというのが、そもそも今までどおりでいいんじゃないか。荏原に保健所があって、品川に保健センター、大井に相談所があって、保健に関する行政のサービスがそれで行き届いていたんだろうと。これで例えば品川、荏原、大井という３つの地域が、それぞれのところに保健センターとして機能し出しますよと。","respondent":"福島長期計画担当課長","answer":"ただいわゆる事業者の方が届出をするですとか、そういったときは１カ所になるということで、これはまた地域割がなくなったということで、定着すればよりわかりやすさも出てくるのではないかと考えています。","id":"exchange-029"},{"speaker":"須貝委員","kind":"質問","question":"まして感染症・新型インフルエンザ等の緊急危機事象発生時と書いてありますが、まさにそういう新型インフルエンザの危険性をマスコミ等もうたっていますが、一々本庁舎へ行って対応を仰ぐというのが、果たしてどうなのかなと。もっとそばで、とりあえずちょっとおかしいんだけどというときに、本庁に行かないと詳しいことはとかいうことがないんでしょうかね。その辺は大丈夫なんですかね。","respondent":"福島長期計画担当課長","answer":"今の組織ですと、保健所が荏原のほうにありますので、といいましても、例えば都から連絡がある場合は、まず健康課のほうで１回受けまして、それを保健所に伝えてという形で保健所で対応する。","id":"exchange-030"},{"speaker":"須貝委員","kind":"質問","question":"もう１点だけなんですが、今度区民の事務手続なんですが、これは逆に本庁まで行かなきゃいけないという煩雑さというんですか。区民サービスの点から考えて、こういうのが増えちゃうんです、本庁に行ってもらわないと困るんですというような、今までと違った状況というのは生まれるんでしょうか。","respondent":"福島長期計画担当課長","answer":"基本的にはどこの地域のセンターでもその受付はできるようにという体制はとってまいります。ですから、煩雑さはないと考えています。","id":"exchange-031"},{"speaker":"金野委員","kind":"確認","question":"細かい点なんですが、今まで品川区保健所の中では、例えば精神保健の相談の窓口だとかがありましたけれども、これはこういう地域の保健センターのほうに振り分けられるのか、それが１点と、あと大井保健センターと改正後はなるということですが、荏原と品川に比べると、大井保健センターは建物自体も非常に小さく、業務が同じようになるのか、そこら辺が心配なんですけれども、どうなんでしょうか。","respondent":"福島長期計画担当課長","answer":"といいますのは、精神衛生に対応している保健師ですとか心理師はそうそう人数がいるわけではありませんので、２つの部署に分かれていますと、例えば１人が相談業務で家庭訪問をしていると、１人が留守番でということになると。","id":"exchange-032"},{"speaker":"金野委員","kind":"確認","question":"そうすると、先ほどの手帳の発行等がこちらでできるので、相談も訪問も安心できるという。実際に、例えば心の病気で、相談の窓口というか、直接来庁して相談をする、そういったものもここの中でできるというか、それとも各保健センターのほうにそれぞれに窓口があって対応してくださるものができるのか、そこを確認させてください。","respondent":"福島長期計画担当課長","answer":"この分野につきましては、障害者福祉課との連携でもかなり重要になってありますので、今回、区役所として一緒になることによりまして、そういった形での連携もより進むのではないかと考えています。","id":"exchange-033"},{"speaker":"金野委員","kind":"意見","question":"とても心の病を持っていらっしゃる方は、それでなくてもパニックというか、あると思いますので、一括にされて、そのようにスムーズにいくということはとても大事なことだと思いますし、またこの保健センターで第１段階、それでは対応がきかない場合、じゃ、本庁舎へというような流れも起きてくるのかなと、いろいろなこともあると思いますが、特に心のというところでは。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-034"},{"speaker":"南委員","kind":"質問・要望","question":"感染症の関係でちょっと伺いたいんですけれども、私も前回のときはかなり心配して、きちんとした対応をとるために、本庁のほうに保健所部分を持ってくるということについて、感染症対応は危機的な状況が見込まれるのでということだったんですけれども、それはそれとして大事なんだけれども、果たしてどうなのかなという疑問がちょっと残ってはいたんですけれども、改めて伺うんですけれども。","respondent":"福島長期計画担当課長","answer":"保健師の配置ですけれども、当然ながら保健師もこちらのほうに対応することになります。","id":"exchange-035"},{"speaker":"南委員","kind":"質問・要望","question":"新型インフルエンザは別として、例えば日常的に起こっている感染症というのがありますよね。結核も含めて。そうなると、現場の３カ所の保健センターに配置している保健師を一定程度引き上げて本庁のほうに来なくちゃいけないと思うので、私はそう思うんですよ。当然そういうふうになるのかなと。その辺の気持ちをちょっと伺いたいなと思うんです。","respondent":"福島長期計画担当課長","answer":"感染症対策です。こちらにつきましては、従来２カ所で行っていましたものを保健所として１カ所で行いますので、そういった意味でのスケールメリットといいますか、人数が多く集まりますので、十分な対応、きめ細やかな対応ができると考えています。","id":"exchange-036"},{"speaker":"南委員","kind":"質問・要望","question":"そういう関係では出先で対応したほうがいいんじゃないかと思っていたし、今までもそういう考え方でそれぞれの保健所で地域割して対応していたと思うんですけれども、そこのところも結局変わっちゃうわけですから、その辺の変わった理由というのが、出先でやったほうがより相談しやすいんじゃないかという、住民の側から見たときにそう思うんだけれども。","respondent":"福島長期計画担当課長","answer":"実際的に日常的なケアをどうしていくかという個々具体的なものにつきましては、その人によって違うと思いますので、本庁のほうのより専門的な担当課へかかわったほうがいいもの、あるいは保健センターで対応していくほうがいいもの、それは個々のケースによって違うと思います。","id":"exchange-037"},{"speaker":"土井委員","kind":"質問・要望","question":"今のお話でわかりました。だからそこら辺の対応を、この状況の中ではぜひ進めていただきたいと思うのが１つ、それから当然のことながら、何人かこちらにいらっしゃると、場所が今までちゃんとあるわけですから、そこが少し広く使えるようになるわけですね。ややもすると、虎視たんたんとそういうところをねらっているのがたくさんいるわけですから、ぜひその点はお願いしたいと思います。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"}]},{"id":"topic-04","title":"４番目、第７９号議案、品川区保健センター条例の一部を改正する条例","agenda":"４番目、第７９号議案、品川区保健センター条例の一部を改正する条例","exchanges":[{"speaker":"林委員","kind":"確認","question":"確認させてください。今、保健所に入っている指定管理者で、今回取り替えるという、それはないですか。","respondent":"福島長期計画担当課長","answer":"指定管理者の変更はあります。これは違うところで審議されております。","id":"exchange-039"},{"speaker":"林委員","kind":"質問","question":"第１４条のところが指定管理者の項になるんだろうと思うんだけど、指定管理者になるのは品川だけですか。品川健康センターでよろしいのかな。","respondent":"福島長期計画担当課長","answer":"両方。","id":"exchange-040"},{"speaker":"林委員","kind":"意見","question":"その人たちは旧のものを理解して品川の指定管理者になるよと手を挙げているのか、いつからによってはこれが変わるということを把握していないと困るわけで、この辺は指定管理者の議論は別の委員会でやるというふうになっているんだけど、２つあるというと、組織上でどの条例を把握して指定管理者として手を挙げているのかわかりますか。","respondent":"福島長期計画担当課長","answer":"これを読みながら現在進めているところです。今回、指定管理者が行いますのも健康センター部分ですので、こちらを読み替えていただければ大丈夫だと考えています。","id":"exchange-041"},{"speaker":"林委員","kind":"質問","question":"そうすると、いわゆる健康とか健診とか、そういうことに関しては指定管理者はかかわっていなくて、区民が健康センターを利用する際の指導とかアイデアをいっぱい出してもらう、そういうふうに理解しておけばいいわけですか。","respondent":"福島長期計画担当課長","answer":"保健センターのほうの指定管理者ということになります。健康センターはまた別です。言い方を間違えたのかもしれません。健康センターについては指定管理者で行います。保健センターは保健所ですので、区のほうで行います。","id":"exchange-042"}]},{"id":"topic-05","title":"第８６号議案、総合区民会館第３期舞台照明設備改修工事請負契約","agenda":"第８６号議案、総合区民会館第３期舞台照明設備改修工事請負契約","exchanges":[{"speaker":"林委員","kind":"質問","question":"こっちの資料のほうの３ページの舞台照明設備の改修工事全体、５番のところでの(3)が今回の改修工事なんだけど、ちょっと何が違うのか説明してくれる。照明設備というのは全部同じで、次の図を見てくださいと言われても、どこが違うのか。申しわけないんだけど、(1)(2)は幾らぐらいで落札があったのかも一緒にわかれば教えてください。","respondent":"阿部経理課長","answer":"もう１つ、平成１９年度に行いました(1)の大ホール照明操作卓等につきましては、契約金額が７,６６５万円です。(2)の小ホールの照明操作卓等につきましては３,７８０万円です。これが契約金額です。","id":"exchange-043"},{"speaker":"林委員","kind":"質問","question":"そうですか。この図は９階の、僕らがふだん見られない真ん中の下あたりの調光器室というところのものであるということで、１つお聞きしたいのは、きゅりあんで和太鼓が使えないというようなことを言われていて、ほかの部屋にというか、ほかの使っているところに音が漏れちゃうというのか、そういうことで和太鼓は使えませんと。そういうことは今回直せるんですか。","respondent":"宍戸施設担当課長","answer":"今回は照明器具の改修ですので、その和太鼓の対応で改修するということではございません。","id":"exchange-044"},{"speaker":"林委員","kind":"質問","question":"素人なものでよくわかりませんけれども、せっかく手を加えるならば、できるならそういう人たちも使えるようになればいいなと思いましたけれども、だめなんですか。では、それはそれでわかりました。こういう数字というのは久しぶりに見たんですけれども、何が原因かという言い方はちょっとあれかわからないけど、これだけ厳しい競争が行われたというのは、何かお考えがありますか。","respondent":"阿部経理課長","answer":"私ども、正直、応礼しましたけれども、実はこの東芝ライテックというところは照明器具製造のトップメーカーです。なおかつ、工事の施工も行うという業者ですので、そういう面からこういう金額、４６.４％ですけれども、こういう金額で応札をしたのかなと思っています。","id":"exchange-045"},{"speaker":"林委員","kind":"意見","question":"単純に計算すると、その上の２番目の人なんかは１億ぐらい多いわけで、こういう競争は、素人が考えるとですよ。そういう理由でこういう落札価格が出てくるとすれば、非常に歓迎するところなんですけれども、当事者の課長で、そういうこれからの指名についてのお考えがあったら聞かせてください。","respondent":"阿部経理課長","answer":"ですから、安いことに関しては、非常に私どもとしてはうれしい限りですけれども、すべてこれからこういう形で安くなるかというのはちょっと疑問でございまして、今申し上げたような制限をつけつつ、十分な品質の工事をやってもらうという形で行ってまいりますので。","id":"exchange-046"},{"speaker":"土井委員","kind":"質問・要望","question":"ちょっと関連するのですが、ここのもともと入っていたものはどこがおやりになったのかなと。同じなのか違うのかということだけお聞かせいただきたいということ、とりあえずそれを。","respondent":"阿部経理課長","answer":"申し上げますと、先ほど３ページの(1)(2)という平成１９年度にやりましたけれども、これも制限付き一般競争入札で行いましたけれども、これについても東芝ライテックは当然そういう能力はございましたけれども、参加はしてございません。","id":"exchange-047"},{"speaker":"土井委員","kind":"質問","question":"今のお話、もともとライテック、品川区内といっても、そこがもともと本社だったので、そういう因縁をお感じになってなったのかなという気がしたものですから、伺ったんです。たしか東急建設だったか、東芝の建設関係で、そういうことでお入りになりたかったのかなという気がしておりますが、何かありますか。","respondent":"阿部経理課長","answer":"今回の件で、東芝ライテックの担当者に話を聞きました。前回、今申し上げた(1)(2)につきましては、東芝ライテックのほうがそういう入札があるというのを知らなかったということだそうです。","id":"exchange-048"},{"speaker":"南委員","kind":"質問","question":"予定価格が１億９,０００万余、入札価格が４６％で１,８００万余、東芝だからこれだけの予定価格を半分以上下回っても落札するというのは、ある程度東芝の事業実績、先ほど条件でおっしゃっていましたけれども、そういう事業実績があるというところを見て落札したと、そのことはわからなくもないし、税金ですからできるだけ安く使っていくというのは当然のことだと思うんですけれども、それにしても。","respondent":"阿部経理課長","answer":"その結果は、先ほども申し上げましたけれども東芝ライテックは照明器具のトップメーカーですので、十分工事内容については仕様書どおり施工すると、これは当然のことですけれども、そういう回答がありましたので、私どもとしてはそういうふうに受けとめております。","id":"exchange-049"},{"speaker":"南委員","kind":"質問","question":"だれでも、素人でもそういうふうに念押しするというのは当然のことだと思いますし、当たり前なんだろうなと思うんですけれども、東芝といえば業界ではかなりいいところだと、こういう照明器具についてはもちろんそうだと思うので、製品そのものも一定程度のものが期待されると思うんですけれども、やっぱり最新鋭のものというか、そういうモデルじゃなくて。","respondent":"阿部経理課長","answer":"私どもはちゃんと仕様をつくっておりますので、その仕様のとおりやるですので、心配はしておりません。","id":"exchange-050"},{"speaker":"須貝委員","kind":"質問","question":"同じ質問、かぶっちゃうので質問はしませんが、実際にこれだけ安く入札されたということはほんとうに驚きだと思います。１つお聞きしたいのが、今後も区民が大ホールを利用すると思うのですが、その利用に対して何か支障になるとか、ある期間使えないとか、そういうことはもうないというふうに考えていてよろしいんでしょうか。","respondent":"阿部経理課長","answer":"今回のは大ホールの照明ですので、大ホールに入って工事をしなければならない部分があります。そういう関係で、来年の２月１日から３月１７日までの間、これは既に貸し出しを禁止しているというように聞いております。","id":"exchange-051"},{"speaker":"須貝委員","kind":"質問・要望","question":"それはかかっちゃうということなのでしょうが、現在、いろいろな工事機器もあると思いますので、できるだけ期間は短縮してできるように、業者のほうにも協力をお願いしたいと思いますので、その辺は区のほうからも業者のほうに言っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-052"}]},{"id":"topic-06","title":"６番目、第８７号議案、目黒川右岸低地部排水施設整備工事その４の２請負契約","agenda":"６番目、第８７号議案、目黒川右岸低地部排水施設整備工事その４の２請負契約","exchanges":[{"speaker":"林委員","kind":"質問","question":"７ページの地図でお聞きします。下に工程が書いてあるんだけど、この工事の最終というのは、その４の幾つまでとか、数字であらわしているとすれば、幾つまで続くというふうに認識しておけばいいんですか。","respondent":"家壽田下水道河川課長","answer":"残りますのは、その５となるかわかりませんけれども、現在、公園を作業基地として借りております。そこの公園復旧。それから、道路も仮設のもので今使っておりますので、その復旧。これが終わりまして、一連のことがすべて完了ということになります。","id":"exchange-053"},{"speaker":"林委員","kind":"質問","question":"そうすると、鮫洲幹線への接続は、この工事が終わればでき上がって、いわゆる五反田近辺の大雨とか台風とか、そういったものの被害は、品川区が大きい声で言っていた「これができ上がれば」というものができ上がると考えていいんですか。","respondent":"家壽田下水道河川課長","answer":"平成２３年度にポンプ所ができた暁には、すべて目黒川のものをこのポンプ所の排水に切りかえるですので、その時点では、当初から申し上げていたような５０ミリの雨が降ってもこの地区は浸水被害が起こらなくなるということが実現いたします。","id":"exchange-054"},{"speaker":"林委員","kind":"質問","question":"そうすると、これができ上がって、およそ２年後、平成２１年度、品川区にとってはどのぐらいの利というか、下水道治水と呼んでいいのかどうかわかりませんけれども、それは我々はどのぐらいの想定をしていいわけですか。","respondent":"家壽田下水道河川課長","answer":"ただ、ためるものですので、満タンになってしまいますと効果がゼロになってしまいますので、そういう意味での対応は当面できませんが、かなりの効果が暫定的な期間で期待できるです。","id":"exchange-055"},{"speaker":"林委員","kind":"質問","question":"そうすると、町の人に、これができると従来よりも１０ミリから１５ミリぐらい強く降っても落ちついていてくださいねというような話でこの工事を見守っていけばいいのでしょうか。","respondent":"家壽田下水道河川課長","answer":"委員ご指摘のとおりです。","id":"exchange-056"},{"speaker":"林委員","kind":"質問","question":"さっき言われていた戸越幹線、鮫洲幹線、全体的な下水整備というか、幹線整備ができ上がるというのはいつごろになるんでしょうか。工事とは直接関係ないので申しわけないけれども。","respondent":"家壽田下水道河川課長","answer":"戸越銀座のあたりでも、現在、受託事業を行っておりまして、これは貯留管をつくっておりますが、これが平成２２年度完成予定ですので、平成２３年３月ぐらいに一応できるような形で今考えています。","id":"exchange-057"},{"speaker":"林委員","kind":"質問・要望","question":"今日、午前中、組織の改正の話をして、まちづくりの頭に「防災」という冠がついた組織になるそうですから、いつごろまでに下水道が整備されて、特に地形によって安心できる地形と、雨が降るたびに心配しなきゃいけない地形とそれぞれ違うと思うので、例えば平成３０年になればすべての幹線ができ上がって、品川においては、最近は１００ミリを超すというのもあるけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-058"},{"speaker":"土井委員","kind":"意見","question":"ちょっと聞かせてください。今のこの工事の図面を見ると、今までのそういうようなもの、以前のときは相当深いところに工事がされていて、今度は浅いところにパイプがつくと。というのは、そういうのがどうしても設備的にいろいろありますので。","respondent":"家壽田下水道河川課長","answer":"ですので、雨が降る前には空にするというところですので、青いところでたまった水につきましては、今回の工事でポンプも設置いたしますので、そのポンプによってくみ上げるという形で考えております。","id":"exchange-059"}]},{"id":"topic-07","title":"２０年請願第２９号、東京電子自治体共同運営電子調達サービスにおける入札参加資格審査申請の行政書士用電子証明書による代理申請システムの構築及び行政書士用電子証明書","agenda":"２０年請願第２９号、東京電子自治体共同運営電子調達サービスにおける入札参加資格審査申請の行政書士用電子証明書による代理申請システムの構築及び行政書士用電子証明書","exchanges":[{"speaker":"土井委員","kind":"質問","question":"そういう皆さんが事業主にかわっていろいろやらなければならない。こういうふうに問題提起されたらあるのか、それとも率先していろいろ議論されていて、今こういう状態にあるということなのか、そしてその中で品川区が、企画部長ですか、ご参加になるようですけれども、例えば協議体はあっても、１回も開かれなかったら、会があるだけで中身がないので、それはどういう形になっているのか。","respondent":"原情報システム課長","answer":"このシステムについては、先ほど委員がおっしゃいましたように、行政書士はこれを業としているわけですから、そういった中で、一番最初からそのシステムに盛り込まれていれば一番よかったと思いますけれども、そういった意見等々をいただきながら。","id":"exchange-060"},{"speaker":"土井委員","kind":"質問","question":"この共同運営の機構が今のような新たなことを提起されている、あるいはみずから提起をして決めていくこの仕組みが、今どう動いているのか。話し合うテーブルはあるけれども、１回もだれもついたことがないというのではあれなので、どういう形で今、議論されているんですか。","respondent":"原情報システム課長","answer":"そういったところで、まずは課長級の中でやろうということで、これも２分の１の賛成の問題がありますけれども、それでやろうという話になりましたら、今度それを先ほどの総会のほうに上げて、この総会は規約では年１回ですけれども、必要に応じて実施するということで。","id":"exchange-061"},{"speaker":"土井委員","kind":"質問","question":"まさしくそういうことであれば、要するにこれは実務者がどれだけ先にちゃんと進むかがポイントで、それを一定の検証をして総会等で決めていくということになるんでしょうから、ぜひ前向きに取り組んでいただくようにお願いしたいし、早速明日ということですから、そういうものが早く決定されていくようにご尽力いただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-062"},{"speaker":"須貝委員","kind":"質問","question":"これは民間企業でも、ゼネコンやマンション業者でも、そこまで細かい資料を出せということを言われてきている状況の中で、例えば表の門を通ったとしても、今度その後というのもまた大変なものが中小零細企業で出てくるわけですが、とりあえずその辺についてのお考えと、また今回こういうことをすることによって、門戸を広げるわけですが、課題等、問題点は出ないのかどうか、その辺。","respondent":"原情報システム課長","answer":"それから今回の認証のところですけれども、入札そのものに対してというよりは、その前の資格審査あるいは変更といったところを、本来は事業者が登録したり変更したりという形なんですけれども、パソコンを使っての操作になりますので。","id":"exchange-063"},{"speaker":"須貝委員","kind":"質問","question":"ということは、申請するときに、パソコン入力が今だと難しいということが前提であると思うんですが、そのシステムをより簡単にするように持っていくというのも１つの手法だと思うんですね。そちらのほうは何か改善というか、取組みというのは出ているんでしょうか。","respondent":"原情報システム課長","answer":"パソコンのところだけ強調したような形になった形になって大変恐縮ですけれども、やはり代理というところが行政書士がそれを業として引用して、受託をしてという、そういうそもそも紙の時代からそういう形でなってありますので、そこをパソコンに置きかえてというところですので。","id":"exchange-064"},{"speaker":"南委員","kind":"質問・要望","question":"代理申請というのを今までは想定していなかったというさっきの説明なんですけれども、改めて利便性がよくなるという点では、そういう方向に進めていくことは大事かなと思うんですけれども、代理申請を想定していなかったというそもそもの区の、この電子自治体のサービスを実施したときの、想定しなかったそこはどうだったのかというのを改めて教えていただきたい。","respondent":"原情報システム課長","answer":"品川区が想定していたとかしていないということではございませんで、まずこのシステムは、先ほど言いました５６の市区町村がどういう仕様でどういうものをつくっていくのかという、そういったものを、当然経費もそこに発生してまいりますので。","id":"exchange-065"},{"speaker":"南委員","kind":"質問","question":"そうすると、将来的に実施していく中で、代理申請ができるようにしていく、サービスの範囲を広げていくということについては、当時は入れなかったけれども、大いに想定し得ることだということで見ていたということでいいんですか。","respondent":"原情報システム課長","answer":"やはり今、ＩＴのこういった時代になっておりまして、パソコンとかネットワークとか、そういったものが前と比べましてさらにそういったものを１つのツールとして上手に使ってということもありますし、いろいろ使っていきますと件数も増えてきたり。","id":"exchange-066"},{"speaker":"南委員","kind":"質問・要望","question":"確認なんですけれども、冒頭の説明で全部書き切れなかったので、３６業務を今実施しているというお話だった。数字はちょっと正確じゃないかもしれないけれども、３６全部でなくてもいいんですけれども、重立った区民生活のところで、直接かかわる部分でいいんですけれども、教えていただきたいと思います。","respondent":"原情報システム課長","answer":"これをインターネットを使って申請をする、そういったものが１つあります。それから乳がん検診の関係、電気式生ごみ処理機の助成申し込み、家庭用消火器の購入、薬剤詰め替えあっせん申し込み等々を含めて、３６の手続を現状でやっているです。","id":"exchange-067"},{"speaker":"林委員","kind":"質問","question":"一番最初の話から入りたいんですけれども、ここに書かれているように、５６市区町村の共同運営協議会という組織があって、ここに品川区も出ていて、こういう電子調達、電子申請、代理申請というような書かれていることを、品川区はこれから電子自治体とかいうような取組みをしていくときに、進めたいなと思っているんですか。","respondent":"原情報システム課長","answer":"品川区の考え方ですけれども、品川区のほうでは、コンピューター化を進めるというよりは、コンピューターは１つのツールですので、それを使いながら行政サービス、区民サービス、行政改革といったところで上手に使っていこうという考え方でこの間、実施してきているところです。","id":"exchange-068"},{"speaker":"林委員","kind":"質問","question":"そうすると、これから各自治体、進んでいるところはいろいろなものを取り入れて、横須賀市あたりではやっているように聞いておりますけれども、電子というものに対する、これから取組む品川区としては、こういうものが協議体の中で話し合われて使っていこうよというときは、これを使うと決めたわけじゃないけれども、使っていけると思っていると考えていいですか。","respondent":"原情報システム課長","answer":"それぞれのサービスの中でどういうふうに参加していくかというのは考えていかなちゃいけないと思いますけれども、ことこの今回の電子申請あるいは電子調達といったところについては、区で独自でシステムを設けて何かするよりは、東京都という全体の中でとらえて。","id":"exchange-069"},{"speaker":"林委員","kind":"質問・要望","question":"もう１つ別な見方というか、別の考え方でいくと、この運営協議会というものがあって、これに限らずいろいろなものを協議しているんだろうと思うんですけれども、そこの協議会の流れというか、考え方の１つの道筋がわかれば教えていただきたいのと、それから、例えばこれを採択して、立ち上げていって、もっと新しいのがあるんだよ、もっといいのがあるんだよというふうになっちゃうと。","respondent":"原情報システム課長","answer":"そういった意味では、今回のこの電子自治体共同運営協議会については、電子申請と電子調達の部分に限ってそういうシステムを構築していくということですから、それを品川区が独自で考えたときと、あるいはこれに乗っかっていったときを考えたときに。","id":"exchange-070"},{"speaker":"林委員","kind":"質問","question":"もう１つ情報として教えてほしいのは、この請願を出された方は、東京都行政書士会の品川支部の支部長ですよね。","respondent":"原情報システム課長","answer":"他の自治体での請願の動きですけれども、正確な数字は別にしまして、ほかの自治体５６の中でも、今、二十幾つの団体がこういった請願、陳情、あるいは区長、市長への要望という形で、やはり使っている中で、どうしても業としてやっている中で。","id":"exchange-071"},{"speaker":"林委員","kind":"意見","question":"請願の要旨の１番、２番とも、最後の言葉が「働きかけてください」という言葉で、意見書を出してくださいとか、いろいろな請願があるんだけれども、働きかけてくださいということになると、あまり何をというふうになるので、運営会議でいろいろなことを言ってもらうというのが働きかけるという初歩的な話になるんだろう思いますけどね。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-072"},{"speaker":"土井委員","kind":"質問","question":"私が伺ったところによりますと、この協議会には区も当事者として一応入っているわけなので、働きかけというのでいいのではないかとご判断されたと伺っております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-073"}]},{"id":"topic-08","title":"２番目の荏原西地区小中一貫校新築工事の進捗状況","agenda":"２番目の荏原西地区小中一貫校新築工事の進捗状況","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"文教委員会に所属していたときに、この荏原西地区一貫校の地盤が軟弱地盤だということがわかって、そして幼保一体施設を入れる予定が、設計を変更したという経緯があったんですけれども、そのときに当然、地盤の調査と同時に土壌の調査もしたのかなと思っていたんですけれども、結果的にそれはしていなかったということなのかどうかと、していなければ当然わからないのかもしれないんですけれども。","respondent":"宍戸施設担当課長","answer":"まさに運ぶ土についての分析をしなければならないということで、今回、こういうことがありましたので、いろいろ施工業者に民間の場合はどうなんだと聞いたんですけれども、通常の施工工程の中で、運ぶ場所や何かがある程度見込みがついてきて。","id":"exchange-074"},{"speaker":"南委員","kind":"質問・要望","question":"基準値から比較するとそうでもないということなんですけれども、どの程度の量が出たのかというのもわかれば教えていただきたいのと、数字的には大したことないというお話ですけれども、あまりいたずらに荒立てるということじゃなくて、やっぱり情報は正確に提供して、そしてしっかり判断していただくということが大事なので、そういう点でちょっと伺いたいと思っているんですけれども、その基準で見たときに。","respondent":"宍戸施設担当課長","answer":"それに比べれば本当に小さい数字ですので、全くこのままの状態で考えなくてもいいと考えています。","id":"exchange-075"},{"speaker":"南委員","kind":"質問・要望","question":"砒素についても中毒を起こして致命的な影響が多いとされているんですけれども、体内の摂取は極めて有毒だということで、この地下から出てきたものが体内に取り込まれるなどということはないとは思うんですけれども、それだけの毒物、劇物だという認識に立ってきちんとした処理が求められると思うので、区のほうで調べられる前提として、出てくる物質によって。","respondent":"宍戸施設担当課長","answer":"３番の今後の予定等のところの丸の２つ目です。平成２２年第１回区議会定例会においてとありますけれども、これは平成２１年の誤りですので、訂正させていただきたいと思います。ご質問に移ります。","id":"exchange-076"},{"speaker":"南委員","kind":"確認","question":"港湾部での埋め立てというと、例えば中央防波堤に持ち込んで、あそこで埋立処分をするということでいいわけですよね。その前にセメントで固めて固化をして埋め立てるということで考えて、今の説明はそういうふうに理解していいのかなと思ったんですけれども、確認を。","respondent":"宍戸施設担当課長","answer":"無害化してセメント原料化するものはそういう処理なんですけれども、港湾部での埋立土につきましては、そのまま埋立土としていいと。１０倍ぐらいの基準なんですね。それでやっていいですよという基準の中におさまっておりますので、その方向で考えております。","id":"exchange-077"},{"speaker":"南委員","kind":"質問・要望","question":"このことは、例えば学校関係者とかにはどういうふうにお知らせ、するのかしないのかも含めて、どういうふうにやろうとしているのか、検討されている中身を教えていただきたいと思います。","respondent":"宍戸施設担当課長","answer":"この委員会終了後、教育委員会が中心になってということになると思いますけれども、保護者等にはできるだけ早い時期に周知をすると聞いてあります。どのような方法にするかということはまでは聞いてございませんが、なるべく早い時期に周知を図ると聞いてあります。","id":"exchange-078"},{"speaker":"金野委員","kind":"質問","question":"今回の想定外のことであるということですが、今後、小中一貫校でこういう建設工事が行われていく中で、これを前提としてというか、今後のこういったことまでしていくことが必要であるかなと思うんですけれども、ここで発言することだったかどうかあれですけれども、今回のことを含めて、これから行う八潮、品川、そして荏原東のほうと、こういったことも今後も含めて必要なことであるかなと思うので。","respondent":"宍戸施設担当課長","answer":"今、この土壌について事前に調べておくと、そういうほうがあらかじめいろいろ予定が立っていいんじゃないかというご質問かと思うんですけれども、例えば品川一貫校で土壌を、今、中学校が建っているところを半地下にするんですけれども、そこの土壌について今。","id":"exchange-079"},{"speaker":"林委員","kind":"質問","question":"戸越台のときもそんなような心配の声が上がって、戸越台は古い、古いと言ってはあれだけれども、品川区はいろいろ歴史上の暮らしていた人たちがいたりして、心配は心配していた。平塚中の校庭の土なのか、体育館に近いほうの土なのか、どの辺の土にこういうのがまじっていたということになって、今、調査をやりましょうということになったのか、ちょっとそれを教えてください。","respondent":"宍戸施設担当課長","answer":"体育館が今回、地下になります。その体育館を地下にするには、そこの土を掘削して運び出さなければいけないんですね。ですから、一番最初、体育館の予定地のほぼ中央のところでボーリング調査をいたしまして、地層ごとに科学的な分析調査をしたわけです。","id":"exchange-080"},{"speaker":"林委員","kind":"質問","question":"非常にうがった見方をすると、保育園・幼稚園がつくれなくなった。一番最初は予定してんだけれども、つくれなくなった。そのときに既にこういうことはわかっていたんじゃないの。幼稚園・保育園は無理だという話に進んだんじゃないのかなと思うんだけれども、いかがですか。","respondent":"宍戸施設担当課長","answer":"これがわかったのは本当に１１月に入ってからでございまして、本当に地下の土をどこに運ぼうかと、工事の要件に基づいて調査をした結果ですので、委員おっしゃったようなことはございません。","id":"exchange-081"},{"speaker":"林委員","kind":"質問","question":"問題はこの工期が４カ月、１学期分ずれちゃう。子どもたちというか、学校にとっては非常に痛いこの４カ月になるわけだけど、この辺についてはまだこれからですか。学校あるいは教育委員会等が話をしていくのは。","respondent":"市岡総務部長","answer":"今ご指摘いただいた点は、今回こういう問題が生じた直後から教育委員会と協議をしてまいりまして、今日、文教委員会の報告の内容になろうかと思うんですが、学校関係者、保護者、それから町会等地域の方々にもご報告することになっていますが、結論から言うと、開校自体は４月。","id":"exchange-082"},{"speaker":"林委員","kind":"意見","question":"工期の問題をそれぞれが納得をしてもらって始めるんだけど、そのときに話す言葉の中に、３カ月、４カ月というのは、万が一歴史上のもの、あるいは今回の自然のもの、そういうことが出た場合、やむを得ない場合は変更するんだというのを、学校側あるいは地域の人たちに一応話すべきじゃないのかな。当然出てくるものだと考えているのかどうかわからないけど、話しておくほうが親切なのかなという気がするけど。","respondent":"宍戸施設担当課長","answer":"なるべくそういうことがないように、今後の工事もぜひ進めたいと考えていますけれども、不測の事態に備えてどうするかというのは、これからも教育委員会と連携を図って、話し合いながら進めていきたいと思います。","id":"exchange-083"},{"speaker":"土井委員","kind":"質問・要望","question":"今のお話を伺っていますと、いつの時点だかわかりませんが、何百年前のところとか、地層がわかりませんけれども、その当時、そういうものがそこに堆積をする何かがあったんだなということ、これまた別な科学的な興味があるところなんですけれども、それはとりあえずこっちへ置きまして、たまたまそういうことでいろいろある。当然のことながら。だから、それをどう処理されたかの問題なんだと思います。","respondent":"宍戸施設担当課長","answer":"今回、内陸部での埋立地に受け入れてもらう予定ということで、非常に厳しい環境基準に基づいて処理しておりますけれども、先ほどもちょっと申し上げましたけれども、第２溶出基準というもう１つの基準があるようでございまして、それは今回。","id":"exchange-084"},{"speaker":"須貝委員","kind":"質問・要望","question":"もう１回、確認なんですが、この件がわかったというのは１１月中ということでいいんでしょうか。こういうふうに報告して、きちんと今後処理しますということで品川区の姿勢というのが明確に伝わると思いますので、今後についてもそのような方向できちっと対応していただきたいと思います。わかったのが１１月のいつごろになったのか、それだけをもう１回確認させてください。","respondent":"宍戸施設担当課長","answer":"今後もいろいろこういう状況の変化が生じた場合には、速やかに報告してまいりたいと考えております。","id":"exchange-085"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/917943?Template=document&Id=1802#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":64856,"voices":234}},{"id":"h20-20081126-6","meetingId":"h20-cm11","date":"2008年11月26日","dateIso":"2008-11-26","committee":"区民委員会","time":"午前１０時０２分～午後０時０５分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を28件抜き出しています。","topics":[{"id":"topic-01","title":"の「３,０００店舗のお宝発見・つまみ食いウォーク─品川区の商店街・東急沿線いいもの巡り─について」","agenda":"の「３,０００店舗のお宝発見・つまみ食いウォーク─品川区の商店街・東急沿線いいもの巡り─について」","exchanges":[{"speaker":"稲川委員","kind":"質問","question":"何でこれは３,０００店舗なのかということ。最後に、これは第３回ですけれども、今後第４回、第５回に向けて、何をもってこれをずっと続けていくのかを教えてください。","respondent":"金子産業振興課長","answer":"そういう意味では、先ほど申し上げませんでしたけれども、区外からの参加者も約７割を数えておりますし、区外の方へのＰＲもできているということから、今後ともこの商店街の魅力をアピールしていくためには、恒例になっていることもありますし。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問・要望","question":"参加者の方の顔ぶれについて幾つかご説明があったんですが、改めてどういう方が、７割が区外ということと、あとリピーターの方が何人ということもお話があったかと思いますけれども、もうちょっとお伺いしたいのと、やっぱりこういうイベントを通して、ふだんなかなか商店街で買い物をする経験がない方もここで経験されて。","respondent":"金子産業振興課長","answer":"幾つかご質問をいただきましたけれども、前段のほうはちょっとわからなかったんですけれども、後半のほうから答えていきたいと思います。過去２回実施しまして、それぞれゴールのところでアンケートをとらせていただいております。","id":"exchange-002"},{"speaker":"安藤委員","kind":"確認","question":"多くなってすみません、最後なんですが、将来のお話もありましたけれども、このチラシを見ると、申し込み先が青葉区新石川の東急の事務所かなと思うんですが、かなり大きなイベントで、やってみるとすごく大変なんだというお話がありましたが、中心になって、主にここで頑張っていらっしゃる主体というのはどこら辺になるのかなというのをもう少し知りたいなと思ったのと。","respondent":"金子産業振興課長","answer":"それがベースになって、今、商店街とのかかわりで、いろいろ立正大学の授業の一環として、商店街とかかわりを持っていただいているところなんですけれども、このつまみ食いウォークに関しては、イベントとして参加したいという意向を向こうで表明されたので。","id":"exchange-003"},{"speaker":"安藤委員","kind":"質問・要望","question":"アンケートをとった内容をぜひ、これは来年以降もぜひ続けてやったほうがいいんじゃないか、続けてほしいという要望なんです、個人的には。なので、ぜひ委員会の中といいますか、この事業の内容をよく理解するという点でも、今回もぜひ、断片でも出して、資料として提供していただければよかったと思いますので、今後ぜひお願いできればと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"渡部委員","kind":"質問","question":"実は１つ気になっていたことがありまして、やはりふだん、商店街、住宅街のまち中の生活道路を歩かれる中で、ボランティアの方でしょうか、道案内の方が立っていらっしゃったんですけれども、いろいろな方が歩いて、当然車も走っているという状況があり、商店街は通行止めなんですけれども、それ以外の歩道のところは車が通るところがあったりしていまして、一つまた町会の方とかとも結構話をして。","respondent":"金子産業振興課長","answer":"とっておかれた方が、ゴール地点の近くでも、やっぱりそこをスタートされた方がいらっしゃるから、そこでもあまり試食がないということで、今回は受付を３カ所にして、スタート地点の近くがなくなるのは、どうしても仕方のないことなので、どこかにはあるような格好にというのを。","id":"exchange-005"},{"speaker":"渡部委員","kind":"質問","question":"交通整理といいましょうか、そのようなボランティアというのはどこから、どういう方に依頼されているのか、やはりトイレはどこかしらとか、どうやって歩いたらいいのかしらという問い合わせ、地元の方が多いのか、そうじゃないのかというのと、何名規模ぐらいなのかというのをちょっと教えていただけますでしょうか。","respondent":"金子産業振興課長","answer":"なれていませんので、案内もなかなか難しい部分があったということがあります。昨年の２回目なんですけれども、日本ウォーキング協会というところに委託しています。","id":"exchange-006"},{"speaker":"渡部委員","kind":"質問","question":"交通安全の方は何人ぐらいの規模でやっているんですか。","respondent":"金子産業振興課長","answer":"今年は、全体で立っているところで３４カ所あるんですけれども、ウォーキング協会の方が大体１８名ぐらいと聞いております。","id":"exchange-007"},{"speaker":"渡部委員","kind":"質問・要望","question":"もう３度目ということで、なれてはいると思いますし、皆さん、楽しんでいる風景も見ました。ともかく事故だけが大変だと思いますので、そのようなことがないように、あとはお天気になって、ぜひまた成功させていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"宮崎副委員長","kind":"質問","question":"１点、事業費というか、お金、経費がどういうふうになっているのかというのを伺いたいんですけれども、全体で事業費というのは幾らぐらいかかっているのかということと、参加費は無料なんですけれども、例えば、こういうチラシだとか、いろいろお金がかかっていると思うんですけれども、それはだれがどういうふうに負担しているのか、主催、共催とありますけれども、それぞれで分けているのかどうなのか。","respondent":"金子産業振興課長","answer":"観光協会がすべて取り仕切っているので、そこから聞いている範囲ということになりますけれども、概算で、総経費で、予備費も含めているとは聞いておりますが、大体３００万円ほどかかっております。うち、１７０万円ほどが区の委託費の部分から出ている。","id":"exchange-009"}]},{"id":"topic-02","title":"の「平成２０年しながわの一番店発見プロジェクトの進捗状況について」","agenda":"の「平成２０年しながわの一番店発見プロジェクトの進捗状況について」","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"毎年４０店舗ずつ認定しているということなんですけれども、３年間で１２０店舗ということなんですが、これから毎年ずっとやっていくと、かなりの店舗があると思うんですけれども、どれくらいまでやっていくのかというお考えといいますか、もし、そういうものがあれば、今の時点のお考えをお伺いしたいのと、あと最初にエントリー店が１８７店ということだったんですが、わかればでいいんですけれども。","respondent":"金子産業振興課長","answer":"一番店発見プロジェクトですけれども、何年続けるかということですが、年次の実施に関しては、状況を見ながら、また商店街連合会とも相談しながら、実施していきたいと考えていますが、長期基本計画の中でも、これは一定程度続けようという判断をしているところであります。","id":"exchange-010"},{"speaker":"安藤委員","kind":"質問","question":"うまく言えないかもしれないんですけれども、(1)(2)で、バリューアドということで、魅力的な店を発見しようということと、あと２番目でビジネススクールということで、そういう店になれるような個店を育てていこうということだと思うんですけれども、昨今のこの大変厳しい経済状態の中で、個々のお店の魅力という、ましてや商店街の魅力をつくっていくということはすごく大事なことだと思うんですが。","respondent":"金子産業振興課長","answer":"商店街全体の取り組みというお尋ねなんですけれども、商店街として見たときには、やはり既存の事業、さまざまなメニューをそろえておりますし、ハード的な装飾等をはじめとした助成、あるいはイベントの助成等々を実施してきておりますし、また。","id":"exchange-011"},{"speaker":"稲川委員","kind":"質問","question":"例えば、先ほどほかの委員からもありました、これは１０回がいいのか、５回で終わるのかわからないですけれども、最終的には、こういうふうにちゃんとした冊子になっていますけれども、ちゃんとした観光ガイドみたいな形で１つの本にするのか、その辺をちょっとお伺いします。","respondent":"金子産業振興課長","answer":"特に品川区の商店街というのは、全国的にもさまざまな取り組みをしていて、いい店がたくさんありますので、そういう意味では、観光資源ともなり得ますので、商業と観光というのは本当にきっちりと線引きできない、密接に関連したものですので、私どもとしましては、観光協会。","id":"exchange-012"},{"speaker":"稲川委員","kind":"質問・要望","question":"先ほどの追跡なんですけれども、やはりマイスター、今回４０店舗ずつということなんですけれども、要は、落ちたという人もいるのかもしれないですけれども、だれでもかれでも、申し込めば、票が入れば、受賞できてしまうというようなイメージが、地域を回っていて、それは僕のイメージですよ、感じるんですけれども、マイスターというのは選ばれたあれなので、非常に価値のあるもの。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"若林委員","kind":"質問・要望","question":"簡単に２点、モニター調査が、５５名がそれぞれに店舗に行ったとして、それの、全店舗数の内容、どんなことを、区民と中小企業診断士で随分見る目に落差が出てくるんですが、そこら辺をちょっと教えていただきたいんですけれども、これは全体的に、先ほどのつまみ食いと地域がダブっている商店街の方もいらっしゃると思うんですが、そこら辺、ある意味では、当然積極的に参加するとか、しないとか。","respondent":"金子産業振興課長","answer":"つまみ食いウォークとの関連ですけれども、つまみ食いウォークはどうしても食品関係が多い参加になって、それ以外のお店というのは、割引というもので幾つか参加していただきますけれども、どうしても参加者の嗜好性、それから、つまみ食いウォークと銘打ってしまっているので。","id":"exchange-014"},{"speaker":"渡部委員","kind":"質問・要望","question":"２点伺います。この投票総数で、２万３,３２６名というのは、非常に多い数字だなと感じています。もし、この辺の内訳が、どこでどういう投票があったのかというのがわかれば、教えていただきたいのと、もし、もう１点わかるとすれば、区外の方の投票がどれぐらいあったのかというのをまず教えてください。それと、実はおとといこの冊子をもらったときに、これを見て、みんなすごくいい顔をしているんです。","respondent":"金子産業振興課長","answer":"ただ、今の段階では、そういうネット上のものよりも、紙媒体のほうが効果があるというか、好まれるという実情かなとも思っておりますので、そういった状況を見ながら今後検討していきたいと考えています。","id":"exchange-015"}]},{"id":"topic-03","title":"の「新製品・新技術クラスターフェアについて」","agenda":"の「新製品・新技術クラスターフェアについて」","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"京浜工業地帯の４自治体による連携ということなんですが、今まで自治体を越えて、こういう京浜工業地帯というカテゴリーで、ほかの４自治体と連携してきたという事業というのは、ほかにどのような、これが初めてなのか、今までもかなりやってきたのか、ほかにどういうものがあるかなど、そこら辺のありようを伺いたいと思います。","respondent":"金子産業振興課長","answer":"それからもう１つ別の事業で、産業のまちネットワーク推進協議会というのがありまして、これは東日本ですから、北海道まで含めまして、ものづくりの集積した自治体が集まって、さまざまな意見交換会、それから、研修等々を共同で実施する連携の場とするものですけれども。","id":"exchange-016"},{"speaker":"宮崎副委員長","kind":"質問","question":"何点か伺いますけれども、こういうのを開催するというのは、情報発信というか、それはどういうふうに、こういうフェアを開催しますという、どういうふうに、どこら辺までお知らせが行くものなのかというのが１点と、あとその４自治体それぞれ６社ずつなんですけれども、これは新製品開発助成対象の認定を受けた企業ということなんですけれども、もっとあると思うんですけれども、この企業を選んで。","respondent":"金子産業振興課長","answer":"情報の周知ですけれども、４地域ありますので、他の地域に関してはそれぞれの自治体ないし財団法人、ＮＰＯが実施しております。品川区に関しましては、区内の中小企業、また大手企業に関しましても、こういう催しがあるということで、お知らせをして参加を要請しています。","id":"exchange-017"},{"speaker":"宮崎副委員長","kind":"意見","question":"今こういう経済状況なので、意欲のあるところはもっと出てくるのかなと思うんですけれども、そこら辺の、今回は６社ということで限っていますけれども、この前の東大阪だとか、常設なんですけれども、かなり多数の企業の展示なんかもあったんですけれども、こういう状況だからこそ、より広く紹介できればと思うんです。今回はこれでだと思うんですけれども、ちょっと検討いただければなと考えています。","respondent":"金子産業振興課長","answer":"ちょっと１つ抜けましたけれども、関東経済産業局のほうもＰＲをしていただいていて、これは細かいところまでは掌握していないんですけれども、この４自治体に限らず、お知らせはいただいているとは聞いてあります。","id":"exchange-018"}]},{"id":"topic-04","title":"の「国民健康保険療養給付費負担金に関する会計検査院の指摘について」","agenda":"の「国民健康保険療養給付費負担金に関する会計検査院の指摘について」","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"最後のご説明のところで、４番のところなんですけれども、進行管理をきちんとやって、かなり事務の過密状態というか、そういうお話もあったと思うんですけれども、実際事務作業というのは今、どのぐらい過密になっているのかというのをもう少しそこのところ、現状はどうなっているかというのを４番目の絡みでお伺いしたいと思います。","respondent":"本城国保年金課長","answer":"過密状態と申しますか、実際に作業をやりましたのは平成１９年度のことですけれども、そのときも医療制度改革とかもありましたけれども、ただ、もろもろ通常の業務の中でやって、その進捗管理がおくれてしまったことで、事務処理がおくれたことを、おくれた段階に応じて、係長。","id":"exchange-019"},{"speaker":"宮崎副委員長","kind":"質問","question":"１点聞きたいのは、今回会計検査院が発見したということなんですけれども、何でわかったのかというのが、一番よくわからないところなんですけれども、今、課長は担当のところの課長を含めて、そういう能力を高めていかなければいけないというお話だったと思うんですけれども、会計検査院の担当者が非常に能力が高かったのか、それとも、こういうチェックの仕方をやっているから見つかったとか。","respondent":"本城国保年金課長","answer":"今回会計検査院のほうで見つかった経緯としては、私どもが伺っているのは、会計検査院としては、ミスを発見するソフトが用意されているということで、関連データを全部入力すると、どこかに誤りがあるという、それで当たりをつけられるようなものがあるということで。","id":"exchange-020"},{"speaker":"宮崎副委員長","kind":"意見","question":"そのソフトがどんなソフトなのかというのはよくわからないですけれども、例えば、そういうことでミスがなくなるというのであれば、そういうのは考えていく必要があるんじゃないかと思うんです。やっぱり人間の能力というのはどうしても限界が、私もあると思うし、自分もそう思うんですけれども、それをいろいろな機械等で補えるのであれば、考えてもいいのかなと感じました。それは感想です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-021"},{"speaker":"本多委員","kind":"質問・要望","question":"少し確認だけさせていただきたいんですけれども、２番目の経緯のところで、６,３１３万円余を返還すべきであったというのが、これが何年度の何月ぐらいに返還すべきものだったのかを教えていただきたいんですけれども。","respondent":"本城国保年金課長","answer":"療養給付費負担金の仕組みですが、今回で言えば、平成１８年度、実績が年度いっぱいで確定しまして、ただ、当初概算でもらっていますので、平成１８年度明けの、具体的には平成１９年７月の時点で、確定値ということで、厚生労働省に報告することになります。","id":"exchange-022"},{"speaker":"本多委員","kind":"質問","question":"今後の対応ということで、後日、国から請求が来て、平成２０年度内に補正で返還という作業に入ると思うんですけれども、それに対して、補正でその数字を返還ということで、ほかの今までの、それに関連する資料という修正は特になくて、その補正で全部、精算ということでいいんでしょうか。","respondent":"本城国保年金課長","answer":"今回につきましては、今までの平成１９年度の手続で多く受給したものについては、もううちのほうに入ったことで、確定している会計処理になっておりますので、今後はそれに基づいた返還という手続のみで行うという形で、今までの土台の上に立って。","id":"exchange-023"},{"speaker":"本多委員","kind":"質問・要望","question":"１つだけ、先ほども出ておりましたけれども、そういった資料というんでしょうか、都に出すものと国に出すものとのフォーマットといいますか、同じものが出せるような仕組みをつくっていただきたいと思います。要望として、終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"}]},{"id":"topic-05","title":"の「地球にやさしいお店発見事業について」","agenda":"の「地球にやさしいお店発見事業について」","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"ホームページなんですが、リンク先といいますか、これは区のホームページにリンクされるのか、区商連のほうと、ホームページを開設された後、どこから見られるようになるのか、単独でつくるわけではないと思うんですが、そこら辺をまず１点お伺いしたいのと、あと、口コミや投稿情報をもとにということなんですが、投稿できるのも、このホームページ上に投稿されるものなのかということが２点目で、あと最後。","respondent":"工藤環境課長","answer":"例えば、お店の中で、打ち水をやっているとか、お店の周りの清掃活動をやっているというところでも、一つ環境にやさしい取り組みをやっているという部分で、ハードルを下げて、店を抽出しているというか、掲載しているところがありますので、そういったところで。","id":"exchange-025"},{"speaker":"安藤委員","kind":"質問・要望","question":"最後なんですけれども、エコアドバイザーのいるお店ということなんですけれども、私、ちょっと勉強不足で申しわけないんですけれども、エコアドバイザーというのはどういう方なのかだけ最後にちょっと教えていただきたいんですけれども。","respondent":"工藤環境課長","answer":"エコアドバイザーがいるお店というものはどういうことかといいますと、例えば、今いろいろと掲載予定なんですけれども、電気屋で、単純に省エネの製品とか、省エネの電球を売るだけではなくて、電気屋ですから、当然知っていなければいけないんですけれども。","id":"exchange-026"},{"speaker":"宮崎副委員長","kind":"質問・要望","question":"地球にやさしいお店発見というので、最初産業振興課のほうかなと思ったら、環境課のほうで、そういう角度からもやるということなんだと思うんですけれども、ちょっと聞きたいのは、業種別としては６種類となっているんですけれども、差し支えなければ、どういうこと、６種類というのをちょっと教えていただければということと、あとはエコアドバイザー、ごみ減量推進店、１０種類程度となっていて。","respondent":"工藤環境課長","answer":"環境にやさしい取り組みで、１０種類程度ということなんですけれども、１０種類といたしましては、何を考えているのかというのは、例えば、すべて申し上げますと、環境にやさしい商品を販売している、レジ袋の削減店、リサイクルの推奨店、ごみ減量推進店、フードマイレージ。","id":"exchange-027"},{"speaker":"宮崎副委員長","kind":"質問・要望","question":"エコアクションというのは、私、ちょっとよくわからなかったので、それがどんな内容かということをお聞かせいただきたいのと、今お話があった、環境課の所管のところが中心になっているかと思うんですけれども、そういう意味では、いろいろ、先ほどの商店街支援というか、商店の支援というか、そういう角度からも連携してできるのかなと思うんです。","respondent":"工藤環境課長","answer":"最後の質問でありますけれども、いろいろと環境にやさしい取り組みというのは、先ほど委員もおっしゃったように、お店の、要は飲食店の視点という部分ですか、そういった部分の視点からというのは、今回の対象の中には入れていないんですけれども。","id":"exchange-028"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/487097?Template=document&Id=2536#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":36348,"voices":90}},{"id":"h20-20081126-7","meetingId":"h20-cm11","date":"2008年11月26日","dateIso":"2008-11-26","committee":"厚生委員会","time":"午前１０時０２分～午後０時３０分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を51件抜き出しています。","topics":[{"id":"topic-01","title":"の１、請願・陳情審査","agenda":"の１、請願・陳情審査","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"ご説明をいただいたんですけれども、請願事項の１点目は、保護者補助金の所得制限の緩和ということで、所得制限のところを伺いたいと思います。","respondent":"小林保育課長","answer":"それから補助金の流れというお求めですけれども、こちらの補助金の開始年度は、保護者補助金が昭和４４年、就園奨励費は昭和４７年ということで、かなり長く維持されている制度ですが、あえて言いますと、大きく転機になったのは、平成８年に保護者補助金の制度にかんがみて。","id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問・要望","question":"所得制限にひっかかってしまう方というか、この制度が受けられない方が１,５８６人保護者補助金のほうでいらっしゃるということなんですけれども、これが受けられない場合の、ここに所得制限の格差を緩和してくださいということなので、公立の幼稚園と比較をしてどのくらい負担が増えているのか、その差を教えていただきたいと思います。公立の保育料との差をもう１回教えてください。","respondent":"小林保育課長","answer":"公立との保育料の負担の状況というのは、園によって、また状況によってまちまちですので、代表的な例ということでご勘弁をいただきたいと思いますが、第１子の基本的な就園奨励費ないしは保護者補助金を受ける場合。","id":"exchange-002"},{"speaker":"飯沼委員","kind":"質問","question":"園によって違うので、受けられていない方のその辺の幅というのか、保育料というか、一番高いところは幾らぐらいかかるんでしょうか。","respondent":"小林保育課長","answer":"平均の保育料ということでしょうか。","id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問","question":"園によって違いがあると思うので、例えば高い園の場合の保育料というのはどのくらい、そこで所得制限がかけられない方がどのくらい負担しているのかなということを知りたいのであって、すいません。そこを教えてください。","respondent":"小林保育課長","answer":"各園の保護者の負担ということかと思いますけれども、保育料は園によって違いますけれども、おおむね平均で月２万６,０００円限度が負担の中心になっていると、それ以外に教材費、あるいはその他の施設の費用等の負担が発生していると聞き及んでおります。","id":"exchange-004"},{"speaker":"飯沼委員","kind":"質問・要望","question":"預かり保育は本当に付加をして、特別のサービス的に考えないとやっていかれないような感じで、かなり赤字の中でやっていらっしゃるというところにおいては、この辺の考えというんですか、若干増えてはいると思うんですけれども、私はまだまだ不十分であると思うんですけれども、その辺のお考えはいかがでしょうか。","respondent":"小林保育課長","answer":"母の会連合会というのは、各園の私立幼稚園の中におられる保護者の方で母の会を組織して、その母の会が各園一緒に動いて事業等をやるということで連合会を組織している、いわば、私立幼稚園に対して幼稚園協会ということで幼稚園が連携しているわけですけれども。","id":"exchange-005"},{"speaker":"飯沼委員","kind":"質問・要望","question":"詳しくありがとうあります。預かり保育のところの都の補助金のところを知らなかったので、どのくらいの金額が出ているのかを教えていただきたいのと、すいません、保育園ＰＴＡのところの予算があったら教えてください。","respondent":"小林保育課長","answer":"それから都の補助金につきましては、今、つかんでおりますのは、私立学校経常費補助金、教育振興事業補助金の中の預かり保育ということで、１,６００万円ほどが、対象としては１８園に支給されていると聞いております。","id":"exchange-006"},{"speaker":"飯沼委員","kind":"意見","question":"わかりました。預かり保育については都の補助金が若干出ているということで、これは助かるなと思うんですけれども、今、幼稚園のところでも、働きに出られるお母さんは増えているので、預かり保育は本当に需要が高くなっているので、ぜひこの辺の補助金も上積みができたらいいなと思って、これは意見です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"},{"speaker":"渡辺委員","kind":"質問","question":"２番目の、今もありました母の会連合会の助成というところで、母の会連合会を含めて、振興費の補助金のところで、ここ数年の予算の増減の経緯を伺いたいのが１点、それはなぜかというと、この請願の趣旨の中ですごく強調されている思いの中で、地域の交流活動、そういった今、近年の社会情勢も踏まえて、この辺の変化というのはだれもが感じている中で、やはり親御さん、保護者の方の情報を得る場。","respondent":"小林保育課長","answer":"それから２点目の保護者の方が連携し、ないしは地域と連携していくことの大切さは委員がご指摘のとおりなんですが、そういった活動に使われる予算といたしましては、正確に把握してございませんが、母の会の活動、あるいは各園での保護者会等の活動、そしてまた昨年来。","id":"exchange-008"},{"speaker":"渡辺委員","kind":"質問・要望","question":"要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"阿部委員","kind":"質問","question":"手短に２点ほど伺います。それが１つです。それから母の会連合会への助成金、今、協会に内包された形であるので、協会への補助金の中から出ているというご説明だったかと思うんですけれども、これは話の順序としては、母の会に対する補助金がないからそうせざるを得ないという状況にあるのではないか、そのように理解したんですが、どのように受けとめていらっしゃいますでしょうか。","respondent":"小林保育課長","answer":"それから母の会の補助金につきましては、母の会単体では独自の事業形成をするにはまだ至っていないと思っておりまして、そういった意味では、協会の中でいろいろな活動をしていく部分につきまして。","id":"exchange-010"},{"speaker":"阿部委員","kind":"質問・要望","question":"それと、母の会単体では補助金の受け手としてどうかということだったと思うんですけれども、むしろこの組織を育てていくという意味でも、いきなり自立して全部自分でやれということではないにせよ、この母の会というものが組織としてさらに力をつけていくためには、項目として、まず母の会に助成金を出すという形で、少しずつ組織としての自立性を高めてもらう、そういう誘導をしていくという、当然。","respondent":"小林保育課長","answer":"それから母の会の育成という点では、保護者と園との協働・連携によって子供を育てていく、そういった意味での連携や地域との連携が大切という意味では、団体の育成ということは今後重視していくべき視点かと考えております。","id":"exchange-011"},{"speaker":"阿部委員","kind":"質問・要望","question":"ただ、特に私立幼稚園は、保育料だけではなくてさまざまな経費がかかってくる、かつ、幼稚園の場合、小さいお子さんを複数抱えたご家庭も多いということで、それに対する補助も既に新設されているところではありますが、やはり所得制限がかかったぎりぎりのところでの格差感ですとか、それから、あと公立では当然ながら所得による保育料の違いがないということなども考えますと、やはり実質的な負担。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"浅野委員","kind":"質問","question":"１番目の保護者補助金の所得制限の緩和について、基本的なところ、私が理解していないところをお伺いしたいと思うんですけれども、所得制限の導入以来、負担の格差が拡大しているという文言ですけれども、導入以前というのはどのような状況だったのか、例えば公立の費用と、あと私立の費用というのはどういう状況だったのかということ、補助の度合いですね、そしてこの所得制限が入ったときに。","respondent":"小林保育課長","answer":"所得制限につきましては、保護者補助金について所得制限が導入されましたのが平成８年当時と考えております。","id":"exchange-013"},{"speaker":"浅野委員","kind":"質問・要望","question":"また幼稚園そのものですけれども、やはり小学校、中学校が義務教育ということで基本的に無料という、全部が無料というわけではないですけれども、そういう形になりつつある中で、就学前のお子さんたちにも負担を減らしていこうという動きが当然あるわけでありますので、ここら辺をかんがみながら、ある意味ではバランスのとれた形で、これからもこういうことは進めていっていただきたいと思うんですけれども。","respondent":"小林保育課長","answer":"ただ、基本的には、今、委員がご説明、ご意見いただきましたように、それぞれの園の教育方針が第一、また、毎日のことなので、住まいしているところのアクセスの状況等が大きなファクターになっているのかと思います。","id":"exchange-014"},{"speaker":"浅野委員","kind":"質問・要望","question":"そういう形で、さっきもお話しさせていただきましたとおり、やはりそれぞれのさまざまな考え方で幼稚園に入れられているということと、保護者の負担をできるだけ減らしていくということはこれからの趨勢だと思いますので、ぜひともこの件につきまして、バランスのとれた形で進めていっていただければと思いますので、これは要望になります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"保護者補助金の所得制限なんですけれども、平成８年から導入したということなんですけれども、この導入した考え方というのがどういうことで導入されたのかということを１つ教えていただきたいのと、あと、毎年この請願は上がっていますので、去年の議事録でも私立幼稚園の保育料というのが毎年３.２％から５％上がっているというふうなことが課長の説明の中にあったんですけれども、そういう点でいえば。","respondent":"小林保育課長","answer":"所得制限導入の考え方というのは、当時の新聞記事によりますと、一律の所得制限もなく、一律の支給は制度の想定しないところであり、むしろ不平等であるというような指摘もありというようなことで書かれておりますが、その趣旨というのは、先ほどご説明しましたように。","id":"exchange-016"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"多くの区が所得制限をつけないというふうなところでやっているというところなんですけれども、私は、ここの請願では所得制限の緩和をぜひしていただきたいというふうなことですので、先ほどからご答弁いただいているように、２人子供がいて４人家族で７３０万円といったら、本当に生活としては、決して所得制限を設けなければならない、そういうレベルではないと思うんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"堺委員","kind":"意見","question":"同じく、本日結論を出すということでお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-018"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"自民党としまして、ＰＴＡの方の保護者の方たちのお話もじかにお聞きしておりますし、また幼稚園からもいろいろなお話も聞いております。ただ、品川区としまして既にいろいろな対応はしている、そのことは我々も十分承知しておりますので、そのご要望の趣旨を採択したいということで、趣旨採択でお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"堺委員","kind":"質問","question":"公明党も、今のこの件につきましては、我々もいろいろな機会に関係者からもお話を伺っております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"飯沼委員","kind":"質問・要望","question":"生活がきびしくなっている中で、教育費が生活費を圧迫しているという、ここにも書かれていますが、十分理解をします。預かり保育の支援とか、保護者の皆さんの交流とか啓発を深めていくという意味でも、母の会への支援もご努力していただきたいなと、趣旨採択でお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"阿部委員","kind":"意見","question":"所得制限については、７３０万円という数字がいろいろ見方が分かれる数字だろうなと思います。ただ、ここで切るということではなくて、やはりもう少し公平感を感じられるような段階的な緩和ですとか、そうしたことも含めて今後も研究・検討をしていただければと思います。全体としては、趣旨採択ということでお願いしたいかと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-022"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今回、請願を出されたこの求める会の皆さんは、何年か前に都南病院跡地に特別養護老人ホームをつくってほしいという請願を出されて、６,５００筆ぐらい署名を集められて請願を出された皆さんなので、本当に身近なところに特別養護老人ホームをつくっていただきたいという強い願いを持っていらっしゃる皆さんで、特別養護老人ホームはかなわなかったけれども、高齢者施設ができるということで。","respondent":"冨岡高齢福祉課長","answer":"それから５月の国の考え方で、すべて軽費老人ホームというところで扱っていこうというふうになっておりまして、それは要は軽い費で、それは軽費老人ホームです。","id":"exchange-023"},{"speaker":"飯沼委員","kind":"意見","question":"ということは、補足給付が入っているところで、特別養護老人ホームの４段階以上の人はちょっと難しいけれども、３段階から２、１という人たちは国民年金で特別養護老人ホームが利用できるということは、さっき、ほかの軽費老人ホームの説明とか、あと高専賃とか高優賃と特定の施設をプラスした施設、そういったところが特別養護老人ホームのように介護も受けられる施設だと。","respondent":"冨岡高齢福祉課長","answer":"そういう意味のサービス費をどうとらえていくかといったことも含めますと、６万６,０００円ということはとてもおさまりきかないという内容です。","id":"exchange-024"},{"speaker":"飯沼委員","kind":"質問","question":"私は軽費老人ホームの中にケアハウスが含まれているという認識がなかったので、インターネットで見てみたら、軽費老人ホームとは、ケアハウスとはといって、こういうふうに書いてあったので、ここも教えてほしいんですが、身寄りのない、または家族との同居が困難な方々に低額な料金でご入居いただける、老人福祉法に基づく老人福祉施設ですということで、６０歳以上の方。","respondent":"冨岡高齢福祉課長","answer":"今回の部分につきましては、今後の高齢者の多様なニーズにおこたえするということの長期基本計画の中の一番最初の部分で位置づけて展開をしているというところで、時代時代を反映した対応ということで、名前的には似ておりますので。","id":"exchange-025"},{"speaker":"飯沼委員","kind":"質問・要望","question":"私の疑問には、あまり軽費老人ホームのことがよくわからないんですが、都南病院のケアハウスを利用しての今回の高齢者の施設なんですけれども、ここへの助成というかの制度がどうなっているのかを教えてほしいのと、あと、課長は大体２０万円前後とこの間、ずっとおっしゃっていらして、前回ですか、厚生委員会のときに私たちが大起エンゼルヘルプのところの資料。","respondent":"冨岡高齢福祉課長","answer":"このさらに詳細な数値につきましては、年が明けまして１月の委員会で、今度は入居の募集をするわけですので、そのときにはご説明ができるかなと思っているところです。","id":"exchange-026"},{"speaker":"飯沼委員","kind":"質問","question":"さっきの質問の中で、ケアハウスに対する助成の中身を教えてほしいんですが。","respondent":"冨岡高齢福祉課長","answer":"ケアハウスにつきましては、国から建設費の助成が出ているところです。","id":"exchange-027"},{"speaker":"飯沼委員","kind":"質問","question":"その建設費の助成が、都南の場合、幾らなのかということを教えてほしいのと、原小学校跡のこうほうえんのところの家賃助成のところなんですけれども、東京都の家賃補助と品川区助成に基づく法人独自の家賃軽減制度、この中身が、これは受けられる助成の金額というのは一律なのか、何かランクがあるのかどうか、これって協定がつくられるということですか。","respondent":"冨岡高齢福祉課長","answer":"これにつきましては、Ａタイプで５万円、Ｂタイプで１万円という形の助成をするということで協定を調整しています。これはケアハウスはちょっと今、手元に資料がございませんが、高齢者施設ということで、全体で国から７,７５０万円ということで入っております。","id":"exchange-028"},{"speaker":"飯沼委員","kind":"質問","question":"こうほうえんのところは、かなり東京都とまた独自の家賃軽減制度がついているので、この辺も大変大きいなと思うので、でも、これでもまだ国民年金では入れる金額では、Ａタイプの一番負担が少ないところで１４万１,２００円ということですけれども、でもかなり工夫をすると、いろいろなところで家賃の助成ができるなという、新しい試みというか、ケースであるなと思いますけれども。","respondent":"木下福祉高齢事業部長","answer":"それで、介護保険の中では基本的には介護保険の介護報酬を事業者としては収入として得るわけですが、利用者の負担金と介護報酬の部分で収支差額が出てまいりますので、今、厳しいという状況はありますけれども、収支差額が出てまいりますので、それが本来的には積み立てられて。","id":"exchange-029"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そういった面で、差のところを埋め合わせるような、私は例えば家賃助成とか、独自のものを考えていただきたいなと思うんですが、いかがでしょうか。","respondent":"木下福祉高齢事業部長","answer":"その結果、かなり低廉な利用料金の施設の提供ができたと考えていますので、現時点でのこの考え方で進めていきたいと考えています。","id":"exchange-030"},{"speaker":"鈴木（真）委員","kind":"質問","question":"逆に１点お聞きしたいのは、八潮南中学校のこれからの考え方の中で、跡地ですね、我々としては数多くの方が安い金額で入れる施設にしてほしいという、特別養護老人ホームという思いがありましたけれども、ある程度、今、区の方向性が出てきた中で、これから先、完成した時点で、概算で結構なんですけれども、どのぐらいで向こうを直したときに可能なのか、というのは。","respondent":"冨岡高齢福祉課長","answer":"それで、従来型個室ということで計算しますと、それがそっくり今後のになってまいりますので、今おっしゃった額で、利用者は２段階では４万円という、これは居住費全部含めて、粗い数字ですけれども、多床室だと３万７,０００円。","id":"exchange-031"},{"speaker":"阿部委員","kind":"質問・要望","question":"ちょっと教えていただきたいんですが、特別養護老人ホームの場合、ざっくりで構わないんですけれども、所得があまり高い方は逆に事実上、入れないとよく聞くんですが、大体どのくらいまでの方が入れているんでしょうか。","respondent":"冨岡高齢福祉課長","answer":"実態的には、やはり一番、第１段階の方が２割、３割ということで、そちらのある程度所得的には低い方が現実的には多くなっているです。","id":"exchange-032"},{"speaker":"阿部委員","kind":"質問","question":"当然、こういう低所得の方が入れる特別養護老人ホームなども用意しておかなきゃいけない。どれも増えていかなきゃいけないと思うんですけれども、今後、そのバランスというんですか、特別養護老人ホームはまだこのくらい欲しいとか、もうちょっと中堅層に対しての施設をこのぐらい欲しいとか、きっちり数字で出さなくても、今後の考え方みたいなものを教えていただけないですか。","respondent":"木下福祉高齢事業部長","answer":"そういう点でいくと、いい適地があったときに、どの制度を使ってやっていくのがいいのかということを具体的に精査して考えていくほうがいいだろうと思いますので、長期的に何カ所という、どちらを幾つずつというようなことをお話しするよりは。","id":"exchange-033"},{"speaker":"浅野委員","kind":"質問","question":"そういう中で、例えば今回の請願にあります、端的に聞きますけれども、国民年金でも入れるような利用料というのは、このような建て方をした場合は、制度をいろいろなことを駆使しても全くだめなのかということを１点お伺いしたいのと、逆に、今、部長からもお話があったとおり、そのような国民年金でも入れるような利用料を設定できる施設というのはどのような建て方、今。","respondent":"冨岡高齢福祉課長","answer":"それにつきまして、今の特別養護老人ホーム以外の制度を利用して、別の形であれ、施設をつくるとなると、その分を国民年金の程度の利用料にするということは財源の投入をしない限り無理ですので、施設的には難しいと考えております。","id":"exchange-034"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"何点かお聞きしたいんですが、まず、この都南病院跡地の高齢者施設は来年の４月からオープンになると思うんですけれども、原小学校の跡地は３月からということで１１月１１日から申し込みが始まりましたけれども、都南病院跡地の高齢者施設の申し込みというのは、１カ月おくれたから１カ月おくれで１２月からというわけじゃないんでしょうか。その点、３点お願いします。","respondent":"冨岡高齢福祉課長","answer":"その後に、１月２１日ので出せれば広報で出して、申し込みのご案内をしたいと思っていますので、一定期間を置いて、２月ぐらいには申し込みというような、詳細についてはまだこれからですけれども、そういうふうなスケジュールで進めたいと考えています。","id":"exchange-035"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そういうところで、区としてはニーズにこたえて、これからもケアホーム、高い利用料の施設をつくっていくというふうなことで言われていますけれども、私はどこでどんなニーズというふうなところが、こういうふうなケアホームのどんどん建てていくということになっていくのか、そのニーズの裏づけというのは何なのかということを１つ教えていただきたいと思います。","respondent":"冨岡高齢福祉課長","answer":"お申し込みの早いものですから、一応見込みでその部分についてはとりあえず発車をしていると、助成の額についてはそういう流れです。","id":"exchange-036"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"私は特別養護老人ホームが４９２名も申し込みながら、西五反田のケアホームは３０人ぐらいしか申し込めないと、五、六パーセントの人しか申し込めないという区民の実態の中で、区がニーズにこたえてケアホームをつくっていくんだというふうなことでずっと言われているわけですけれども、そのニーズというのはどういうところから来ているのかという、そのニーズの裏づけを聞かせていただきたいと。","respondent":"木下福祉高齢事業部長","answer":"都南についてもできないのかというお話がありましたけれども、そういう意味で、都南についてもそのような形で区は建設費のかなりの部分を持って、事業主負担は年間でいうと大体５５０万円をちょうだいする金額にしておりますのは、国と都の補助金を除いた残りの金額。","id":"exchange-037"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そうしたらやっぱりＡタイプと同じぐらいの、同じ時期にできる、区民からすると本当に同じ施設なわけですから、同じ料金でなければ納得いかないと思うんです。いろいろのところで聞いてみてください。ケアホームと特別養護老人ホーム、どちらが希望ですかといったら、特別養護老人ホームを建ててくださいという人のほうが必ず多いですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"だから、その平均というふうなことからすると、２３万円なんていうのは本当に高いほうで、前に比べて厚生年金の人が多くなるというけれども、厚生年金の人の年金はどんどん下がっていますので、そういう実態ではないというふうなところも改めて考えていただきたいと思います。それと、先ほどの、そうするとケアホーム、原小学校の跡地の建設に……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そういう点でも、私は区民の圧倒的なニーズというのであれば、圧倒的なニーズは特別養護老人ホームをつくってほしいというふうなことだと思いますし、先ほど新型特別養護老人ホームは所得制限はありません、所得の高い人から、厚生年金の方から低い人までみんなが入れるのが新型特別養護老人ホームで、施設そのものもケアホームと基本的には同じですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"堺委員","kind":"意見","question":"本日結論を出すということでお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-041"},{"speaker":"鈴木（真）委員","kind":"意見","question":"自民党としましては、都南病院の跡地の高齢者施設についての利用料につきましては、再三低い金額でお願いをしたいということは何回も主張はしております。希望としては、私どもももちろん同じように安くということはわかっておりますけれども、この請願の国民年金者でも入れる利用料にしてくださいという部分につきましては、申しわけないですが、採択できないという考え方をいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-042"},{"speaker":"堺委員","kind":"意見","question":"申し上げておきたいことは、公明党としても特別養護老人ホーム、あるいはこういうケアハウス等につきましても、高齢者施設、あるいは高齢者の方がご利用されるという視点からとらえますと、それは利用料が安いことにこしたことはないわけでありまして、なお、また希望としては、なるべくならば、利用者も安心して利用できるような料金設定にしてもらえるならば、なお一層ありがたいなとは思いますけれども。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-043"},{"speaker":"飯沼委員","kind":"質問・要望","question":"有料老人ホームとか、ケアホームとかが経済的な理由で利用できない、施設は無理だということになると、介護難民がますます増えてしまう。この間、区民のニーズであるということでケアホームをつくってきた。もう現実的に進んでいる施設なので、今できる対策ということを具体的に考えていただいて、この請願に添うような状況に持っていっていただきたいなと思いますので、採択を主張したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"阿部委員","kind":"質問・要望","question":"前提として、高齢者のための施設が数として足りていないということはあると思います。国の施策が新しく出ると、それだけで設定できる利用料金というのは変わってきますので、そういった意味では区だけではなくて、国に対してももっともっと充実した施策をどんどん出してほしいと思いますし、それに対する研究というのも当然区でも続けていっていただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"川西絹子議員の高齢者住宅の建設促進についてというところのご答弁の中に、小規模多機能に付属してというか、つけて高齢者の住宅を考えるといったご答弁があったかと思うので、ちょっとその辺を詳しく、メモが見つからなかったので、申しわけないんですが、その辺をもう一度というか、ご答弁をいただきたいのと、高齢者住宅に関して、今後、期待できるというか。","respondent":"永尾高齢事業課長、冨岡高齢福祉課長","answer":"高齢者人口は増加しておりまして、今後、そういう方に対しての体制、新しい高齢者住宅を建設していくことについて、今、検討をしていますが。今の小規模多機能型居宅介護施設ということで、併設ですが、これはあくまでも「など」というふうに書いてありますように、そういう介護施設を代表として申し上げたということで、併設を検討していると。","id":"exchange-046"},{"speaker":"飯沼委員","kind":"質問","question":"まだこれからというところの受けとめなんですけれども、高齢者住宅というのがどういう中身なのかというあたりを、わかっていることをもうちょっと伝えることができるんだったら教えてほしいのと、これから取得というところでは、今後の経緯のめどというか、どのくらいまでにはという考えがあるのかどうか、その辺も聞かせてください。","respondent":"永尾高齢事業課長","answer":"それと、あと今後の予定については、現在、土地の候補として都営大井林町跡地を考えているんですが、こちらにつきまして、まだ取得のめどは立っていない状態であります。ですので、この土地の取得が決定いたしましたら、検討に入っていきたいと考えております。","id":"exchange-047"},{"speaker":"飯沼委員","kind":"質問・要望","question":"高齢者住宅は本当に希望者が多いので、頑張って進めていただきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"},{"speaker":"鈴木（真）委員","kind":"質問","question":"先ほど希望の中で２階以上が多いと言ったんですが、高齢者の方は２階以下だよね。そこがちょっと気になった。私もここは何回か質問しているので、同じような話なんですけれども、お願いします。","respondent":"永尾高齢事業課長","answer":"申しわけありませんでした。２階以上は希望しないです。どうも失礼いたしました。","id":"exchange-049"},{"speaker":"鈴木（ひ）副委員長","kind":"確認","question":"高齢者住宅なんですけれども、２１９戸と同じような高齢者住宅という、シルバーピアの高齢者住宅と考えていいんでしょうか。高専賃とか、そういうものではなくて、シルバーピアの今までずっと、今、１２月１日から５日まで募集が始まりますけれども、その高齢者住宅が増える、その高齢者住宅を増やすという考え方でいいのか、そこだけ確認させてください。","respondent":"永尾高齢事業課長","answer":"高齢者住宅としての考え方は今までと同様ですけれども、制度の使い道として、高優賃を使うなどのことを今現在考えているところです。","id":"exchange-050"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"高優賃というと、近傍家賃の設定というふうなことになってきますよね。そこら辺のところが、私はぜひ所得の少ない人が対象になるような、今までの高齢者住宅を拡大するという形での検討をぜひ、要望させていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-051"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/481603?Template=document&Id=3222#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":37701,"voices":121}}]);
